fn shell_prefix(text: &str) -> Option<(&str, bool)> {
    text.strip_prefix("!!")
        .map(|command| (command, true))
        .or_else(|| text.strip_prefix('!').map(|command| (command, false)))
}
fn local_command_phase(command: &ParsedLocalCommand) -> LocalCommandPhase {
    command.phase()
}
impl Host {
    // This queue is strictly local: no user/context record, no steering receipt,
    // and no automatic replay of a partly executed control after resume.
    fn receive_parsed_local_command(
        &mut self,
        id: &str,
        parsed: ParsedLocalCommand,
        busy: bool,
    ) -> Result<()> {
        if id.is_empty() || self.ids.contains(id) {
            self.event(
                "rejected",
                json!({"command_id":id,"error":"missing or duplicate command ID"}),
            );
            return Ok(());
        }
        let name = parsed.name.clone();
        // Never journal arbitrary arguments (notably login/config credentials).
        self.journal.append(
            "local_command_accepted",
            json!({
            "command_id":id,"command":name,"resume_policy":"never-replay"}),
        )?;
        self.ids.insert(id.to_owned());
        self.event("accepted", json!({"command_id":id}));
        let phase = if busy {
            local_command_phase(&parsed)
        } else {
            LocalCommandPhase::Immediate
        };
        let command = LocalCommand {
            id: id.to_owned(),
            parsed,
            phase,
        };
        if phase == LocalCommandPhase::Immediate {
            self.finish_local_command(command, busy)?;
        } else {
            self.event(
                "notice",
                json!({"text":format!("{name}: local command queued for the next cell boundary.")}),
            );
            self.frontend.queue_command(command);
        }
        Ok(())
    }
    fn finish_local_command(&mut self, command: LocalCommand, busy: bool) -> Result<()> {
        let parsed = &command.parsed;
        let args = parsed.args.as_str();
        let result = (|| -> Result<bool> {
            self.reload_auth()?;
            if busy && parsed.interruption() == CommandInterruption::CancelActive {
                INTERRUPT.store(true, std::sync::atomic::Ordering::SeqCst);
                return Ok(true);
            }
            if busy && parsed.interruption() == CommandInterruption::QuitActive {
                self.bg_guard(transition_cancel(args)?)?;
                self.exit_requested = true;
                INTERRUPT.store(true, std::sync::atomic::Ordering::SeqCst);
                return Ok(false);
            }
            // No discovery HTTP/runtime reentry during an in-flight request.
            if busy && parsed.kind == LocalCommandKind::Models {
                self.ui_json("Usable models (cached)", &json!(self.matching_models(args)));
                return Ok(true);
            }
            if busy && parsed.kind == LocalCommandKind::Model {
                if let Some(query) = &parsed.busy_model_list_query {
                    self.ui_json(
                        "Usable models (cached)",
                        &json!(self.matching_models(query.trim())),
                    );
                } else if args.is_empty() {
                    self.ui_text(&self.provider.model);
                } else {
                    self.choose_model(args)?;
                }
                return Ok(true);
            }
            self.execute_local_command(parsed)
        })();
        match result {
            Ok(keep_running) => {
                if !keep_running {
                    self.exit_requested = true;
                }
                self.journal
                    .append("local_command_completed", json!({"command_id":command.id}))?;
                self.event("completed", json!({"command_id":command.id,"status":"ok"}));
                self.event("state", self.state_payload());
            }
            Err(error) => {
                self.event(
                    "error",
                    json!({"command_id":command.id,"error":error.to_string()}),
                );
                if self.journal.failed {
                    return Err(error);
                }
            }
        }
        Ok(())
    }
    fn cancel_local_commands(&mut self) -> Result<()> {
        while let Some(command) = self.frontend.pop_command() {
            self.journal.append(
                "local_command_cancelled",
                json!({
                "command_id":command.id,"reason":"quit"}),
            )?;
            self.event(
                "completed",
                json!({"command_id":command.id,"status":"cancelled"}),
            );
        }
        Ok(())
    }
    fn has_after_turn_command(&self) -> bool {
        self.frontend.has_after_turn_command()
    }
    fn drain_local_commands(&mut self, after_turn: bool) -> Result<()> {
        while self
            .frontend
            .next_command_phase()
            .is_some_and(|phase| after_turn || phase == LocalCommandPhase::CellBoundary)
        {
            let command = self.frontend.pop_command().unwrap();
            self.finish_local_command(command, !after_turn)?;
            if self.exit_requested {
                break;
            }
        }
        Ok(())
    }
    fn route_busy_command(&mut self, command: NativeCommand) -> Result<bool> {
        if let Some(parsed) = command.args.local.clone() {
            self.receive_parsed_local_command(&command.id, parsed, true)?;
            return Ok(true);
        }
        if command.kind != NativeCommandKind::Shell {
            return Ok(false);
        }
        let inputs = self.cell_input_records.clone();
        let revision = self.context.revision();
        let result = self.dispatch_command(command.clone());
        let selected = command.args.visible && self.context.revision() != revision;
        if selected {
            self.frontend.admit_visible_change()?;
        } else {
            self.cell_input_records = inputs;
        }
        if let Err(error) = result {
            self.event(
                "error",
                json!({"command_id":command.id,"error":error.to_string()}),
            );
            if self.journal.failed {
                return Err(error);
            }
        }
        Ok(true)
    }
}
fn transition_cancel(args: &str) -> Result<bool> {
    match args.trim() {
        "" => Ok(false),
        "--cancel-tasks" => Ok(true),
        _ => Err("Only --cancel-tasks is accepted here".into()),
    }
}
fn transition_query(args: &str) -> Result<(&str, bool)> {
    let (query, cancel) = if let Some(query) = args.strip_suffix("--cancel-tasks") {
        if !query.ends_with(char::is_whitespace) {
            return Err("Separate --cancel-tasks from the session path".into());
        }
        (query.trim(), true)
    } else {
        (args.trim(), false)
    };
    if query.is_empty() {
        return Err("Usage: /resume <path or fuzzy session> [--cancel-tasks]".into());
    }
    Ok((query, cancel))
}
impl Host {
    fn ui_background_command(&mut self, command: &str, args: &str) -> Result<()> {
        let id = format!("ui{}", self.journal.seq);
        let words: Vec<_> = args.split_whitespace().collect();
        let mut v=match command{
            "/tasks" if words.len()<=1=>json!({"kind":"task_list","state":words.first()}),
            "/task"=>match words.as_slice(){
                [task]=>json!({"kind":"task_get","task_id":task}),
                ["logs",task]=>json!({"kind":"task_logs","task_id":task,"stream":"both"}),
                ["logs",task,stream] if ["stdout","stderr","both"].contains(stream)=>json!({"kind":"task_logs","task_id":task,"stream":stream}),
                ["kill",task]=>json!({"kind":"task_kill","task_id":task,"force":false}),
                ["kill",task,"--force"]=>json!({"kind":"task_kill","task_id":task,"force":true}),
                _=>return Err("Usage: /task <id> | /task logs <id> [stdout|stderr|both] | /task kill <id> [--force]".into())
            },
            "/bg"=>{
                let (kind,source)=args.split_once(char::is_whitespace).ok_or("Usage: /bg shell|python <source>")?;
                if !["shell","python"].contains(&kind)||source.trim().is_empty(){return Err("Usage: /bg shell|python <source>".into());}
                json!({"kind":"bg_run","task_kind":kind,"source":source.trim_start()})
            },
            "/wakeups" if words.is_empty()=>json!({"kind":"wakeup_list"}),
            "/wakeup"=>match words.as_slice(){
                ["cancel",wake]=>json!({"kind":"wakeup_cancel","wakeup_id":wake}),
                ["run",wake]=>json!({"kind":"wakeup_run","wakeup_id":wake}),
                _=>return Err("Usage: /wakeup cancel|run <id>".into())
            },
            _=>return Err("Unexpected arguments; /help lists background commands".into())
        };
        let previous: HashSet<_> = self.scheduler.task_ids().cloned().collect();
        v["id"] = json!(id);
        let command = NativeCommand::decode(v, NativeCommandOrigin::Internal);
        self.dispatch_command(command.clone())?;
        let result = match command.kind {
            NativeCommandKind::TaskList => {
                self.bg_list(command.args.task_state.require()?.as_deref())?
            }
            NativeCommandKind::BgRun => self
                .scheduler
                .new_task(&previous)
                .ok_or("background launch did not create a task")?,
            NativeCommandKind::TaskGet | NativeCommandKind::TaskKill => {
                self.bg_get(command.args.task_id.require()?)?
            }
            NativeCommandKind::TaskLogs => {
                let metadata = self.bg_get(command.args.task_id.require()?)?;
                let mut logs = json!({"id":metadata["id"]});
                for stream in ["stdout", "stderr"] {
                    if !command.args.stream.require()?.includes(stream) {
                        continue;
                    }
                    let index = metadata[stream]["index"]
                        .as_u64()
                        .ok_or("task has no output reference")?
                        as usize;
                    let preview = self.ui_stream_preview(stream, index)?;
                    logs[stream] = metadata[stream].clone();
                    logs[stream]["preview_truncated"] = json!(
                        preview.chars().count()
                            < metadata[stream]["chars"].as_u64().unwrap_or(0) as usize
                    );
                    logs[stream]["preview"] = json!(preview);
                }
                if !self.json {
                    self.ui_text(&human_background_result(NativeCommandKind::TaskLogs, &logs));
                }
                return Ok(());
            }
            _ => self.wakeup_list()?,
        };
        if self.json {
            self.ui_json("Background management", &result);
        } else {
            self.ui_text(&human_background_result(command.kind, &result));
        }
        Ok(())
    }
    fn ui_stream_preview(&self, stream: &str, index: usize) -> Result<String> {
        let bytes =
            self.history
                .preview_bytes(RecordCollection::decode(stream)?, index, &self.journal)?;
        Ok(String::from_utf8_lossy(&bytes)
            .lines()
            .take(12)
            .collect::<Vec<_>>()
            .join("\n")
            .chars()
            .take(4000)
            .collect())
    }
}
// =============================================================================
// CLI and interactive terminal
// =============================================================================

fn main() {
    if let Err(e) = cli() {
        for line in terminal_wrap(&e.to_string(), terminal_width()).0 {
            eprintln!("{line}");
        }
        std::process::exit(1);
    }
}
fn cli() -> Result<()> {
    // Parse every option before touching storage or starting Python. There are
    // deliberately no positional prompts, key arguments or extension flags.
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (mut help, mut version, mut spec, mut json_mode, mut json_input, mut no_model) =
        (false, false, false, false, false, false);
    let (mut model, mut effort, mut resume): (Option<String>, Option<String>, Option<PathBuf>) =
        (None, None, None);
    let mut i = 0;
    while i < args.len() {
        let flag = args[i].as_str();
        match flag{
            "--help"|"-h"=>help=true,"--version"|"-V"=>version=true,"--spec"=>spec=true,
            "--json"=>json_mode=true,"--json-input"=>json_input=true,"--no-model"=>no_model=true,
            "--model"|"--effort"|"--session"|"--resume"=>{
                let value=args.get(i+1).filter(|v|!v.is_empty()&&!v.starts_with('-'))
                    .ok_or_else(||format!("{flag} requires a value; run --help for usage"))?;
                match flag{
                    "--model"=>{if model.replace(value.clone()).is_some(){return Err("--model specified more than once".into());}},
                    "--effort"=>{
                        let value=value.to_lowercase();
                        if !["off","minimal","low","medium","high","xhigh","max"].contains(&value.as_str()){
                            return Err("Unsupported effort: off, minimal, low, medium, high, xhigh or max (model-dependent)".into());
                        }
                        if effort.replace(value).is_some(){return Err("--effort specified more than once".into());}
                    },
                    _=>{if resume.replace(PathBuf::from(value)).is_some(){return Err("Use only one --session or --resume path".into());}}
                }
                i+=1;
            },
            _=>return Err(format!("Unexpected argument {flag}; run --help for supported options (no positional prompts)").into())
        }
        i += 1;
    }
    if help {
        ui_text("Usage: py [options]\nPersistent ordinary Python + a Python-writing model. No sandbox.\n\n--model <provider/id or unique fuzzy query>: choose a known/configured model\n--effort <off|minimal|low|medium|high|xhigh|max>: reasoning preference (supported levels depend on the model)\n--session <path>, --resume <path>: restore an existing journal; fresh Python, no replay\n--no-model: local Python/shell mode, no automatic model turns\n--json: write versioned JSONL events to stdout instead of human previews\n--json-input: read JSONL commands from stdin instead of the editor\n--spec: print the embedded specification and coverage ledger\n--help, -h: show this help without starting Python or creating files\n--version, -V: show the version without creating files\n\nJSON input and output are independent; combine --json --json-input for automation.\nPY_HOME chooses global state storage (default ~/.py); PY_MODEL/config.json choose defaults.\nCLI model/effort override restored session settings and are saved in that session, not global defaults.\nExplicit /model and /effort (/thinking) changes atomically save config.json defaults; queries do not.\nJSON kind=model with model=<query>, or kind=effort/thinking with effort=<level>, saves the same defaults.\nOmit the value to query; call-local agent.llm options never change defaults.\nInteractive: /help, /login, /model list, /new, /resume. Tab fuzzily completes.\n! / @: hidden shell / Python; !! / @@: visible. Empty prompts are ignored.\nThere are no positional prompts or CLI API-key flags; use hidden /login entry.");
        return Ok(());
    }
    if version {
        println!("py {} (transition)", env!("CARGO_PKG_VERSION"));
        return Ok(());
    }
    if spec {
        print!("{SPEC}");
        return Ok(());
    }
    if let Some(path) = &resume {
        if !path.is_file() {
            return Err(format!("Session file does not exist: {}", path.display()).into());
        }
    }
    install_signals();
    let home = std::env::var_os("PY_HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(std::env::var_os("HOME").unwrap_or_default()).join(".py"));
    let mut host = Host::new(
        home,
        resume,
        json_mode,
        no_model,
        model.as_deref(),
        effort.as_deref(),
    )?;
    host.announce_ready();
    if json_input {
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            for line in io::stdin().lock().lines() {
                match line {
                    Ok(s) => match serde_json::from_str::<Value>(&s) {
                        Ok(v) => {
                            if tx
                                .send(NativeCommand::decode(v, NativeCommandOrigin::Native))
                                .is_err()
                            {
                                break;
                            }
                        }
                        Err(e) => {
                            let _=tx.send(NativeCommand::decode(json!({"id":format!("bad{}",now_ms()),"kind":"invalid","error":e.to_string()}), NativeCommandOrigin::Native));
                        }
                    },
                    Err(_) => break,
                }
            }
        });
        host.incoming = Some(rx);
        loop {
            if host.exit_requested {
                break;
            }
            INTERRUPT.store(false, std::sync::atomic::Ordering::SeqCst);
            host.service_background()?;
            let command = if let Some(v) = host.pending.pop_front() {
                v
            } else {
                match host
                    .incoming
                    .as_ref()
                    .unwrap()
                    .recv_timeout(std::time::Duration::from_millis(25))
                {
                    Ok(v) => v,
                    Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
                    Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                        if let Err(e) = host.dispatch_wakeups() {
                            host.event("error", json!({"error":e.to_string()}));
                        }
                        continue;
                    }
                }
            };
            INTERRUPT.store(false, std::sync::atomic::Ordering::SeqCst);
            let command_id = command.id.clone();
            match host.dispatch_command(command) {
                Ok(false) => break,
                Ok(true) => {}
                Err(e) => host.event(
                    "error",
                    json!({"command_id":command_id,"error":e.to_string()}),
                ),
            }
        }
    } else {
        use rustyline::history::History;
        let mut editor_history = rustyline::history::DefaultHistory::new();
        let history = host.home.join("editor-history");
        let _ = editor_history.load(&history);
        loop {
            if host.exit_requested {
                break;
            }
            for line in host.frontend.pending_editor_history() {
                editor_history.add(line.as_str())?;
            }
            // Steering captured by the busy prompt is dispatched here if the
            // active turn ended before consuming it at a cell boundary.
            if let Some(command) = host.pending.pop_front() {
                let id = command.id.clone();
                if let Err(error) = host.dispatch_command(command) {
                    host.event("error", json!({"command_id":id,"error":error.to_string()}));
                }
                continue;
            }
            // Idle interrupts clear the editor, never cancel a future operation.
            INTERRUPT.store(false, std::sync::atomic::Ordering::SeqCst);
            host.reload_auth()?;
            let prompt = if host.json { "" } else { "> " };
            let models = host.usable_models();
            let providers = host.login_providers();
            let current_model = host.provider.model.clone();
            let mut helper = Completion::from_worker(
                host.execution.worker_mut(),
                models,
                host.home.clone(),
                current_model,
                providers,
            )?;
            helper.catalog.task_ids = host.scheduler.task_ids().cloned().collect();
            helper.catalog.wakeup_ids = host.scheduler.wakeup_ids().cloned().collect();
            host.frontend.seed_editor(
                helper.catalog.clone(),
                editor_history.iter().cloned().collect(),
            );
            let line = match if terminal_editor_available(host.json) {
                terminal_readline(
                    &helper,
                    &editor_history.iter().cloned().collect::<Vec<_>>(),
                    if host.json { 2 } else { 1 },
                    &mut host,
                )
            } else {
                serviceable_readline(&helper, prompt, &mut host)
            } {
                Ok(s) => s,
                Err(rustyline::error::ReadlineError::Interrupted) => {
                    INTERRUPT.store(false, std::sync::atomic::Ordering::SeqCst);
                    continue;
                }
                Err(rustyline::error::ReadlineError::Eof) => break,
                Err(e) => return Err(e.into()),
            };
            INTERRUPT.store(false, std::sync::atomic::Ordering::SeqCst);
            if line.trim().is_empty() {
                continue;
            }
            // Never persist authentication commands, let alone an accidentally
            // pasted credential. Keys are accepted only by the hidden tty prompt.
            if !line.trim_start().starts_with("/login") && !line.trim_start().starts_with("/config")
            {
                editor_history.add(line.as_str())?;
                host.frontend.remember_editor_line(&line);
            }
            if line.starts_with('/') {
                match host.ui_command(line.trim()) {
                    Ok(false) => break,
                    Ok(true) => {}
                    Err(e) => host.event("error", json!({"error":e.to_string()})),
                }
                continue;
            }
            let id = format!("ui{}", host.journal.seq);
            let v = if let Some(s) = line.strip_prefix("!!") {
                json!({"id":id,"kind":"shell","command":s,"visible":true,"terminal_controls":true})
            } else if let Some(s) = line.strip_prefix("!") {
                json!({"id":id,"kind":"shell","command":s,"terminal_controls":true})
            } else if let Some(s) = line.strip_prefix("@@") {
                json!({"id":id,"kind":"python","source":s,"visible":true})
            } else if let Some(s) = line.strip_prefix("@") {
                json!({"id":id,"kind":"python","source":s})
            } else {
                json!({"id":id,"kind":"submit","text":line})
            };
            match host.dispatch_command(NativeCommand::decode(v, NativeCommandOrigin::Terminal)) {
                Ok(false) => break,
                Ok(true) => {}
                Err(e) => host.event("error", json!({"error":e.to_string()})),
            }
        }
        for line in host.frontend.pending_editor_history() {
            editor_history.add(line.as_str())?;
        }
        editor_history.save(&history)?;
        if history.exists() {
            fs::set_permissions(
                &history,
                std::os::unix::fs::PermissionsExt::from_mode(0o600),
            )?;
        }
    }
    host.bg_shutdown()?;
    Ok(())
}

// One renderer owns the working footer. Agent events are inserted above it;
// keyboard edits and status ticks share its lock, never an opaque canonical
// tty buffer. The full draft (including cursor/undo) survives every transition.
#[derive(Default)]
struct BusyEditorCache {
    catalog: Option<CompletionCatalog>,
    history: Vec<String>,
    pending_history: Vec<String>,
    refreshed: Option<std::time::Instant>,
}
impl BusyEditorCache {
    fn remember(&mut self, line: &str) {
        if !editor_history_safe(line) || self.history.last().is_some_and(|old| old == line) {
            return;
        }
        self.history.push(line.to_owned());
        self.pending_history.push(line.to_owned());
        if self.history.len() > 100 {
            self.history.remove(0);
        }
        if self.pending_history.len() > 100 {
            self.pending_history.remove(0);
        }
    }
}
fn editor_history_safe(line: &str) -> bool {
    !line.trim().is_empty()
        && !line.trim_start().starts_with("/login")
        && !line.trim_start().starts_with("/config")
}
impl TerminalFrontend {
    fn seed_editor(&mut self, catalog: CompletionCatalog, history: Vec<String>) {
        let mut cache = self.editor_cache.lock().unwrap();
        cache.catalog = Some(catalog);
        cache.history = history;
        cache.refreshed = Some(std::time::Instant::now());
    }
    fn pending_editor_history(&self) -> Vec<String> {
        std::mem::take(&mut self.editor_cache.lock().unwrap().pending_history)
    }
    fn remember_editor_line(&self, line: &str) {
        self.editor_cache.lock().unwrap().remember(line);
    }
}
// Both frontends own different input lifetimes, but share the complete picker
// model and presentation. Query editing never changes the underlying draft.
struct PickerState {
    choices: Vec<rustyline::completion::Pair>,
    query: String,
    filtered: Vec<usize>,
    selected: usize,
}
enum PickerAction {
    Append(String),
    Backspace,
    Clear,
    EraseWord,
    Next,
    Previous,
    Accept,
    Cancel,
    Ignore,
}
enum PickerDecision {
    Changed,
    Accepted(String),
    Cancelled,
    Unchanged,
}
impl PickerAction {
    fn from_edit_key(key: EditKey) -> Self {
        match key {
            EditKey::Text(text) => Self::Append(text),
            EditKey::Paste(text) => Self::Append(normalize_picker_paste(&text)),
            EditKey::Byte(13 | 10) => Self::Accept,
            EditKey::Byte(27 | 4) => Self::Cancel,
            EditKey::Byte(9 | 14) => Self::Next,
            EditKey::Byte(16) => Self::Previous,
            EditKey::Byte(8 | 127) => Self::Backspace,
            EditKey::Byte(21) => Self::Clear,
            EditKey::Byte(23) => Self::EraseWord,
            EditKey::Byte(byte) if (32..127).contains(&byte) => {
                Self::Append((byte as char).to_string())
            }
            EditKey::Sequence(value) => match value.as_str() {
                "escape" => Self::Cancel,
                "alt:enter" | "shift:enter" => Self::Accept,
                "[A" | "OA" | "[Z" => Self::Previous,
                "[B" | "OB" => Self::Next,
                _ => Self::Ignore,
            },
            _ => Self::Ignore,
        }
    }
}
// Clipboard data is one query edit, never navigation or selection. Keep this
// normalization identical for the editor-owned and standalone picker readers.
fn normalize_picker_paste(text: &str) -> String {
    let text: String = text
        .chars()
        .map(|c| if c.is_whitespace() { ' ' } else { c })
        .filter(|c| !c.is_control())
        .collect();
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}
impl PickerState {
    fn new(choices: Vec<rustyline::completion::Pair>, query: &str) -> Self {
        let query: String = query
            .chars()
            .filter(|c| !c.is_control())
            .take(512)
            .collect();
        let filtered = picker_filter(&choices, &query);
        Self {
            choices,
            query,
            filtered,
            selected: 0,
        }
    }
    fn choice(&self) -> Option<&rustyline::completion::Pair> {
        self.filtered
            .get(self.selected)
            .map(|index| &self.choices[*index])
    }
    fn apply(&mut self, action: PickerAction) -> PickerDecision {
        let edited = match action {
            PickerAction::Accept => {
                return self
                    .choice()
                    .map(|choice| PickerDecision::Accepted(choice.replacement.clone()))
                    .unwrap_or(PickerDecision::Unchanged)
            }
            PickerAction::Cancel => return PickerDecision::Cancelled,
            PickerAction::Next | PickerAction::Previous => {
                if self.filtered.is_empty() {
                    return PickerDecision::Unchanged;
                }
                self.selected = if matches!(action, PickerAction::Next) {
                    (self.selected + 1) % self.filtered.len()
                } else {
                    (self.selected + self.filtered.len() - 1) % self.filtered.len()
                };
                return PickerDecision::Changed;
            }
            PickerAction::Append(text) => {
                let text: String = text
                    .chars()
                    .map(|c| if c.is_whitespace() { ' ' } else { c })
                    .filter(|c| !c.is_control())
                    .collect();
                let room = 512usize.saturating_sub(self.query.chars().count());
                self.query.extend(text.chars().take(room));
                true
            }
            PickerAction::Backspace => {
                self.query.pop();
                true
            }
            PickerAction::Clear => {
                self.query.clear();
                true
            }
            PickerAction::EraseWord => {
                while self.query.ends_with(char::is_whitespace) {
                    self.query.pop();
                }
                while !self.query.is_empty() && !self.query.ends_with(char::is_whitespace) {
                    self.query.pop();
                }
                true
            }
            PickerAction::Ignore => false,
        };
        if edited {
            self.filtered = picker_filter(&self.choices, &self.query);
            self.selected = 0;
            PickerDecision::Changed
        } else {
            PickerDecision::Unchanged
        }
    }
    fn layout(&self, width: usize, slots: usize) -> PickerLayout {
        PickerLayout::new(
            &self.choices,
            &self.query,
            &self.filtered,
            self.selected,
            width,
            slots,
        )
    }
}
struct PickerLayout {
    lines: Vec<(String, &'static str)>,
    query_row: usize,
    cursor_column: usize,
}
impl PickerLayout {
    fn new(
        choices: &[rustyline::completion::Pair],
        query: &str,
        filtered: &[usize],
        selected: usize,
        width: usize,
        slots: usize,
    ) -> Self {
        let mut lines = if slots == 2 {
            vec![format!("Fuzzy select · {query}")]
        } else {
            vec![
                "Fuzzy select — Enter picks".into(),
                format!("Find: {query}"),
            ]
        };
        if slots >= 6 {
            lines.push("↑↓/Tab move · Esc cancels".into());
        }
        let footer = usize::from(slots >= 5);
        let available = slots.saturating_sub(lines.len() + footer).max(1);
        let start = selected
            .saturating_sub(available / 2)
            .min(filtered.len().saturating_sub(available));
        if filtered.is_empty() {
            lines.push("No matches — edit query".into());
        } else {
            for (position, index) in filtered.iter().enumerate().skip(start).take(available) {
                lines.push(format!(
                    "{}{}",
                    if position == selected { "→ " } else { "  " },
                    choices[*index].display
                ));
            }
        }
        if footer > 0 {
            lines.push(format!(
                "{}/{}",
                if filtered.is_empty() { 0 } else { selected + 1 },
                filtered.len()
            ));
        }
        let lines = (0..slots)
            .map(|index| {
                let line = lines.get(index).map(String::as_str).unwrap_or("");
                let style = if index == 0 {
                    "1;36"
                } else if index == 1 && slots > 2 {
                    "36"
                } else if line.starts_with("→ ") {
                    "1;7"
                } else if line.starts_with("  ") {
                    "0"
                } else {
                    "2"
                };
                (picker_clip(line, width.saturating_sub(1).max(1)), style)
            })
            .collect();
        let query_row = usize::from(slots > 2);
        let query_line = if slots == 2 {
            format!("Fuzzy select · {}", terminal_safe(query))
        } else {
            format!("Find: {}", terminal_safe(query))
        };
        Self {
            lines,
            query_row,
            cursor_column: terminal_columns(&query_line).min(width.saturating_sub(1)),
        }
    }
}
fn picker_slots(height: usize, prompt_rows: usize) -> usize {
    height
        .saturating_sub(prompt_rows)
        .min((height / 2).max(2))
        .min(8)
}
fn completion_picker(
    catalog: &CompletionCatalog,
    line: &str,
    cursor: usize,
    start: usize,
) -> rustyline::Result<PickerState> {
    let (_, choices) = catalog.candidates(line, cursor, true)?;
    let prefix = &line[..cursor];
    let python = prefix.starts_with('@');
    let offset = if prefix.starts_with("@@") || prefix.starts_with("!!") {
        2
    } else if python || prefix.starts_with('!') {
        1
    } else {
        0
    };
    let (_, quote) = completion_token(prefix, offset);
    Ok(PickerState::new(
        choices,
        &completion_unescape(&prefix[start..], python, quote),
    ))
}
struct BusyCompletionMenu {
    original: EditBuffer,
    start: usize,
    end: usize,
    picker: PickerState,
}
enum BusyEditResult {
    None,
    Submit(String, String),
    Interrupt,
}
