// Codex device/protocol constants follow the Pig pin in SPEC; own client identity.
// Browser OAuth uses the Pi pin; WebSocket transport and implicit retries are not provided.
const CODEX_CLIENT_ID: &str = "app_EMoamEEZ73f0CkXaXp7hrann";
fn provider_alias(provider: &str) -> &str {
    if provider == "codex" {
        "openai-codex"
    } else {
        provider
    }
}
fn codex_token_value(body: &Value) -> Result<Value> {
    let access = oauth_token(body, "access_token")?;
    let refresh = oauth_token(body, "refresh_token")?;
    let seconds = body["expires_in"]
        .as_f64()
        .filter(|s| s.is_finite() && *s > 0.0 && *s <= 31536000.0)
        .ok_or("Codex token response has invalid expiry")?;
    let pieces: Vec<_> = access.split('.').collect();
    if pieces.len() != 3 {
        return Err("Codex access token has invalid account metadata".into());
    }
    let bytes = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(pieces[1].trim_end_matches('='))
        .map_err(|_| "Codex access token has invalid account metadata")?;
    let claims: Value = serde_json::from_slice(&bytes)
        .map_err(|_| "Codex access token has invalid account metadata")?;
    // Decode for account routing only, not JWT signature verification.
    let account = claims["https://api.openai.com/auth"]["chatgpt_account_id"]
        .as_str()
        .filter(|s| !s.is_empty() && s.len() <= 512 && s.bytes().all(|c| (33..=126).contains(&c)))
        .ok_or("Codex access token lacks valid account ID")?;
    Ok(json!({"type":"oauth","access":access,"refresh":refresh,
        "expires":now_ms() as u64+(seconds*1000.0) as u64,"accountId":account}))
}
impl Host {
    fn auth_lock(&mut self) -> Result<File> {
        self.auth_lock_until(None)
    }
    fn auth_checkpoint(&mut self, deadline: Option<std::time::Instant>) -> Result<()> {
        if self.codex_cancel("auth")? {
            return Err("authentication cancelled; credentials unchanged".into());
        }
        if deadline.is_some_and(|until| std::time::Instant::now() >= until) {
            return Err("browser login timed out; credentials unchanged".into());
        }
        Ok(())
    }
    fn auth_lock_until(&mut self, deadline: Option<std::time::Instant>) -> Result<File> {
        let file = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .mode(0o600)
            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
            .open(self.home.join("auth.lock"))?;
        loop {
            if deadline.is_some() {
                self.auth_checkpoint(deadline)?;
            }
            if unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) } == 0 {
                if deadline.is_some() {
                    self.auth_checkpoint(deadline)?;
                }
                return Ok(file);
            }
            let error = io::Error::last_os_error();
            if error.kind() != io::ErrorKind::WouldBlock
                && error.kind() != io::ErrorKind::Interrupted
            {
                return Err(error.into());
            }
            self.auth_checkpoint(deadline)?;
            std::thread::sleep(std::time::Duration::from_millis(15));
        }
    }
    fn reload_auth(&mut self) -> Result<()> {
        let _lock = self.auth_lock()?;
        self.provider
            .accept_auth(load_json(&self.home.join("auth.json"))?);
        Ok(())
    }
    fn store_credential(&mut self, provider: &str, credential: Option<Value>) -> Result<()> {
        self.store_credential_until(provider, credential, None)
    }
    fn store_credential_until(
        &mut self,
        provider: &str,
        credential: Option<Value>,
        deadline: Option<std::time::Instant>,
    ) -> Result<()> {
        let _lock = self.auth_lock_until(deadline)?;
        let path = self.home.join("auth.json");
        let mut auth = load_json(&path)?;
        let map = auth.as_object_mut().ok_or("invalid auth config")?;
        let provider = provider_alias(provider);
        if let Some(value) = credential {
            map.insert(provider.into(), value);
        } else {
            map.remove(provider);
        }
        if deadline.is_some() {
            self.auth_checkpoint(deadline)?;
        }
        // Successful atomic write is the commit boundary. Cancellation arriving
        // after this checkpoint cannot promise rollback of an already-saved login.
        write_private_json(&path, &auth)?;
        self.provider.accept_auth(auth);
        Ok(())
    }
    fn codex_cancel(&mut self, operation: &str) -> Result<bool> {
        Ok(self
            .pump_control(WaitPolicy::Provider { operation })?
            .cancelled)
    }
    fn codex_wait<T>(
        &mut self,
        future: impl std::future::Future<Output = Result<T>>,
        operation: &str,
    ) -> Result<T> {
        ProviderClient::wait_codex(future, operation, self)
    }
    fn codex_http(&mut self, request: reqwest::RequestBuilder) -> Result<(u16, Value)> {
        self.codex_wait(
            async {
                let mut response = request
                    .send()
                    .await
                    .map_err(|_| "Codex authentication network error")?;
                let status = response.status().as_u16();
                let mut bytes = Vec::new();
                while let Some(chunk) = response
                    .chunk()
                    .await
                    .map_err(|_| "Codex authentication network error")?
                {
                    if bytes.len() + chunk.len() > 1048576 {
                        return Err("Codex authentication response exceeds limit".into());
                    }
                    bytes.extend_from_slice(&chunk);
                }
                let body = match serde_json::from_slice(&bytes) {
                    Ok(body) => body,
                    // Pig treats device polling 403/404 as pending even with an
                    // empty/non-JSON body. Other callers still reject these statuses.
                    Err(_) if status == 403 || status == 404 => Value::Null,
                    Err(_) => return Err("Codex authentication returned invalid JSON".into()),
                };
                Ok((status, body))
            },
            "auth",
        )
    }
    fn codex_auth_base() -> String {
        std::env::var("PY_CODEX_AUTH_BASE_URL")
            .unwrap_or_else(|_| "https://auth.openai.com".into())
            .trim_end_matches('/')
            .into()
    }
    fn codex_login(&mut self) -> Result<()> {
        let base = Self::codex_auth_base();
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(30))
            .redirect(reqwest::redirect::Policy::none())
            .build()?;
        let (status, device) = self.codex_http(
            client
                .post(format!("{base}/api/accounts/deviceauth/usercode"))
                .json(&json!({"client_id":CODEX_CLIENT_ID})),
        )?;
        if status != 200 {
            return Err(format!("Codex device login unavailable (HTTP {status}); enable device-code login in ChatGPT settings if required").into());
        }
        let device_id = device["device_auth_id"]
            .as_str()
            .filter(|s| !s.is_empty())
            .ok_or("Codex device response missing device ID")?;
        let code = device["user_code"]
            .as_str()
            .filter(|s| !s.is_empty() && s.len() <= 128 && !s.chars().any(char::is_control))
            .ok_or("Codex device response missing user code")?;
        let mut interval = device["interval"]
            .as_f64()
            .or_else(|| device["interval"].as_str()?.trim().parse().ok())
            .filter(|n| n.is_finite() && *n >= 0.0 && *n <= 60.0)
            .ok_or("Codex device response has invalid interval")?
            .max(0.01);
        self.event("login_prompt",json!({"provider":"openai-codex","method":"device_code","url":"https://auth.openai.com/codex/device","user_code":code}));
        if !self.json {
            ui_text(&format!(
                "Open https://auth.openai.com/codex/device and enter {code}. Ctrl-C cancels."
            ));
        }
        let seconds = std::env::var("PY_CODEX_DEVICE_TIMEOUT_SECONDS")
            .ok()
            .map(|s| s.parse::<f64>())
            .transpose()?
            .unwrap_or(900.0);
        if !seconds.is_finite() || seconds <= 0.0 || seconds > 900.0 {
            return Err("invalid Codex device timeout (0–900 seconds)".into());
        }
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs_f64(seconds);
        loop {
            let left = deadline.saturating_duration_since(std::time::Instant::now());
            if left.is_zero() {
                return Err("Codex device login expired; try /login codex again".into());
            }
            let pause = std::time::Duration::from_secs_f64(interval).min(left);
            self.codex_wait(
                async {
                    tokio::time::sleep(pause).await;
                    Ok(())
                },
                "auth",
            )?;
            if std::time::Instant::now() >= deadline {
                return Err("Codex device login expired; try /login codex again".into());
            }
            let (status, token) = self.codex_http(
                client
                    .post(format!("{base}/api/accounts/deviceauth/token"))
                    .timeout(
                        deadline
                            .saturating_duration_since(std::time::Instant::now())
                            .min(std::time::Duration::from_secs(30)),
                    )
                    .json(&json!({"device_auth_id":device_id,"user_code":code})),
            )?;
            if status == 200 {
                let authorization = token["authorization_code"]
                    .as_str()
                    .filter(|s| !s.is_empty())
                    .ok_or("Codex device token response missing authorization code")?;
                let verifier = token["code_verifier"]
                    .as_str()
                    .filter(|s| !s.is_empty())
                    .ok_or("Codex device token response missing verifier")?;
                let (status, body) = self.codex_http(
                    client
                        .post(format!("{base}/oauth/token"))
                        .header("Accept", "application/json")
                        .form(&[
                            ("grant_type", "authorization_code"),
                            ("client_id", CODEX_CLIENT_ID),
                            ("code", authorization),
                            ("code_verifier", verifier),
                            (
                                "redirect_uri",
                                "https://auth.openai.com/deviceauth/callback",
                            ),
                        ]),
                )?;
                if status != 200 {
                    return Err(format!(
                        "Codex token exchange failed (HTTP {status}); try /login codex again"
                    )
                    .into());
                }
                return self.store_credential("openai-codex", Some(codex_token_value(&body)?));
            }
            let error = token["error"]
                .as_str()
                .or(token["error"]["code"].as_str())
                .unwrap_or("");
            if status == 403 || status == 404 || error == "deviceauth_authorization_pending" {
                continue;
            }
            if error == "slow_down" {
                interval = (interval + 5.0).min(60.0);
                continue;
            }
            return Err(
                format!("Codex device authorization denied or failed (HTTP {status})").into(),
            );
        }
    }
    fn refresh_codex(&mut self) -> Result<()> {
        // Lock spans reload/check/exchange/write: rotating refresh tokens are used once.
        let _lock = self.auth_lock()?;
        self.provider
            .accept_auth(load_json(&self.home.join("auth.json"))?);
        let credential = &self.provider.auth["openai-codex"];
        let refresh = oauth_token(credential, "refresh")
            .map_err(|_| "Codex stored credential invalid; /login codex again")?
            .to_string();
        if credential["expires"].as_u64().unwrap_or(0) > now_ms() as u64 {
            oauth_token(credential, "access")
                .map_err(|_| "Codex stored credential invalid; /login codex again")?;
            credential["accountId"]
                .as_str()
                .filter(|s| {
                    !s.is_empty() && s.len() <= 512 && s.bytes().all(|c| (33..=126).contains(&c))
                })
                .ok_or("Codex stored credential has invalid account ID; /login codex again")?;
            return Ok(());
        }
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(30))
            .redirect(reqwest::redirect::Policy::none())
            .build()?;
        let (status, body) = self.codex_http(
            client
                .post(format!("{}/oauth/token", Self::codex_auth_base()))
                .header("Accept", "application/json")
                .form(&[
                    ("grant_type", "refresh_token"),
                    ("client_id", CODEX_CLIENT_ID),
                    ("refresh_token", refresh.as_str()),
                ]),
        )?;
        if status != 200 {
            return Err(
                format!("Codex token refresh failed (HTTP {status}); /login codex again").into(),
            );
        }
        let next = codex_token_value(&body)?;
        let mut auth = self.provider.auth.clone();
        auth["openai-codex"] = next;
        write_private_json(&self.home.join("auth.json"), &auth)?;
        self.provider.accept_auth(auth);
        Ok(())
    }
}
impl ProviderClient {
    fn text_request(
        &self,
        client: &reqwest::Client,
        url: &str,
        key: &str,
        id: &str,
        messages: Vec<Value>,
        api: &ApiKind,
        fields: &Value,
        max: usize,
        session_id: &str,
        codex: bool,
        anthropic_oauth: bool,
    ) -> Result<reqwest::RequestBuilder> {
        Ok(if codex {
            self.codex_request(client, url, key, id, &messages, session_id)?
        } else if *api == ApiKind::Responses {
            let mut input = messages.clone();
            for message in &mut input {
                if let Some(parts) = message["content"].as_array_mut() {
                    for part in parts {
                        match part["type"].as_str() {
                            Some("text") => part["type"] = json!("input_text"),
                            Some("image_url") => {
                                let url = part["image_url"]["url"].clone();
                                *part = json!({"type":"input_image","image_url":url});
                            }
                            _ => {}
                        }
                    }
                }
            }
            let mut body = json!({"model":id,"input":input,"max_output_tokens":max,"store":false});
            merge_reasoning_fields(&mut body, fields);
            client
                .post(format!("{url}/responses"))
                .bearer_auth(key)
                .json(&body)
        } else if *api == ApiKind::Anthropic {
            let system = messages
                .iter()
                .filter(|m| m["role"] == "system")
                .filter_map(|m| m["content"].as_str())
                .collect::<Vec<_>>()
                .join("\n");
            let mut msgs: Vec<_> = messages
                .into_iter()
                .filter(|m| m["role"] != "system")
                .collect();
            for message in &mut msgs {
                if let Some(parts) = message["content"].as_array_mut() {
                    for part in parts {
                        if part["type"] == "image_url" {
                            let url = part["image_url"]["url"]
                                .as_str()
                                .ok_or("image URL missing")?;
                            let (mime, data) = image_data_url(url)?;
                            *part = json!({"type":"image","source":{"type":"base64","media_type":mime,"data":data}});
                        }
                    }
                }
            }
            let mut body = json!({"model":id,"system":system,"messages":msgs,"max_tokens":max});
            merge_reasoning_fields(&mut body, fields);
            let mut request = client
                .post(format!("{url}/messages"))
                .header("anthropic-version", "2023-06-01");
            if anthropic_oauth {
                // Subscription compatibility changes the wire, not stored context.
                body["system"] = json!([
                    {"type":"text","text":ANTHROPIC_OAUTH_SYSTEM},
                    {"type":"text","text":system}
                ]);
                let mut beta =
                    "claude-code-20250219,oauth-2025-04-20,fine-grained-tool-streaming-2025-05-14"
                        .to_string();
                if body.get("thinking").is_some() {
                    beta.push_str(",interleaved-thinking-2025-05-14");
                }
                request = request
                    .bearer_auth(key)
                    .header("anthropic-beta", beta)
                    .header("x-app", "cli")
                    .header(
                        "User-Agent",
                        "claude-cli/2.1.2 (external, cli) py-rust/0.1.0",
                    )
                    .header("Accept", "application/json");
            } else {
                request = request.header("x-api-key", key);
                if body.get("thinking").is_some() {
                    request = request.header("anthropic-beta", "interleaved-thinking-2025-05-14");
                }
            }
            request.json(&body)
        } else if *api == ApiKind::Google {
            let system = messages
                .iter()
                .filter(|m| m["role"] == "system")
                .filter_map(|m| m["content"].as_str())
                .collect::<Vec<_>>()
                .join("\n");
            let mut contents = Vec::new();
            for message in messages.iter().filter(|m| m["role"] != "system") {
                let mut parts = Vec::new();
                if let Some(text) = message["content"].as_str() {
                    parts.push(json!({"text":text}));
                } else if let Some(items) = message["content"].as_array() {
                    for item in items {
                        if item["type"] == "text" {
                            parts.push(json!({"text":item["text"]}));
                        } else if item["type"] == "image_url" {
                            let (mime, data) = image_data_url(
                                item["image_url"]["url"]
                                    .as_str()
                                    .ok_or("image URL missing")?,
                            )?;
                            parts.push(json!({"inlineData":{"mimeType":mime,"data":data}}));
                        }
                    }
                }
                contents.push(json!({"role":if message["role"]=="assistant"{"model"}else{"user"},"parts":parts}));
            }
            let mut body = json!({"contents":contents,"systemInstruction":{"parts":[{"text":system}]},
                "generationConfig":{"maxOutputTokens":max}});
            if let Some(config) = fields.get("thinkingConfig") {
                body["generationConfig"]["thinkingConfig"] = config.clone();
            }
            client
                .post(format!("{url}/models/{id}:generateContent"))
                .header("x-goog-api-key", key)
                .json(&body)
        } else {
            let mut body = json!({"model":id,"messages":messages,"max_tokens":max});
            merge_reasoning_fields(&mut body, fields);
            client
                .post(format!("{url}/chat/completions"))
                .bearer_auth(key)
                .json(&body)
        })
    }
    fn codex_request(
        &self,
        client: &reqwest::Client,
        url: &str,
        key: &str,
        id: &str,
        messages: &[Value],
        session_id: &str,
    ) -> Result<reqwest::RequestBuilder> {
        let mut instructions = Vec::new();
        let mut input = Vec::new();
        for message in messages {
            let role = message["role"].as_str().unwrap_or("user");
            if role == "system" || role == "developer" {
                if let Some(text) = message["content"].as_str() {
                    instructions.push(text.to_string());
                } else if let Some(parts) = message["content"].as_array() {
                    for p in parts {
                        if let Some(text) = p["text"].as_str() {
                            instructions.push(text.to_string());
                        }
                    }
                }
                continue;
            }
            let mut item = message.clone();
            if role == "assistant" {
                item["type"] = json!("message");
                item["status"] = json!("completed");
                item["phase"] = json!(codex_assistant_phase(message)?);
            } else if let Some(object) = item.as_object_mut() {
                object.remove("phase");
                object.remove("status");
            }
            if let Some(text) = item["content"].as_str() {
                item["content"] = if role == "assistant" {
                    json!([{"type":"output_text","text":text,"annotations":[]}])
                } else {
                    json!([{"type":"input_text","text":text}])
                };
            } else if let Some(parts) = item["content"].as_array_mut() {
                for part in parts {
                    if matches!(
                        part["type"].as_str(),
                        Some("text" | "input_text" | "output_text")
                    ) {
                        part["type"] = json!(if role == "assistant" {
                            "output_text"
                        } else {
                            "input_text"
                        });
                        if role == "assistant" {
                            part["annotations"] = json!([]);
                        } else if let Some(object) = part.as_object_mut() {
                            object.remove("annotations");
                        }
                    } else if part["type"] == "image_url" {
                        *part = json!({"type":"input_image","image_url":part["image_url"]["url"]});
                    }
                }
            }
            input.push(item);
        }
        let session = session_id;
        let mut body = json!({"model":id,"store":false,"stream":true,"instructions":instructions.join("\n"),"input":input,
            "text":{"verbosity":"medium"},"include":["reasoning.encrypted_content"],"prompt_cache_key":session});
        let effort = self.effort.as_str();
        let meta = self.reasoning_metadata(&format!("openai-codex/{id}"));
        reasoning_fields(
            "openai-codex-responses",
            "openai-codex",
            id,
            &meta,
            effort,
            4096,
        )?;
        if effort != "off" || meta["reasoning_efforts"].is_array() {
            body["reasoning"] = json!({"effort":if effort=="off"{"none"}else if effort=="minimal"&&(id.starts_with("gpt-5.2")||id.starts_with("gpt-5.3")){"low"}else{effort},"summary":"auto"});
        }
        let endpoint = if url.ends_with("/codex/responses") {
            url.to_string()
        } else if url.ends_with("/codex") {
            format!("{url}/responses")
        } else {
            format!("{url}/codex/responses")
        };
        Ok(client
            .post(endpoint)
            .bearer_auth(key)
            .header(
                "chatgpt-account-id",
                self.auth["openai-codex"]["accountId"]
                    .as_str()
                    .ok_or("Codex account ID missing")?,
            )
            .header("OpenAI-Beta", "responses=experimental")
            .header("Accept", "text/event-stream")
            .header("originator", "py")
            .header("User-Agent", "py-rust/0.1.0")
            .header("session-id", session)
            .header("x-client-request-id", session)
            .json(&body))
    }
}
impl Host {
    #[cfg(test)]
    fn codex_request(
        &self,
        client: &reqwest::Client,
        url: &str,
        key: &str,
        id: &str,
        messages: &[Value],
    ) -> Result<reqwest::RequestBuilder> {
        self.provider
            .codex_request(client, url, key, id, messages, &self.journal.session_id)
    }
    fn supersede_pending_codex_retry(&mut self, operation: &str) -> Result<()> {
        if self
            .provider
            .retry_snapshot()
            .is_some_and(|retry| retry.operation == operation && retry.waiting_delay_ms.is_some())
            && self.agent_turn
            && self.execution.cell().is_none()
            && self.pending.iter().any(NativeCommand::steering)
        {
            self.journal.append(
                "provider_retry_superseded",
                json!({"operation":operation,"reason":"new steering"}),
            )?;
            return Err(RetrySuperseded.into());
        }
        Ok(())
    }
    fn mark_codex_billing_unknown(&mut self) {
        self.mark_cache_usage_incomplete();
    }
    fn codex_sse(
        &mut self,
        request: reqwest::RequestBuilder,
        operation: &str,
        max_retries: u64,
    ) -> Result<Value> {
        let scope = self
            .provider
            .begin_request(operation, self.execution.cancel_revision());
        let result = self.codex_sse_retries(&request, operation, max_retries);
        self.provider.settle_request(
            operation,
            if result.is_ok() {
                ProviderRequestOutcome::Succeeded
            } else {
                ProviderRequestOutcome::Failed
            },
        );
        let changed = self.provider.retry_snapshot().is_some();
        drop(scope);
        if changed {
            self.event("state", self.state_payload());
        }
        result
    }
    fn codex_sse_retries(
        &mut self,
        request: &reqwest::RequestBuilder,
        operation: &str,
        max_retries: u64,
    ) -> Result<Value> {
        let secrets = self.provider.codex_secrets();
        let attempts = self.provider.attempts.clone();
        ProviderClient::retry_codex(request, operation, max_retries, &secrets, attempts, self)
    }
}
impl ProviderClient {
    fn codex_secrets(&self) -> Vec<String> {
        let mut secrets = Vec::new();
        credential_secret_values(&self.auth, &mut secrets);
        if let Ok((_, key, _)) = self.provider_config("openai-codex/gpt-6.1-sol") {
            if !key.is_empty() {
                secrets.push(key);
            }
        }
        secrets
    }
    fn retry_codex(
        request: &reqwest::RequestBuilder,
        operation: &str,
        max_retries: u64,
        secrets: &[String],
        attempts: ProviderAttempts,
        control: &mut impl ProviderControl,
    ) -> Result<Value> {
        for retry in 0..=max_retries {
            if control.provider_checkpoint(operation)? {
                return Err("Codex operation cancelled; request outcome may be unknown".into());
            }
            control.provider_retry_checkpoint(operation)?;
            let request = request
                .try_clone()
                .ok_or("Codex request cannot be cloned for retry")?;
            attempts.transition(
                operation,
                ProviderAttemptPhase::Sending,
                Some(ProviderRetryState {
                    operation: operation.into(),
                    retry,
                    max_retries,
                    waiting_delay_ms: None,
                }),
            );
            // Journal acknowledgement remains outside transport and must precede send.
            control.provider_attempt_started(operation, retry, max_retries)?;
            let result = Self::wait_codex(
                codex_sse_once(request, secrets, attempts.clone(), operation),
                operation,
                control,
            );
            match result {
                Ok(body) => return Ok(body),
                Err(error) => {
                    let transient = error.downcast_ref::<RetryableProviderError>();
                    let billing_unknown = transient.is_some_and(|error| error.billing_unknown);
                    control.provider_attempt_failed(
                        operation,
                        retry,
                        transient.is_some(),
                        billing_unknown,
                        &error.to_string(),
                        error
                            .downcast_ref::<CodexTerminalFailure>()
                            .map(|failure| &failure.diagnostic),
                    )?;
                    let Some(transient) = transient else {
                        return Err(error);
                    };
                    if retry == max_retries {
                        let exhausted = if max_retries == 0 {
                            "automatic retries disabled".to_owned()
                        } else {
                            format!("retry limit exhausted ({} attempts)", max_retries + 1)
                        };
                        return Err(format!("{error}; {exhausted}; previous cell outputs remain available in H.cells").into());
                    }
                    let next_retry = retry + 1;
                    let delay_ms = (500u64 << retry)
                        .min(30000)
                        .max(transient.retry_after_ms.unwrap_or(0));
                    attempts.transition(
                        operation,
                        ProviderAttemptPhase::Backoff,
                        Some(ProviderRetryState {
                            operation: operation.into(),
                            retry: next_retry,
                            max_retries,
                            waiting_delay_ms: Some(delay_ms),
                        }),
                    );
                    control.provider_retry_scheduled(
                        operation,
                        next_retry,
                        max_retries,
                        delay_ms,
                        billing_unknown,
                        &transient.reason,
                    )?;
                    Self::wait_codex(
                        async {
                            tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
                            Ok(())
                        },
                        operation,
                        control,
                    )?;
                }
            }
        }
        Err("Codex retry limit invariant violated".into())
    }
}
#[cfg(test)]
mod provider_retry_tests {
    use super::*;
    #[test]
    fn retry_rendering_is_visible_in_both_status_surfaces() {
        let status = json!({"state":"thinking","model":"codex/model","effort":"high",
            "retry":1,"max_retries":2,"retry_delay_ms":500});
        let historical = terminal_state(&status, 500).join("\n");
        let footer = terminal_status(&status, 500).join("\n");
        for text in [historical, footer] {
            assert!(
                text.contains("retry 1/2") && text.contains("backoff 0.5s"),
                "{text}"
            );
        }
    }
    #[test]
    fn footer_identity_preserves_final_cell_but_advances_for_intermediate_boundaries() {
        let mut status = json!({"state":"idle","cell":null,"cells":3,
            "last_cell":{"cell":3,"status":"ok","elapsed_ms":10}});
        assert_eq!(terminal_status_cell(&status), Some(3));
        status["state"] = json!("thinking");
        assert_eq!(terminal_status_cell(&status), Some(4));
        status["state"] = json!("running");
        status["cell"] = json!(1);
        assert_eq!(terminal_status_cell(&status), Some(1));
        status["state"] = json!("idle");
        status["cell"] = Value::Null;
        status["generation_failed"] = json!(true);
        assert_eq!(terminal_status_cell(&status), None);
        let footer = terminal_status(&status, 500).join("\n");
        assert!(footer.contains("provider request failed"), "{footer}");
        assert!(
            !footer.contains("cell 3") && !footer.contains("status: ok"),
            "{footer}"
        );
    }

    #[test]
    fn child_footer_omits_provider_metrics_but_preserves_identity_and_failure() {
        let mut event = json!({"cell":50,"parent_cell":49,"language":"shell",
            "elapsed_ms":28,"status":"ok","model":"codex/model","effort":"high",
            "context_usage":{"estimated_tokens":100,"context_limit":200},
            "cache_hit_percentage":75.6});
        let child = terminal_cell_end(&event, 500).join("\n");
        assert!(
            child.starts_with("  ↳ cell 49 › 50 · shell 28ms · status: ok"),
            "{child}"
        );
        for metric in ["ctx", "cache hit", "codex/model", "──"] {
            assert!(!child.contains(metric), "{child}");
        }
        event["status"] = json!("error");
        assert!(terminal_cell_end(&event, 40).join("\n").contains("error"));
        event["parent_cell"] = Value::Null;
        let parent = terminal_cell_end(&event, 500).join("\n");
        assert!(
            parent.starts_with("\n── cell 50 · shell") && parent.ends_with("\n"),
            "{parent}"
        );
        assert!(
            parent.contains("cache hit") && parent.contains("codex/model"),
            "{parent}"
        );
    }
    #[test]
    fn codex_terminal_diagnostics_are_bounded_redacted_and_nonretryable() {
        let secrets = vec![
            "credential-SECRET".to_owned(),
            "credential-SECRET-long".to_owned(),
        ];
        for kind in [
            "error",
            "response.failed",
            "response.incomplete",
            "response.completed",
        ] {
            let event = json!({"type":kind,"headers":{"authorization":"credential-SECRET"},
                "response":{"status":"incomplete","incomplete_details":{"reason":"max_output_tokens"},
                    "error":{"code":"credential-SECRET-long","message":format!("credential-SECRET\n\u{1b}{}", "λ".repeat(1200)),
                        "extra":"PRIVATE-RAW"},
                    "output":[{"text":"PARTIAL-MUST-NOT-BE-RETAINED"}]}});
            let error = codex_terminal_failure(&event, &secrets);
            assert!(error.downcast_ref::<RetryableProviderError>().is_none());
            let diagnostic = &error
                .downcast_ref::<CodexTerminalFailure>()
                .unwrap()
                .diagnostic;
            assert_eq!(diagnostic["event_type"], kind);
            assert_eq!(diagnostic["reason"], "max_output_tokens");
            assert_eq!(diagnostic["code"], "[redacted]");
            assert_eq!(diagnostic.as_object().unwrap().len(), 5);
            let text = error.to_string();
            for forbidden in [
                "credential-SECRET",
                "PARTIAL-MUST",
                "PRIVATE-RAW",
                "authorization",
                "\n",
                "\u{1b}",
            ] {
                assert!(!text.contains(forbidden), "{text}");
            }
            assert!(diagnostic["message"].as_str().unwrap().chars().count() <= 1036);
            assert!(text.contains("[truncated]") && text.contains("no automatic retry"));
        }
        let error = codex_terminal_failure(
            &json!({"type":"error","code":"server_error","message":"try again"}),
            &[],
        );
        assert!(error.to_string().contains("code=server_error"));
        let error = codex_terminal_failure(&json!({"type":"response.failed"}), &[]);
        assert_eq!(
            error.to_string(),
            "Codex response.failed; no automatic retry"
        );
    }
    #[test]
    fn retry_after_never_shortens_an_unrepresentable_server_delay() {
        for header in ["31", "Wed, 21 Oct 2037 07:28:00 GMT", "invalid"] {
            let error = codex_rejection_error(
                reqwest::StatusCode::TOO_MANY_REQUESTS,
                String::new(),
                Some(header.into()),
            );
            assert!(error.downcast_ref::<RetryableProviderError>().is_none());
            assert!(error.to_string().contains("no automatic retry"));
        }
        let error = codex_rejection_error(
            reqwest::StatusCode::TOO_MANY_REQUESTS,
            String::new(),
            Some("2".into()),
        );
        let retry = error.downcast_ref::<RetryableProviderError>().unwrap();
        assert_eq!(retry.retry_after_ms, Some(2000));
        assert!(!retry.billing_unknown);
    }
}
fn codex_transport_error(error: reqwest::Error, reason: &str) -> Box<dyn std::error::Error> {
    if !error.is_builder()
        && !error.is_decode()
        && (error.is_connect() || error.is_timeout() || error.is_request() || error.is_body())
    {
        RetryableProviderError {
            reason: reason.into(),
            retry_after_ms: None,
            billing_unknown: true,
        }
        .into()
    } else {
        format!("{reason}; no automatic retry").into()
    }
}
fn codex_rejection_error(
    status: reqwest::StatusCode,
    detail: String,
    retry_after: Option<String>,
) -> Box<dyn std::error::Error> {
    let reason = format!("Codex provider HTTP {status}{detail}");
    if !matches!(status.as_u16(), 408 | 429 | 500 | 502 | 503 | 504) {
        return format!("{reason}; no automatic retry").into();
    }
    let retry_after_ms=match retry_after{
        None=>None,
        Some(value)=>match value.trim().parse::<u64>(){
            Ok(seconds) if seconds<=30=>Some(seconds*1000),
            _=>return format!("{reason}; Retry-After unsupported or exceeds 30s; no automatic retry (do not retry before the server's requested delay)").into()
        }
    };
    RetryableProviderError {
        reason,
        retry_after_ms,
        billing_unknown: status.as_u16() != 429,
    }
    .into()
}
async fn codex_sse_once(
    request: reqwest::RequestBuilder,
    secrets: &[String],
    attempts: ProviderAttempts,
    operation: &str,
) -> Result<Value> {
    let mut response = request
        .send()
        .await
        .map_err(|error| codex_transport_error(error, "Codex provider network error"))?;
    attempts.transition(operation, ProviderAttemptPhase::Streaming, None);
    let status = response.status();
    if !status.is_success() {
        let retry_after = response
            .headers()
            .get(reqwest::header::RETRY_AFTER)
            .map(|value| {
                value
                    .to_str()
                    .map(str::to_owned)
                    .unwrap_or_else(|_| "unsupported".into())
            });
        let mut bytes = Vec::new();
        loop {
            match response.chunk().await {
                Ok(Some(chunk)) => {
                    if bytes.len() + chunk.len() > 65536 {
                        return Err(format!("Codex provider HTTP {status}; error body exceeds 64 KiB; no automatic retry").into());
                    }
                    bytes.extend_from_slice(&chunk);
                }
                Ok(None) => break,
                // An incomplete rejection body is never printed: even a known
                // secret's truncated prefix could evade full-token redaction.
                Err(_) => {
                    return Err(codex_rejection_error(
                        status,
                        ": error response disconnected".into(),
                        retry_after,
                    ))
                }
            }
        }
        return Err(codex_rejection_error(
            status,
            codex_error_detail(&bytes, secrets),
            retry_after,
        ));
    }
    // Local parser state belongs to this attempt only; a later attempt receives
    // a new parser and cannot concatenate abandoned partial generated code.
    codex_read_sse(response, secrets).await
}
fn credential_secret_values(value: &Value, out: &mut Vec<String>) {
    if let Some(object) = value.as_object() {
        for (key, value) in object {
            if matches!(
                key.as_str(),
                "key"
                    | "access"
                    | "refresh"
                    | "access_token"
                    | "refresh_token"
                    | "id_token"
                    | "accountId"
            ) {
                if let Some(value) = value.as_str().filter(|v| !v.is_empty()) {
                    out.push(value.into());
                }
            } else {
                credential_secret_values(value, out);
            }
        }
    } else if let Some(values) = value.as_array() {
        for value in values {
            credential_secret_values(value, out);
        }
    }
}
fn codex_error_detail(bytes: &[u8], secrets: &[String]) -> String {
    let Ok(text) = std::str::from_utf8(bytes) else {
        return ": unreadable error response".into();
    };
    let mut detail = if let Ok(body) = serde_json::from_str::<Value>(text) {
        let error = &body["error"];
        [
            error["message"]
                .as_str()
                .or(error.as_str())
                .or(body["message"].as_str())
                .or(body["detail"].as_str()),
            error["code"].as_str(),
            error["param"].as_str(),
        ]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .join("; ")
    } else {
        text.to_string()
    };
    // Redact before truncation so a token crossing the preview boundary cannot
    // leak a partial prefix. Never store the raw rejection body in the journal.
    let mut secrets: Vec<_> = secrets.iter().filter(|s| !s.is_empty()).collect();
    secrets.sort_by_key(|s| std::cmp::Reverse(s.len()));
    for secret in secrets {
        detail = detail.replace(secret, "[redacted]");
    }
    let truncated = detail.chars().count() > 1024;
    let mut safe: String = detail
        .chars()
        .take(1024)
        .map(|c| {
            if c.is_control() || matches!(c, '\u{2028}' | '\u{2029}') {
                ' '
            } else {
                c
            }
        })
        .collect();
    if truncated {
        safe.push_str(" [truncated]");
    }
    if safe.trim().is_empty() {
        String::new()
    } else {
        format!(": {}", safe.trim())
    }
}

// Failed events retain only bounded, credential-redacted fields, never partial
// generated source or the raw SSE payload.
#[derive(Debug)]
struct CodexTerminalFailure {
    diagnostic: Value,
}
impl std::fmt::Display for CodexTerminalFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "Codex {}",
            self.diagnostic["event_type"]
                .as_str()
                .unwrap_or("response failure")
        )?;
        for key in ["status", "code", "reason", "message"] {
            if let Some(value) = self.diagnostic[key].as_str() {
                write!(f, "; {key}={value}")?;
            }
        }
        write!(f, "; no automatic retry")
    }
}
impl std::error::Error for CodexTerminalFailure {}
fn codex_terminal_failure(event: &Value, secrets: &[String]) -> Box<dyn std::error::Error> {
    let kind = match event["type"].as_str() {
        Some("error") => "error",
        Some("response.failed") => "response.failed",
        Some("response.incomplete") => "response.incomplete",
        Some("response.done") => "response.done",
        _ => "response.completed",
    };
    let response = &event["response"];
    let error = if event["error"].is_object() {
        &event["error"]
    } else if response["error"].is_object() {
        &response["error"]
    } else {
        event
    };
    let mut diagnostic = json!({"event_type":kind});
    for (key, value) in [
        ("status", &response["status"]),
        ("code", &error["code"]),
        ("reason", &response["incomplete_details"]["reason"]),
        ("message", &error["message"]),
    ] {
        if let Some(text) = value.as_str() {
            let safe = codex_error_detail(json!({"error": text}).to_string().as_bytes(), secrets);
            let safe = safe.strip_prefix(": ").unwrap_or(&safe);
            if !safe.is_empty() {
                diagnostic[key] = json!(safe);
            }
        }
    }
    Box::new(CodexTerminalFailure { diagnostic })
}

fn validate_provider_completion(body: &Value) -> Result<()> {
    let reason = if body["choices"][0]["finish_reason"] == "length" {
        Some("finish_reason=length")
    } else if body["stop_reason"] == "max_tokens" {
        Some("stop_reason=max_tokens")
    } else if body["candidates"][0]["finishReason"] == "MAX_TOKENS" {
        Some("finishReason=MAX_TOKENS")
    } else if body["status"] == "incomplete" {
        Some("status=incomplete")
    } else {
        None
    };
    if let Some(reason) = reason {
        return Err(format!("provider response truncated/incomplete ({reason}); no generated code was executed, no automatic retry").into());
    }
    if matches!(body["status"].as_str(), Some("failed" | "cancelled")) {
        return Err(
            "provider response did not complete successfully; no generated code was executed"
                .into(),
        );
    }
    Ok(())
}

// Responses can contain draft/commentary messages as well as the finalized
// program. Executing their concatenation repeats side effects. Select by phase,
// not text equality: intentional repetition in the final program must survive.
fn responses_final_text(output: &[Value]) -> Result<String> {
    let final_phase = output
        .iter()
        .any(|item| item["type"] == "message" && item["phase"] == "final_answer");
    let text = output
        .iter()
        .filter(|item| {
            item["type"] == "message"
                && if final_phase {
                    item["phase"] == "final_answer"
                } else {
                    item["phase"].is_null()
                }
        })
        .filter_map(|item| item["content"].as_array())
        .flatten()
        .filter(|part| part["type"] == "output_text")
        .filter_map(|part| part["text"].as_str())
        .collect::<String>();
    if text.is_empty() {
        return Err("provider response contains no final answer text; intermediate messages were not executed".into());
    }
    Ok(text)
}
#[derive(Default)]
struct CodexStreamText {
    items: std::collections::BTreeMap<u64, Value>,
    deltas: std::collections::BTreeMap<u64, String>,
    completed_items: HashSet<u64>,
    completed_text: std::collections::BTreeMap<u64, std::collections::BTreeMap<u64, String>>,
}
impl CodexStreamText {
    fn index(&self, event: &Value) -> Result<u64> {
        let index = event["output_index"].as_u64().or_else(|| {
            event["item_id"].as_str().and_then(|id| {
                self.items
                    .iter()
                    .find(|(_, item)| item["id"] == id)
                    .map(|(index, _)| *index)
            })
        });
        match index {
            Some(index) => Ok(index),
            None if self.items.is_empty() => Ok(0),
            None => Err("Codex text event has no output item identity; no automatic retry".into()),
        }
    }
    fn observe(&mut self, event: &Value) -> Result<()> {
        match event["type"].as_str().unwrap_or("") {
            "response.output_item.added" | "response.output_item.done" => {
                if let (Some(index), Some(item)) =
                    (event["output_index"].as_u64(), event["item"].as_object())
                {
                    let stored = self.items.entry(index).or_insert_with(|| json!({}));
                    for (key, value) in item {
                        stored[key] = value.clone();
                    }
                    if event["type"] == "response.output_item.done" {
                        self.completed_items.insert(index);
                    }
                }
            }
            "response.output_text.delta" => {
                if let Some(text) = event["delta"].as_str() {
                    self.deltas
                        .entry(self.index(event)?)
                        .or_default()
                        .push_str(text);
                }
            }
            "response.output_text.done" => {
                if let Some(text) = event["text"].as_str() {
                    self.completed_text
                        .entry(self.index(event)?)
                        .or_default()
                        .insert(event["content_index"].as_u64().unwrap_or(0), text.into());
                }
            }
            _ => {}
        }
        Ok(())
    }
    fn output(mut self) -> Value {
        let mut authoritative = HashSet::new();
        for index in &self.completed_items {
            if self.items[index]["content"]
                .as_array()
                .is_some_and(|parts| {
                    parts
                        .iter()
                        .any(|part| part["type"] == "output_text" && part["text"].is_string())
                })
            {
                authoritative.insert(*index);
            }
        }
        for (index, parts) in self.completed_text {
            if authoritative.contains(&index) {
                continue;
            }
            let item = self
                .items
                .entry(index)
                .or_insert_with(|| json!({"type":"message"}));
            item["content"] = json!(parts
                .into_values()
                .map(|text| json!({"type":"output_text","text":text}))
                .collect::<Vec<_>>());
            authoritative.insert(index);
        }
        for (index, text) in self.deltas {
            if authoritative.contains(&index) {
                continue;
            }
            let item = self
                .items
                .entry(index)
                .or_insert_with(|| json!({"type":"message"}));
            item["content"] = json!([{"type":"output_text","text":text}]);
        }
        json!(self.items.into_values().collect::<Vec<_>>())
    }
}
async fn codex_read_sse(mut response: reqwest::Response, secrets: &[String]) -> Result<Value> {
    let mut bytes = Vec::new();
    let mut data = Vec::new();
    let mut text_items = CodexStreamText::default();
    let mut total = 0usize;
    // reqwest can classify an interrupted Content-Length body as Decode,
    // not Body. At this boundary it is transport failure; JSON/SSE decoding
    // happens below and remains a separate, non-retryable protocol error.
    while let Some(chunk) = response
        .chunk()
        .await
        .map_err(|_| -> Box<dyn std::error::Error> {
            RetryableProviderError {
                reason: "Codex stream disconnected".into(),
                retry_after_ms: None,
                billing_unknown: true,
            }
            .into()
        })?
    {
        total += chunk.len();
        if total > 16 * 1024 * 1024 {
            return Err("Codex stream exceeds 16 MiB; outcome unknown".into());
        }
        bytes.extend_from_slice(&chunk);
        let mut consumed = 0usize;
        while let Some(offset) = bytes[consumed..].iter().position(|b| *b == b'\n') {
            let end = consumed + offset;
            let line = &bytes[consumed..end];
            consumed = end + 1;
            let line = line.strip_suffix(b"\r").unwrap_or(line);
            if line.is_empty() {
                if data.is_empty() {
                    continue;
                }
                let text = std::str::from_utf8(&data).map_err(|_| "Codex SSE has invalid UTF-8")?;
                if text.trim() == "[DONE]" {
                    data.clear();
                    continue;
                }
                let event: Value =
                    serde_json::from_str(text).map_err(|_| "Codex SSE has invalid JSON")?;
                data.clear();
                text_items.observe(&event)?;
                match event["type"].as_str().unwrap_or("") {
                    "error" | "response.failed" | "response.incomplete" => {
                        return Err(codex_terminal_failure(&event, secrets))
                    }
                    "response.done" | "response.completed" => {
                        let mut body = event["response"].clone();
                        if body["status"] != "completed" {
                            return Err(codex_terminal_failure(&event, secrets));
                        }
                        if body["output"].is_null()
                            || body["output"].as_array().is_some_and(Vec::is_empty)
                        {
                            body["output"] = text_items.output();
                        }
                        return Ok(body);
                    }
                    _ => {}
                }
            } else if let Some(part) = line.strip_prefix(b"data:") {
                if !data.is_empty() {
                    data.push(b'\n');
                }
                data.extend_from_slice(part.strip_prefix(b" ").unwrap_or(part));
                if data.len() > 2 * 1024 * 1024 {
                    return Err("Codex SSE frame exceeds 2 MiB; outcome unknown".into());
                }
            }
        }
        bytes.drain(..consumed);
        if bytes.len() > 2 * 1024 * 1024 {
            return Err("Codex SSE line exceeds 2 MiB; outcome unknown".into());
        }
        tokio::task::yield_now().await;
    }
    Err("Codex stream ended without successful terminal event; outcome/billing unknown. No automatic retry; previous cell outputs remain available in H.cells.".into())
}

// No getpass subprocess or echoed stdin fallback: secrets belong only to the
// foreground controlling terminal. The guard restores terminal state on errors
// and unwinding; cancellation also discards any unfinished canonical line.
struct SecretTerminal {
    tty: File,
    original: libc::termios,
    active: bool,
}
impl SecretTerminal {
    fn restore(&mut self, discard: bool) -> io::Result<()> {
        if !self.active {
            return Ok(());
        }
        if discard {
            unsafe {
                libc::tcflush(self.tty.as_raw_fd(), libc::TCIFLUSH);
            }
        }
        if unsafe { libc::tcsetattr(self.tty.as_raw_fd(), libc::TCSANOW, &self.original) } != 0 {
            return Err(io::Error::last_os_error());
        }
        self.active = false;
        Ok(())
    }
}
impl Drop for SecretTerminal {
    fn drop(&mut self) {
        let _ = self.restore(true);
    }
}
struct SecretBytes(Vec<u8>);
impl Drop for SecretBytes {
    fn drop(&mut self) {
        for byte in &mut self.0 {
            unsafe {
                std::ptr::write_volatile(byte, 0);
            }
        }
        std::sync::atomic::compiler_fence(std::sync::atomic::Ordering::SeqCst);
    }
}
fn terminal_secret_service(
    prompt: &str,
    deadline: Option<std::time::Instant>,
    mut service: impl FnMut() -> Result<()>,
) -> Result<String> {
    let tty=OpenOptions::new().read(true).write(true)
        .custom_flags(libc::O_NOCTTY|libc::O_CLOEXEC|libc::O_NONBLOCK).open("/dev/tty")
        .map_err(|_|"API-key entry requires a controlling terminal; use an environment variable or JSON login for automation")?;
    let fd = tty.as_raw_fd();
    if unsafe { libc::tcgetpgrp(fd) } != unsafe { libc::getpgrp() } {
        return Err("API-key entry requires the foreground terminal".into());
    }
    let mut original = unsafe { std::mem::zeroed::<libc::termios>() };
    if unsafe { libc::tcgetattr(fd, &mut original) } != 0 {
        return Err("API-key entry requires a terminal with controllable echo".into());
    }
    let mut secret_mode = original;
    secret_mode.c_lflag |= libc::ICANON | libc::ISIG;
    secret_mode.c_lflag &= !(libc::ECHO | libc::ECHONL | libc::ECHOCTL);
    if unsafe { libc::tcsetattr(fd, libc::TCSAFLUSH, &secret_mode) } != 0 {
        return Err("could not disable terminal echo; API key was not read".into());
    }
    let mut guard = SecretTerminal {
        tty,
        original,
        active: true,
    };
    let result = (|| -> Result<String> {
        guard.tty.write_all(terminal_safe(prompt).as_bytes())?;
        guard.tty.flush()?;
        // Canonical read preserves the terminal's native erase/kill bindings.
        // A partial line returned by Ctrl-D is cancellation, never a stored key.
        let mut bytes = SecretBytes(vec![0; 65536]);
        loop {
            service()?;
            if deadline.is_some_and(|d| std::time::Instant::now() >= d) {
                return Err("browser login timed out; retry /login <provider> manual".into());
            }
            if INTERRUPT.swap(false, std::sync::atomic::Ordering::SeqCst) {
                return Err("login cancelled".into());
            }
            let mut poll = libc::pollfd {
                fd,
                events: libc::POLLIN,
                revents: 0,
            };
            let ready = unsafe { libc::poll(&mut poll, 1, 100) };
            if ready < 0 {
                let error = io::Error::last_os_error();
                if error.kind() == io::ErrorKind::Interrupted {
                    continue;
                }
                return Err("could not poll terminal for API key".into());
            }
            if ready == 0 {
                continue;
            }
            if poll.revents & (libc::POLLERR | libc::POLLNVAL) != 0 {
                return Err("terminal disconnected during API-key entry".into());
            }
            let count = unsafe { libc::read(fd, bytes.0.as_mut_ptr().cast(), bytes.0.len()) };
            if count < 0 {
                let error = io::Error::last_os_error();
                if matches!(
                    error.kind(),
                    io::ErrorKind::Interrupted | io::ErrorKind::WouldBlock
                ) {
                    continue;
                }
                return Err("could not read API key from terminal".into());
            }
            if INTERRUPT.swap(false, std::sync::atomic::Ordering::SeqCst) {
                return Err("login cancelled".into());
            }
            if count == 0 {
                return Err("login cancelled".into());
            }
            let length = count as usize;
            if length == bytes.0.len() {
                return Err("API key exceeds the input limit".into());
            }
            if bytes.0[length - 1] != b'\n' {
                return Err("login cancelled".into());
            }
            let mut length = length - 1;
            if length > 0 && bytes.0[length - 1] == b'\r' {
                length -= 1;
            }
            let text = std::str::from_utf8(&bytes.0[..length])
                .map_err(|_| "API key must be valid UTF-8")?;
            if text.trim().is_empty() {
                return Err("empty API key; login cancelled".into());
            }
            return Ok(text.to_owned());
        }
    })();
    guard
        .restore(result.is_err())
        .map_err(|_| "could not restore terminal after API-key entry")?;
    guard.tty.write_all(b"\n")?;
    guard.tty.flush()?;
    result
}

// Browser authorization constants and subscription compatibility follow the Pi
// revision pinned in SPEC (not installed newer docs, and not Pig's newer endpoints).
const ANTHROPIC_CLIENT_ID: &str = "9d1c250a-e61b-44d9-88ed-5944d1962f5e";
const ANTHROPIC_REDIRECT: &str = "https://console.anthropic.com/oauth/code/callback";
const ANTHROPIC_OAUTH_SYSTEM: &str = "You are Claude Code, Anthropic's official CLI for Claude.";
fn oauth_random(length: usize) -> Result<Vec<u8>> {
    use std::io::Read as _;
    let mut bytes = vec![0; length];
    File::open("/dev/urandom")?.read_exact(&mut bytes)?;
    Ok(bytes)
}
fn oauth_pkce() -> Result<(String, String)> {
    let verifier = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(oauth_random(32)?);
    let digest = ring::digest::digest(&ring::digest::SHA256, verifier.as_bytes());
    let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(digest.as_ref());
    Ok((verifier, challenge))
}
fn oauth_token<'a>(body: &'a Value, name: &str) -> Result<&'a str> {
    body[name]
        .as_str()
        .filter(|s| !s.is_empty() && s.len() <= 32768 && s.bytes().all(|c| (33..=126).contains(&c)))
        .ok_or_else(|| "OAuth response contains an invalid or missing token".into())
}
fn anthropic_token_value(body: &Value) -> Result<Value> {
    let access = oauth_token(body, "access_token")?;
    let refresh = oauth_token(body, "refresh_token")?;
    let seconds = body["expires_in"]
        .as_f64()
        .filter(|s| s.is_finite() && *s > 300.0 && *s <= 31536000.0)
        .ok_or("Anthropic OAuth response has invalid token expiry")?;
    Ok(json!({"type":"oauth","access":access,"refresh":refresh,
        "expires":now_ms() as u64+(seconds*1000.0) as u64-300000}))
}
fn oauth_query(url: &reqwest::Url, name: &str) -> Result<Option<String>> {
    let values: Vec<_> = url
        .query_pairs()
        .filter(|(key, _)| key == name)
        .map(|(_, v)| v.into_owned())
        .collect();
    if values.len() > 1 {
        return Err("OAuth callback contains duplicate parameters".into());
    }
    Ok(values.into_iter().next())
}
fn oauth_code(url: &reqwest::Url, state: &str) -> Result<String> {
    if oauth_query(url, "state")?.as_deref() != Some(state) {
        return Err("OAuth callback state mismatch; login not saved".into());
    }
    if oauth_query(url, "error")?.is_some() {
        return Err("OAuth authorization denied; login not saved".into());
    }
    let code = oauth_query(url, "code")?
        .filter(|s| !s.is_empty() && s.len() <= 32768 && s.bytes().all(|c| (33..=126).contains(&c)))
        .ok_or("OAuth callback has no valid authorization code")?;
    Ok(code)
}
fn oauth_pasted_code(input: &str, redirect: &str, state: &str) -> Result<String> {
    let input = input.trim();
    if input.contains("://") {
        let url = reqwest::Url::parse(input).map_err(|_| "Invalid OAuth redirect URL")?;
        let expected =
            reqwest::Url::parse(redirect).map_err(|_| "Invalid OAuth callback configuration")?;
        if url.origin() != expected.origin()
            || url.path() != expected.path()
            || !url.username().is_empty()
            || url.password().is_some()
        {
            return Err("OAuth redirect URL does not match this login's callback".into());
        }
        return oauth_code(&url, state);
    }
    let (code, received) = input
        .split_once('#')
        .ok_or("Paste the full redirect URL or code#state from this login")?;
    if received != state {
        return Err("OAuth callback state mismatch; login not saved".into());
    }
    if code.is_empty() || code.len() > 32768 || !code.bytes().all(|c| (33..=126).contains(&c)) {
        return Err("OAuth callback has no valid authorization code".into());
    }
    Ok(code.into())
}
fn oauth_browser_open(url: &str) {
    // Browser processes may outlive login; launch without waiting, reap in a
    // detached thread, and never route their output/arguments through H.
    let program = std::env::var("PY_OAUTH_BROWSER").unwrap_or_else(|_| {
        if cfg!(target_os = "macos") {
            "open"
        } else {
            "xdg-open"
        }
        .into()
    });
    if program.is_empty() {
        return;
    }
    if let Ok(mut child) = Command::new(program)
        .arg(url)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
    {
        std::thread::spawn(move || {
            let _ = child.wait();
        });
    }
}
impl Host {
    fn anthropic_auth_base() -> String {
        std::env::var("PY_ANTHROPIC_AUTH_BASE_URL")
            .unwrap_or_else(|_| "https://console.anthropic.com".into())
            .trim_end_matches('/')
            .into()
    }
    fn browser_deadline() -> Result<std::time::Instant> {
        let seconds = std::env::var("PY_OAUTH_TIMEOUT_SECONDS")
            .ok()
            .map(|s| s.parse::<f64>())
            .transpose()?
            .unwrap_or(300.0);
        if !seconds.is_finite() || seconds <= 0.0 || seconds > 900.0 {
            return Err("Invalid browser OAuth timeout (0–900 seconds)".into());
        }
        Ok(std::time::Instant::now() + std::time::Duration::from_secs_f64(seconds))
    }
    fn browser_callback(
        &mut self,
        listener: &std::net::TcpListener,
        state: &str,
        deadline: std::time::Instant,
    ) -> Result<String> {
        use std::io::Read as _;
        listener.set_nonblocking(true)?;
        loop {
            if self.codex_cancel("auth")? {
                return Err("browser login cancelled".into());
            }
            if std::time::Instant::now() >= deadline {
                return Err(
                    "browser login timed out; use /login codex manual for remote callback paste"
                        .into(),
                );
            }
            let (mut stream, peer) = match listener.accept() {
                Ok(v) => v,
                Err(e)
                    if matches!(
                        e.kind(),
                        io::ErrorKind::WouldBlock | io::ErrorKind::Interrupted
                    ) =>
                {
                    std::thread::sleep(std::time::Duration::from_millis(15));
                    continue;
                }
                Err(_) => return Err("Could not receive browser OAuth callback".into()),
            };
            if !peer.ip().is_loopback() {
                continue;
            }
            stream.set_nonblocking(true)?;
            let until =
                (std::time::Instant::now() + std::time::Duration::from_secs(1)).min(deadline);
            let mut bytes = SecretBytes(Vec::new());
            let mut complete = false;
            loop {
                if self.codex_cancel("auth")? {
                    return Err("browser login cancelled".into());
                }
                if std::time::Instant::now() >= until {
                    break;
                }
                let mut buffer = [0; 1024];
                match stream.read(&mut buffer) {
                    Ok(0) => break,
                    Ok(n) => {
                        bytes.0.extend_from_slice(&buffer[..n]);
                        if bytes.0.len() > 8192 {
                            break;
                        }
                        if bytes.0.windows(4).any(|w| w == b"\r\n\r\n") {
                            complete = true;
                            break;
                        }
                    }
                    Err(e)
                        if matches!(
                            e.kind(),
                            io::ErrorKind::WouldBlock | io::ErrorKind::Interrupted
                        ) =>
                    {
                        std::thread::sleep(std::time::Duration::from_millis(15))
                    }
                    Err(_) => break,
                }
            }
            let parsed = if complete && bytes.0.len() <= 8192 {
                std::str::from_utf8(&bytes.0)
                    .ok()
                    .and_then(|text| text.lines().next())
                    .and_then(|line| {
                        let parts: Vec<_> = line.split(' ').collect();
                        if parts.len() != 3
                            || parts[0] != "GET"
                            || !parts[1].starts_with('/')
                            || !matches!(parts[2], "HTTP/1.0" | "HTTP/1.1")
                        {
                            return None;
                        }
                        reqwest::Url::parse(&format!("http://localhost{}", parts[1])).ok()
                    })
            } else {
                None
            };
            let outcome = parsed
                .as_ref()
                .filter(|url| url.path() == "/auth/callback")
                .map(|url| oauth_code(url, state));
            let status = if parsed
                .as_ref()
                .is_some_and(|url| url.path() != "/auth/callback")
            {
                "404 Not Found"
            } else if outcome.as_ref().is_some_and(|result| result.is_ok()) {
                "200 OK"
            } else {
                "400 Bad Request"
            };
            let body = if status == "200 OK" {
                "Authorization received. Return to py."
            } else {
                "Invalid authorization callback."
            };
            let response=format!("HTTP/1.1 {status}\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len());
            let _ = stream.write_all(response.as_bytes());
            let _ = stream.shutdown(std::net::Shutdown::Both);
            if let Some(Ok(code)) = outcome {
                return Ok(code);
            }
            // A provider denial with the valid state ends the flow. Invalid
            // requests never consume the valid callback or reveal credentials.
            if parsed.as_ref().is_some_and(|url| {
                url.path() == "/auth/callback"
                    && oauth_query(url, "state").ok().flatten().as_deref() == Some(state)
                    && oauth_query(url, "error").ok().flatten().is_some()
            }) {
                return Err("OAuth authorization denied; login not saved".into());
            }
        }
    }
    fn browser_login(&mut self, provider: &str, manual: bool) -> Result<()> {
        self.with_state(UiState::Login, None, |host| {
            host.browser_login_inner(provider, manual)
        })
    }
    fn browser_login_inner(&mut self, provider: &str, manual: bool) -> Result<()> {
        let provider = provider_alias(provider);
        if !matches!(provider, "anthropic" | "openai-codex") {
            return Err("Browser OAuth unsupported for this provider; /login lists methods".into());
        }
        let deadline = Self::browser_deadline()?;
        let (verifier, challenge) = oauth_pkce()?;
        let state = if provider == "anthropic" {
            verifier.clone()
        } else {
            base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(oauth_random(24)?)
        };
        let port = std::env::var("PY_OAUTH_CALLBACK_PORT")
            .ok()
            .map(|s| s.parse::<u16>())
            .transpose()?
            .unwrap_or(1455);
        let listener = if provider == "openai-codex" && !manual {
            std::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST, port)).ok()
        } else {
            None
        };
        if listener.is_none() && provider == "openai-codex" && !manual && self.json {
            return Err("Could not bind Codex callback; use a free callback port, device method, or interactive manual paste".into());
        }
        let callback_port = listener
            .as_ref()
            .map(|l| l.local_addr().map(|addr| addr.port()))
            .transpose()?
            .unwrap_or(port);
        let redirect = if provider == "anthropic" {
            ANTHROPIC_REDIRECT.to_string()
        } else {
            format!("http://localhost:{callback_port}/auth/callback")
        };
        let authorize = if provider == "anthropic" {
            std::env::var("PY_ANTHROPIC_AUTHORIZE_URL")
                .unwrap_or_else(|_| "https://claude.ai/oauth/authorize".into())
        } else {
            format!("{}/oauth/authorize", Self::codex_auth_base())
        };
        let mut url =
            reqwest::Url::parse(&authorize).map_err(|_| "Invalid OAuth authorize endpoint")?;
        {
            let mut query = url.query_pairs_mut();
            query
                .append_pair(
                    "client_id",
                    if provider == "anthropic" {
                        ANTHROPIC_CLIENT_ID
                    } else {
                        CODEX_CLIENT_ID
                    },
                )
                .append_pair("response_type", "code")
                .append_pair("redirect_uri", &redirect)
                .append_pair(
                    "scope",
                    if provider == "anthropic" {
                        "org:create_api_key user:profile user:inference"
                    } else {
                        "openid profile email offline_access"
                    },
                )
                .append_pair("code_challenge", &challenge)
                .append_pair("code_challenge_method", "S256")
                .append_pair("state", &state);
            if provider == "anthropic" {
                query.append_pair("code", "true");
            } else {
                query
                    .append_pair("id_token_add_organizations", "true")
                    .append_pair("codex_cli_simplified_flow", "true")
                    .append_pair("originator", "py");
            }
        }
        self.event("login_prompt",json!({"provider":provider,"method":if manual{"manual"}else{"browser"},"url":url.as_str()}));
        if !self.json {
            ui_text(&format!("Open this URL in your browser (automatic opener is best-effort):\n{url}\nCtrl-C cancels; authorization codes are entered only in the hidden prompt."));
            if provider == "anthropic" {
                ui_text("Anthropic subscription compatibility uses the provider's Claude Code protocol marker/headers; py identity is also sent. Your original system instructions follow unchanged. Live compatibility is unverified; API-key login is available.");
            }
            if provider == "openai-codex" && listener.is_none() && !manual {
                ui_text("Callback port unavailable; paste this login's full redirect URL in the hidden prompt instead.");
            }
        }
        oauth_browser_open(url.as_str());
        let code = if let Some(listener) = listener.as_ref() {
            self.browser_callback(listener, &state, deadline)?
        } else {
            let pasted =
                terminal_secret_service("Authorization code (hidden): ", Some(deadline), || {
                    if self.codex_cancel("auth")? {
                        Err("login cancelled".into())
                    } else {
                        Ok(())
                    }
                })?;
            oauth_pasted_code(&pasted, &redirect, &state)?
        };
        // Drop the loopback listener before any exchange: no second callback can
        // influence an exchange or be falsely acknowledged as another login.
        drop(listener);
        if std::time::Instant::now() >= deadline {
            return Err("browser login timed out; credentials unchanged".into());
        }
        let client = reqwest::Client::builder()
            .redirect(reqwest::redirect::Policy::none())
            .timeout(
                deadline
                    .saturating_duration_since(std::time::Instant::now())
                    .min(std::time::Duration::from_secs(30)),
            )
            .build()?;
        let request = if provider == "anthropic" {
            client.post(format!("{}/v1/oauth/token",Self::anthropic_auth_base())).json(&json!({
                "grant_type":"authorization_code","client_id":ANTHROPIC_CLIENT_ID,"code":code,"state":state,
                "redirect_uri":redirect,"code_verifier":verifier}))
        } else {
            client
                .post(format!("{}/oauth/token", Self::codex_auth_base()))
                .form(&[
                    ("grant_type", "authorization_code"),
                    ("client_id", CODEX_CLIENT_ID),
                    ("code", code.as_str()),
                    ("code_verifier", verifier.as_str()),
                    ("redirect_uri", redirect.as_str()),
                ])
        };
        let (status, body) = self
            .codex_http(request)
            .map_err(|e| e.to_string().replace("Codex", "OAuth"))?;
        if status != 200 {
            return Err(
                format!("OAuth token exchange rejected (HTTP {status}); login not saved").into(),
            );
        }
        let credential = if provider == "anthropic" {
            anthropic_token_value(&body)?
        } else {
            codex_token_value(&body)?
        };
        if self.codex_cancel("auth")? {
            return Err("browser login cancelled; credentials unchanged".into());
        }
        self.store_credential_until(provider, Some(credential), Some(deadline))
    }
    fn refresh_anthropic(&mut self) -> Result<()> {
        let _lock = self.auth_lock()?;
        self.provider
            .accept_auth(load_json(&self.home.join("auth.json"))?);
        let credential = &self.provider.auth["anthropic"];
        if credential["type"] != "oauth" {
            return Err(
                "Anthropic subscription credential changed; retry operation without replaying code"
                    .into(),
            );
        }
        if credential["expires"].as_u64().unwrap_or(0) > now_ms() as u64 {
            oauth_token(credential, "access")?;
            oauth_token(credential, "refresh")?;
            return Ok(());
        }
        let refresh = oauth_token(credential, "refresh")?.to_string();
        let client = reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(30))
            .redirect(reqwest::redirect::Policy::none())
            .build()?;
        let (status,body)=self.codex_http(client.post(format!("{}/v1/oauth/token",Self::anthropic_auth_base()))
            .json(&json!({"grant_type":"refresh_token","client_id":ANTHROPIC_CLIENT_ID,"refresh_token":refresh})))
            .map_err(|e|e.to_string().replace("Codex","Anthropic OAuth"))?;
        if status != 200 {
            return Err(format!(
                "Anthropic OAuth refresh rejected (HTTP {status}); stored credential unchanged"
            )
            .into());
        }
        let next = anthropic_token_value(&body)?;
        let mut auth = self.provider.auth.clone();
        auth["anthropic"] = next;
        if self.codex_cancel("auth")? {
            return Err("Anthropic OAuth refresh cancelled; stored credential unchanged".into());
        }
        write_private_json(&self.home.join("auth.json"), &auth)?;
        self.provider.accept_auth(auth);
        Ok(())
    }
}

// =============================================================================
// Background tasks and wakeups
// =============================================================================

// Session-owned isolated processes. All capture/journal mutation remains on Host's thread.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BgTaskOutcome {
    Succeeded,
    Failed,
    Cancelled,
    Killed,
    TimedOut,
    OutcomeUnknown,
}
impl BgTaskOutcome {
    fn as_str(self) -> &'static str {
        match self {
            Self::Succeeded => "succeeded",
            Self::Failed => "failed",
            Self::Cancelled => "cancelled",
            Self::Killed => "killed",
            Self::TimedOut => "timed_out",
            Self::OutcomeUnknown => "outcome_unknown",
        }
    }
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BgTaskStatus {
    Starting,
    Running,
    Cancelling,
    Settled(BgTaskOutcome),
}
impl BgTaskStatus {
    fn parse(value: &Value) -> Result<Self> {
        let status = value
            .as_str()
            .ok_or("background task status must be a recognized string")?;
        Ok(match status {
            "starting" => Self::Starting,
            "running" => Self::Running,
            "cancelling" => Self::Cancelling,
            "succeeded" => Self::Settled(BgTaskOutcome::Succeeded),
            "failed" => Self::Settled(BgTaskOutcome::Failed),
            "cancelled" => Self::Settled(BgTaskOutcome::Cancelled),
            "killed" => Self::Settled(BgTaskOutcome::Killed),
            "timed_out" => Self::Settled(BgTaskOutcome::TimedOut),
            "outcome_unknown" => Self::Settled(BgTaskOutcome::OutcomeUnknown),
            _ => return Err("unknown background task status".into()),
        })
    }
    fn as_str(self) -> &'static str {
        match self {
            Self::Starting => "starting",
            Self::Running => "running",
            Self::Cancelling => "cancelling",
            Self::Settled(outcome) => outcome.as_str(),
        }
    }
    fn is_active(self) -> bool {
        !matches!(self, Self::Settled(_))
    }
}
struct BgTask {
    child: Option<Child>,
    stdout: Option<Capture>,
    stderr: Option<Capture>,
    dir: PathBuf,
    // Status is intentionally absent from metadata; the enum is its sole
    // internal source of truth. snapshot() adds the unchanged protocol field.
    metadata: Value,
    status: BgTaskStatus,
    deadline: Option<std::time::Instant>,
    cancel_at: Option<std::time::Instant>,
    terminal_status: Option<BgTaskOutcome>,
    reaped: Option<std::process::ExitStatus>,
}
impl BgTask {
    fn from_metadata(mut metadata: Value) -> Result<Self> {
        let status = BgTaskStatus::parse(&metadata["status"])?;
        metadata
            .as_object_mut()
            .ok_or("background task metadata must be an object")?
            .remove("status");
        Ok(Self {
            child: None,
            stdout: None,
            stderr: None,
            dir: PathBuf::new(),
            metadata,
            status,
            deadline: None,
            cancel_at: None,
            terminal_status: None,
            reaped: None,
        })
    }
    fn prepare(
        metadata: Value,
        stdout: Capture,
        stderr: Capture,
        dir: PathBuf,
        timeout: Option<f64>,
    ) -> Result<Self> {
        let mut task = Self::from_metadata(metadata)?;
        task.stdout = Some(stdout);
        task.stderr = Some(stderr);
        task.dir = dir;
        task.deadline = timeout
            .map(|seconds| std::time::Instant::now() + std::time::Duration::from_secs_f64(seconds));
        Ok(task)
    }
    fn launch(&mut self, command: &mut Command) -> io::Result<()> {
        match command.spawn() {
            Ok(child) => {
                self.status = BgTaskStatus::Running;
                self.metadata["pid"] = json!(child.id());
                self.child = Some(child);
                Ok(())
            }
            Err(error) => {
                self.status = BgTaskStatus::Settled(BgTaskOutcome::Failed);
                Err(error)
            }
        }
    }
    fn finish_launch_failure(&mut self, io: &mut impl CaptureSink, error: io::Error) -> Result<()> {
        self.stderr.as_mut().unwrap().commit(
            io,
            format!("Background launch failed: {error}\n").as_bytes(),
        )?;
        self.metadata["stdout"] = self.stdout.take().unwrap().finish(io, true)?;
        self.metadata["stderr"] = self.stderr.take().unwrap().finish(io, true)?;
        for name in ["stdout", "stderr"] {
            self.metadata[name]
                .as_object_mut()
                .unwrap()
                .remove("preview");
        }
        self.metadata["finished_ms"] = json!(now_ms());
        Ok(())
    }
    fn snapshot(&self) -> Value {
        debug_assert!(self.metadata.get("status").is_none());
        let mut metadata = self.metadata.clone();
        metadata["status"] = json!(self.status.as_str());
        metadata
    }
}
impl Drop for BgTask {
    fn drop(&mut self) {
        if let Some(mut child) = self.child.take() {
            if self.reaped.is_none() {
                unsafe {
                    libc::kill(-(child.id() as i32), libc::SIGKILL);
                }
                let _ = child.kill();
                let _ = child.wait();
            }
        }
        if !self.dir.as_os_str().is_empty() {
            let _ = fs::remove_dir_all(&self.dir);
        }
    }
}
#[cfg(test)]
mod background_status_tests {
    use super::*;

    #[test]
    fn task_status_roundtrips_without_a_duplicate_metadata_field() {
        for status in [
            "starting",
            "running",
            "cancelling",
            "succeeded",
            "failed",
            "cancelled",
            "killed",
            "timed_out",
            "outcome_unknown",
        ] {
            let metadata = json!({"id":"task-status","status":status,"stdout":{"bytes":0}});
            let task = BgTask::from_metadata(metadata.clone()).unwrap();
            assert!(task.metadata.get("status").is_none());
            assert_eq!(task.status.as_str(), status);
            assert_eq!(task.snapshot(), metadata);
            assert_eq!(
                task.status.is_active(),
                matches!(status, "starting" | "running" | "cancelling")
            );
        }
    }

    #[test]
    fn missing_or_malformed_task_status_is_not_a_terminal_default() {
        for metadata in [
            json!({"id":"task"}),
            json!({"id":"task","status":null}),
            json!({"id":"task","status":123}),
            json!({"id":"task","status":"finished"}),
            json!({"id":"task","status":"typo"}),
        ] {
            assert!(BgTask::from_metadata(metadata).is_err());
        }
    }
}
#[derive(Clone, Debug, PartialEq)]
enum WakeupState {
    Scheduled,
    Ready,
    PendingConfirmation,
    Dispatching,
    Consumed,
    Cancelled,
    OutcomeUnknown,
    // Preserve unknown historical extension states without assigning effects.
    Unknown(Value),
    Missing,
}
impl WakeupState {
    fn parse(value: Value) -> Self {
        match value.as_str() {
            Some("scheduled") => Self::Scheduled,
            Some("ready") => Self::Ready,
            Some("pending_confirmation") => Self::PendingConfirmation,
            Some("dispatching") => Self::Dispatching,
            Some("consumed") => Self::Consumed,
            Some("cancelled") => Self::Cancelled,
            Some("outcome_unknown") => Self::OutcomeUnknown,
            _ => Self::Unknown(value),
        }
    }
    fn value(&self) -> Value {
        match self {
            Self::Scheduled => json!("scheduled"),
            Self::Ready => json!("ready"),
            Self::PendingConfirmation => json!("pending_confirmation"),
            Self::Dispatching => json!("dispatching"),
            Self::Consumed => json!("consumed"),
            Self::Cancelled => json!("cancelled"),
            Self::OutcomeUnknown => json!("outcome_unknown"),
            Self::Unknown(value) => value.clone(),
            Self::Missing => Value::Null,
        }
    }
    fn pending(&self) -> bool {
        matches!(
            self,
            Self::Scheduled | Self::Ready | Self::PendingConfirmation
        )
    }
}
struct Wakeup {
    metadata: Value,
    state: WakeupState,
    deadline: Option<std::time::Instant>,
}
impl Wakeup {
    fn from_metadata(mut metadata: Value, deadline: Option<std::time::Instant>) -> Result<Self> {
        let object = metadata.as_object_mut().ok_or("invalid wakeup metadata")?;
        let state = object
            .remove("state")
            .map(WakeupState::parse)
            .unwrap_or(WakeupState::Missing);
        Ok(Self {
            metadata,
            state,
            deadline,
        })
    }
    fn snapshot(&self) -> Value {
        let mut metadata = self.metadata.clone();
        if self.state != WakeupState::Missing {
            metadata["state"] = self.state.value();
        }
        metadata
    }
}
enum TaskKind {
    Shell,
    Python,
}
impl TaskKind {
    fn label(&self) -> &'static str {
        match self {
            Self::Shell => "shell",
            Self::Python => "python",
        }
    }
    fn command(&self, source: &str) -> Command {
        match self {
            Self::Shell => {
                let mut command = Command::new("/bin/sh");
                command.args(["-c", source]);
                command
            }
            Self::Python => {
                let mut command =
                    Command::new(std::env::var("PY_PYTHON").unwrap_or_else(|_| "python3".into()));
                command.args(["-u", "-c", source]);
                command
            }
        }
    }
}
struct TaskLaunch {
    source: String,
    kind: TaskKind,
    name: Option<String>,
    wakeup_reason: Option<String>,
    timeout: Option<f64>,
    cwd: Option<String>,
    env: Vec<(String, String)>,
}
impl TaskLaunch {
    fn decode(value: &Value) -> Result<Self> {
        let source = value["source"]
            .as_str()
            .ok_or("background source required")?;
        if source.trim().is_empty() {
            return Err("background source must not be empty".into());
        }
        let kind = match value.get("task_kind").or_else(|| value.get("kind")) {
            None => TaskKind::Shell,
            Some(value) => match value.as_str().ok_or("background kind must be a string")? {
                "shell" => TaskKind::Shell,
                "python" => TaskKind::Python,
                _ => return Err("background kind must be shell or python".into()),
            },
        };
        let options = value
            .get("options")
            .filter(|option| !option.is_null())
            .unwrap_or(value);
        if !options.is_object() {
            return Err("background options must be an object".into());
        }
        let name = bg_text(options, "name", 128)?.map(str::to_owned);
        let wakeup_reason = bg_text(options, "wakeup_reason", 512)?.map(str::to_owned);
        let timeout = bg_seconds(&options["timeout"], 604800.0)?;
        let cwd = match options.get("cwd") {
            None | Some(Value::Null) => None,
            Some(Value::String(path)) => Some(path.clone()),
            _ => return Err("cwd must be a string".into()),
        };
        let mut env = Vec::new();
        if let Some(value) = options.get("env").filter(|value| !value.is_null()) {
            for (key, value) in value.as_object().ok_or("env must be an object")? {
                if key.is_empty() || key.contains(['=', '\0']) {
                    return Err("invalid environment key".into());
                }
                let value = value.as_str().ok_or("environment values must be strings")?;
                if value.contains('\0') {
                    return Err("invalid environment value".into());
                }
                env.push((key.clone(), value.to_owned()));
            }
        }
        Ok(Self {
            source: source.to_owned(),
            kind,
            name,
            wakeup_reason,
            timeout,
            cwd,
            env,
        })
    }
}
#[derive(Default)]
struct TaskScheduler {
    tasks: HashMap<String, BgTask>,
    wakeups: HashMap<String, Wakeup>,
}
impl TaskScheduler {
    fn prepare_launch(&self, value: &Value) -> Result<TaskLaunch> {
        if self.active_count() >= 4 {
            return Err("at most four active background jobs".into());
        }
        TaskLaunch::decode(value)
    }
    fn task_ids(&self) -> impl Iterator<Item = &String> {
        self.tasks.keys()
    }
    fn wakeup_ids(&self) -> impl Iterator<Item = &String> {
        self.wakeups.keys()
    }
    fn task_count(&self) -> usize {
        self.tasks.len()
    }
    fn new_task(&self, previous: &HashSet<String>) -> Option<Value> {
        self.tasks
            .iter()
            .find(|(id, _)| !previous.contains(*id))
            .map(|(_, task)| task.snapshot())
    }
    fn active_count(&self) -> usize {
        self.tasks
            .values()
            .filter(|task| task.child.is_some())
            .count()
    }
    fn has_poll_work(&self) -> bool {
        self.tasks.values().any(|task| task.child.is_some())
            || self
                .wakeups
                .values()
                .any(|wakeup| wakeup.state == WakeupState::Scheduled && wakeup.deadline.is_some())
    }
    fn pending_count(&self) -> usize {
        self.wakeups.values().filter(|w| w.state.pending()).count()
    }
    fn has_ready(&self) -> bool {
        self.wakeups.values().any(|w| w.state == WakeupState::Ready)
    }
    fn active_ids(&self) -> Vec<String> {
        self.tasks
            .iter()
            .filter_map(|(id, task)| task.child.as_ref().map(|_| id.clone()))
            .collect()
    }
    fn is_active(&self, id: &str) -> bool {
        self.tasks.get(id).is_some_and(|task| task.child.is_some())
    }
    fn insert_task(&mut self, id: String, task: BgTask) {
        self.tasks.insert(id, task);
    }
    fn list(&self, state: Option<&str>) -> Result<Value> {
        let exact = match state {
            None | Some("all" | "finished") => None,
            Some(state) => {
                Some(BgTaskStatus::parse(&json!(state)).map_err(|_| "unknown task state filter")?)
            }
        };
        let mut tasks: Vec<_> = self
            .tasks
            .values()
            .filter(|task| {
                exact.is_none_or(|status| task.status == status)
                    && (state != Some("finished") || !task.status.is_active())
            })
            .map(BgTask::snapshot)
            .collect();
        tasks.sort_by_key(|metadata| metadata["created_ms"].as_u64().unwrap_or(0));
        Ok(json!(tasks))
    }
    fn get(&self, id: &str) -> Result<Value> {
        Ok(self.tasks.get(id).ok_or("unknown task ID")?.snapshot())
    }
    fn kill(&mut self, id: &str, force: bool) -> Result<Option<Value>> {
        let task = self.tasks.get_mut(id).ok_or("unknown task ID")?;
        let Some(child) = task.child.as_ref().filter(|_| task.reaped.is_none()) else {
            return Ok(None);
        };
        let signal = if force { libc::SIGKILL } else { libc::SIGTERM };
        if unsafe { libc::kill(-(child.id() as i32), signal) } < 0
            && io::Error::last_os_error().raw_os_error() != Some(libc::ESRCH)
        {
            return Err(io::Error::last_os_error().into());
        }
        if task.cancel_at.is_none() {
            task.cancel_at = Some(std::time::Instant::now());
            task.terminal_status = Some(if force {
                BgTaskOutcome::Killed
            } else {
                BgTaskOutcome::Cancelled
            });
        } else if force && task.terminal_status != Some(BgTaskOutcome::TimedOut) {
            task.terminal_status = Some(BgTaskOutcome::Killed);
        }
        task.status = BgTaskStatus::Cancelling;
        Ok(Some(task.snapshot()))
    }
    fn save_task(
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
        metadata: &Value,
    ) -> Result<()> {
        BgTaskStatus::parse(&metadata["status"])?;
        io.journal.append("task_state", metadata.clone())?;
        emit("task_state", metadata.clone());
        Ok(())
    }
    fn save_wakeup(
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
        metadata: &Value,
    ) -> Result<()> {
        io.journal.append("wakeup_state", metadata.clone())?;
        emit("wakeup_state", metadata.clone());
        Ok(())
    }
    fn settle(
        &mut self,
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
        metadata: &Value,
    ) -> Result<()> {
        if BgTaskStatus::parse(&metadata["status"])?.is_active() {
            return Err("cannot settle an active background task".into());
        }
        let wakeup = metadata["wakeup_reason"].as_str().map(|reason| json!({
            "id":format!("wake{}",io.journal.seq),"reason":reason,"due_ms":now_ms(),"state":"ready","task":metadata}));
        io.journal.append("task_settled", json!({"operation":metadata["id"],"status":metadata["status"],"task":metadata,"wakeup":wakeup}))?;
        emit("task_state", metadata.clone());
        if let Some(wakeup) = wakeup {
            emit("wakeup_state", wakeup.clone());
            self.wakeups.insert(
                wakeup["id"].as_str().unwrap().into(),
                Wakeup::from_metadata(wakeup, None)?,
            );
        }
        Ok(())
    }
    fn abort(&mut self) {
        for task in self.tasks.values_mut() {
            if let Some(mut child) = task.child.take() {
                if task.reaped.is_none() {
                    unsafe {
                        libc::kill(-(child.id() as i32), libc::SIGKILL);
                    }
                    let _ = child.kill();
                    let _ = child.wait();
                }
                task.status = BgTaskStatus::Settled(BgTaskOutcome::OutcomeUnknown);
                task.metadata.as_object_mut().unwrap().remove("pid");
                for name in ["stdout", "stderr"] {
                    task.metadata[name]["complete"] = json!(false);
                }
            }
        }
    }
    fn poll(
        &mut self,
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
    ) -> Result<()> {
        for id in self.active_ids() {
            let mut task = self.tasks.remove(&id).unwrap();
            let result = (|| -> Result<()> {
                let more_out = if let Some(out) = task.stdout.as_mut() {
                    let more = out.drain(io)?;
                    task.metadata["stdout"]["bytes"] = json!(out.bytes);
                    task.metadata["stdout"]["chars"] =
                        json!(out.chars + String::from_utf8_lossy(&out.carry).chars().count());
                    more
                } else {
                    false
                };
                let more_err = if let Some(err) = task.stderr.as_mut() {
                    let more = err.drain(io)?;
                    task.metadata["stderr"]["bytes"] = json!(err.bytes);
                    task.metadata["stderr"]["chars"] =
                        json!(err.chars + String::from_utf8_lossy(&err.carry).chars().count());
                    more
                } else {
                    false
                };
                let now = std::time::Instant::now();
                let pid = task.child.as_ref().unwrap().id() as i32;
                let mut exit = if let Some(exit) = task.reaped {
                    Some(exit)
                } else {
                    task.child.as_mut().unwrap().try_wait()?
                };
                if exit.is_none() {
                    if task.cancel_at.is_none()
                        && task.deadline.is_some_and(|deadline| now >= deadline)
                    {
                        unsafe {
                            libc::kill(-pid, libc::SIGTERM);
                        }
                        task.cancel_at = Some(now);
                        task.terminal_status = Some(BgTaskOutcome::TimedOut);
                        task.status = BgTaskStatus::Cancelling;
                        Self::save_task(io, emit, &task.snapshot())?;
                    }
                    if task.cancel_at.is_some_and(|at| {
                        now.duration_since(at) >= std::time::Duration::from_millis(500)
                    }) {
                        unsafe {
                            libc::kill(-pid, libc::SIGKILL);
                        }
                        exit = task.child.as_mut().unwrap().try_wait()?;
                    }
                }
                if let Some(exit) = exit {
                    if task.reaped.is_none() {
                        unsafe {
                            libc::kill(-pid, libc::SIGKILL);
                        }
                        task.reaped = Some(exit);
                        return Ok(());
                    }
                    if more_out || more_err {
                        return Ok(());
                    }
                    task.child.take();
                    task.metadata["stdout"] =
                        task.stdout.take().unwrap().finish_metadata(io, true)?;
                    task.metadata["stderr"] =
                        task.stderr.take().unwrap().finish_metadata(io, true)?;
                    for key in ["stdout", "stderr"] {
                        task.metadata[key]
                            .as_object_mut()
                            .unwrap()
                            .remove("preview");
                    }
                    task.status =
                        BgTaskStatus::Settled(task.terminal_status.unwrap_or_else(|| {
                            if exit.success() {
                                BgTaskOutcome::Succeeded
                            } else {
                                BgTaskOutcome::Failed
                            }
                        }));
                    task.metadata["exit_code"] = json!(exit.code());
                    task.metadata["finished_ms"] = json!(now_ms());
                    self.settle(io, emit, &task.snapshot())?;
                }
                Ok(())
            })();
            self.tasks.insert(id, task);
            result?;
        }
        let mut ready = Vec::new();
        for wakeup in self.wakeups.values_mut() {
            if wakeup.state == WakeupState::Scheduled
                && wakeup
                    .deadline
                    .is_some_and(|due| due <= std::time::Instant::now())
            {
                wakeup.state = WakeupState::Ready;
                ready.push(wakeup.snapshot());
            }
        }
        for metadata in ready {
            Self::save_wakeup(io, emit, &metadata)?;
        }
        Ok(())
    }
    fn schedule(
        &mut self,
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
        seconds: f64,
        reason: &str,
        task: Option<Value>,
    ) -> Result<Value> {
        bg_seconds(&json!(seconds), 604800.0)?;
        bg_text(&json!({"reason":reason}), "reason", 512)?;
        let metadata = json!({"id":format!("wake{}",io.journal.seq),"reason":reason,
            "due_ms":now_ms()+(seconds*1000.0).ceil() as u128,"state":"scheduled","task":task,"stop_settled":task.is_none()});
        Self::save_wakeup(io, emit, &metadata)?;
        self.wakeups.insert(
            metadata["id"].as_str().unwrap().into(),
            Wakeup::from_metadata(
                metadata.clone(),
                Some(std::time::Instant::now() + std::time::Duration::from_secs_f64(seconds)),
            )?,
        );
        Ok(metadata)
    }
    fn wakeup_list(&self) -> Value {
        let mut entries: Vec<_> = self.wakeups.values().map(Wakeup::snapshot).collect();
        entries.sort_by_key(|metadata| metadata["due_ms"].as_u64().unwrap_or(0));
        json!(entries)
    }
    fn cancelled_wakeup(&self, id: &str) -> Option<Value> {
        self.wakeups
            .get(id)
            .filter(|wakeup| wakeup.state == WakeupState::Cancelled)
            .map(Wakeup::snapshot)
    }
    fn change_wakeup(&mut self, id: &str, state: WakeupState) -> Result<Value> {
        let wakeup = self.wakeups.get_mut(id).ok_or("unknown wakeup ID")?;
        if state == WakeupState::Cancelled && wakeup.state == WakeupState::Cancelled {
            return Ok(wakeup.snapshot());
        }
        if !wakeup.state.pending() {
            return Err("wakeup is already settled".into());
        }
        wakeup.state = state;
        Ok(wakeup.snapshot())
    }
    fn ready_ids(&self) -> Vec<String> {
        let mut ids: Vec<_> = self
            .wakeups
            .iter()
            .filter_map(|(id, wakeup)| (wakeup.state == WakeupState::Ready).then_some(id.clone()))
            .collect();
        ids.sort();
        ids
    }
    fn dispatch_wakeup(&mut self, id: &str, state: WakeupState) -> Value {
        let wakeup = self.wakeups.get_mut(id).expect("selected wakeup missing");
        wakeup.state = state;
        wakeup.snapshot()
    }
    fn restore(&mut self, kind: &JournalEventKind, payload: &Value) -> Result<()> {
        if kind == &JournalEventKind::TaskSettled {
            let status = BgTaskStatus::parse(&payload["status"])?;
            if status.is_active() || status != BgTaskStatus::parse(&payload["task"]["status"])? {
                return Err("invalid settled background task status".into());
            }
            self.restore(&JournalEventKind::TaskState, &payload["task"])?;
            if !payload["wakeup"].is_null() {
                self.restore(&JournalEventKind::WakeupState, &payload["wakeup"])?;
            }
            return Ok(());
        }
        let id = payload["id"]
            .as_str()
            .ok_or("invalid background journal ID")?
            .to_owned();
        match kind {
            JournalEventKind::TaskState => {
                self.tasks
                    .insert(id, BgTask::from_metadata(payload.clone())?);
            }
            JournalEventKind::WakeupState => {
                self.wakeups
                    .insert(id, Wakeup::from_metadata(payload.clone(), None)?);
            }
            _ => {}
        }
        Ok(())
    }
    fn recover(
        &mut self,
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
    ) -> Result<()> {
        let mut tasks = Vec::new();
        let mut wakeups = Vec::new();
        for task in self.tasks.values_mut() {
            if task.status.is_active() {
                task.status = BgTaskStatus::Settled(BgTaskOutcome::OutcomeUnknown);
                task.metadata["replay_allowed"] = json!(false);
                task.metadata.as_object_mut().unwrap().remove("pid");
                for name in ["stdout", "stderr"] {
                    let mut bytes = 0usize;
                    let mut chars = 0usize;
                    let mut carry = Vec::new();
                    if let Some(index) = task.metadata[name]["index"].as_u64() {
                        if let Some(chunks) = io
                            .history
                            .stream_chunks(RecordCollection::decode(name)?, index as usize)
                        {
                            for seq in chunks {
                                let event = io.journal.decoded_event(*seq)?;
                                let JournalEventData::Stream(stream) = &event.data else {
                                    return Err("invalid stream bytes".into());
                                };
                                let data =
                                    stream.base64.as_deref().ok_or("invalid stream bytes")?;
                                let chunk = B64.decode(data)?;
                                bytes += chunk.len();
                                chars += decode_output(&mut carry, &chunk, false).chars().count();
                            }
                        }
                    }
                    chars += decode_output(&mut carry, &[], true).chars().count();
                    task.metadata[name]["bytes"] = json!(bytes);
                    task.metadata[name]["chars"] = json!(chars);
                    task.metadata[name]["complete"] = json!(false);
                }
                tasks.push(task.snapshot());
            }
        }
        for wakeup in self.wakeups.values_mut() {
            if matches!(
                wakeup.state,
                WakeupState::Scheduled | WakeupState::Ready | WakeupState::Dispatching
            ) {
                wakeup.state = if wakeup.state == WakeupState::Dispatching {
                    WakeupState::OutcomeUnknown
                } else {
                    WakeupState::PendingConfirmation
                };
                wakeups.push(wakeup.snapshot());
            }
        }
        for metadata in tasks {
            Self::save_task(io, emit, &metadata)?;
        }
        for metadata in wakeups {
            Self::save_wakeup(io, emit, &metadata)?;
        }
        Ok(())
    }
    fn finish_partial(
        &mut self,
        io: &mut CaptureSession<'_>,
        emit: &mut dyn FnMut(&str, Value),
        id: &str,
    ) -> Result<()> {
        let mut task = self.tasks.remove(id).expect("active task missing");
        let result = (|| -> Result<()> {
            if let Some(mut child) = task.child.take() {
                if task.reaped.is_none() {
                    child.wait()?;
                }
                task.metadata["stdout"] = task.stdout.take().unwrap().finish_metadata(io, false)?;
                task.metadata["stderr"] = task.stderr.take().unwrap().finish_metadata(io, false)?;
                for name in ["stdout", "stderr"] {
                    task.metadata[name]
                        .as_object_mut()
                        .unwrap()
                        .remove("preview");
                }
                task.status =
                    BgTaskStatus::Settled(task.terminal_status.unwrap_or(BgTaskOutcome::Cancelled));
                task.metadata["finished_ms"] = json!(now_ms());
                self.settle(io, emit, &task.snapshot())?;
            }
            Ok(())
        })();
        self.tasks.insert(id.to_owned(), task);
        result
    }
}
impl Host {
    fn commit_stop(&mut self) -> Result<()> {
        if let Some((seconds, reason)) = self.execution.take_wakeup() {
            // One durable event commits both settled stop and its timer.
            self.schedule_wakeup(seconds, &reason, None)?;
        }
        Ok(())
    }
    fn background_control(&mut self, v: &NativeCommand) -> Result<bool> {
        if !v.kind.background() {
            return Ok(false);
        }
        if !self.accept_input_control(v)? {
            return Ok(true);
        }
        if let Err(e) = self.finish_background_control(v) {
            self.event("error", json!({"command_id":v.id,"error":e.to_string()}));
        }
        Ok(true)
    }
    fn finish_background_control(&mut self, v: &NativeCommand) -> Result<()> {
        let result = match v.kind {
            NativeCommandKind::TaskList => self.bg_list(v.args.task_state.require()?.as_deref())?,
            NativeCommandKind::TaskGet | NativeCommandKind::TaskLogs => {
                let metadata = self.bg_get(v.args.task_id.require()?)?;
                if v.kind == NativeCommandKind::TaskLogs {
                    let stream = *v.args.stream.require()?;
                    let mut logs = json!({"task":metadata});
                    for name in ["stdout", "stderr"] {
                        if stream.includes(name) {
                            logs[name] = json!({"ref":logs["task"][name]["ref"],"preview":self.ui_stream_preview(name,logs["task"][name]["index"].as_u64().ok_or("missing stream index")? as usize)?});
                        }
                    }
                    logs
                } else {
                    metadata
                }
            }
            NativeCommandKind::TaskKill => {
                self.bg_kill(v.args.task_id.require()?, *v.args.force.require()?)?
            }
            NativeCommandKind::WakeupList => self.wakeup_list()?,
            NativeCommandKind::WakeupCancel => self.wakeup_cancel(v.args.wakeup_id.require()?)?,
            NativeCommandKind::WakeupRun => self.wakeup_run(v.args.wakeup_id.require()?)?,
            _ => return Err("unknown background control".into()),
        };
        self.event(
            "completed",
            json!({"command_id":v.id,"status":"ok","result":result}),
        );
        Ok(())
    }
}
#[cfg(test)]
mod scheduler_frontend_tests {
    use super::*;
    struct Scratch(crate::test_support::TestDirectory);
    impl Scratch {
        fn new() -> Self {
            Self(crate::test_support::TestDirectory::new(
                "py-scheduler-frontend",
            ))
        }
    }
    fn histories() -> HistoryArchive {
        HistoryArchive::default()
    }
    #[test]
    fn idle_scheduler_polls_do_not_serialize_context_or_footer_status() {
        let scratch = Scratch::new();
        fs::write(
            scratch.0.join("config.json"),
            json!({"skills":{"enabled":false}}).to_string(),
        )
        .unwrap();
        let mut host = Host::new(scratch.0.to_path_buf(), None, true, true, None, None).unwrap();
        let before = STATUS_SNAPSHOT_CALLS.with(std::cell::Cell::get);
        for _ in 0..1024 {
            host.service_background().unwrap();
            host.scheduler_operation(|_, _, _| Ok(())).unwrap();
        }
        assert_eq!(STATUS_SNAPSHOT_CALLS.with(std::cell::Cell::get), before);
        host.state_payload();
        assert_eq!(STATUS_SNAPSHOT_CALLS.with(std::cell::Cell::get), before + 1);
    }
    #[test]
    fn scheduler_poll_work_includes_future_deadlines_but_not_ready_or_recovered_wakeups() {
        let mut scheduler = TaskScheduler::default();
        assert!(!scheduler.has_poll_work());
        for state in ["ready", "pending_confirmation", "cancelled", "scheduled"] {
            scheduler.wakeups.insert(
                state.into(),
                Wakeup::from_metadata(
                    json!({"id":state,"state":state,"due_ms":0,"reason":"test"}),
                    None,
                )
                .unwrap(),
            );
        }
        assert!(!scheduler.has_poll_work());
        scheduler.wakeups.get_mut("scheduled").unwrap().deadline =
            Some(std::time::Instant::now() + std::time::Duration::from_secs(60));
        assert!(scheduler.has_poll_work());
        scheduler.wakeups.get_mut("scheduled").unwrap().state = WakeupState::Ready;
        assert!(!scheduler.has_poll_work());
    }
    #[test]
    fn recovered_tasks_and_wakeups_have_owned_states_without_pid_or_replay() {
        let scratch = Scratch::new();
        let mut journal = Journal::open(scratch.0.join("session.jsonl")).unwrap();
        let mut history = histories();
        let mut scheduler = TaskScheduler::default();
        scheduler.restore(&JournalEventKind::TaskState, &json!({"id":"old-task","status":"running","pid":12345,
            "stdout":{"index":0,"bytes":9,"complete":true},"stderr":{"index":0,"bytes":5,"complete":true}})).unwrap();
        for state in ["scheduled", "ready", "dispatching", "cancelled"] {
            scheduler
                .restore(
                    &JournalEventKind::WakeupState,
                    &json!({"id":state,"state":state,"reason":"continuation","due_ms":0}),
                )
                .unwrap();
        }
        let mut notices = Vec::new();
        let mut io = CaptureSession {
            journal: &mut journal,
            history: &mut history,
            owner: None,
        };
        scheduler
            .recover(&mut io, &mut |kind, value| {
                notices.push((kind.to_owned(), value))
            })
            .unwrap();
        let task = scheduler.get("old-task").unwrap();
        assert_eq!(task["status"], "outcome_unknown");
        assert_eq!(task["replay_allowed"], false);
        assert!(task.get("pid").is_none());
        assert_eq!(scheduler.active_count(), 0);
        assert_eq!(task["stdout"]["complete"], false);
        assert!(!scheduler.has_ready());
        assert_eq!(scheduler.pending_count(), 2);
        assert_eq!(
            scheduler.wakeups["scheduled"].snapshot()["state"],
            "pending_confirmation"
        );
        assert_eq!(
            scheduler.wakeups["dispatching"].snapshot()["state"],
            "outcome_unknown"
        );
        assert_eq!(
            scheduler.wakeups["cancelled"].snapshot()["state"],
            "cancelled"
        );
        assert_eq!(notices.len(), 4);
        scheduler
            .change_wakeup("ready", WakeupState::Ready)
            .unwrap();
        assert_eq!(scheduler.ready_ids(), vec!["ready".to_owned()]);
        assert_eq!(
            scheduler.dispatch_wakeup("ready", WakeupState::Dispatching)["state"],
            "dispatching"
        );
        assert!(scheduler
            .change_wakeup("ready", WakeupState::Ready)
            .is_err());
        assert_eq!(
            scheduler.dispatch_wakeup("ready", WakeupState::Consumed)["state"],
            "consumed"
        );
    }
    #[test]
    fn wakeup_state_has_one_interpretation_and_preserves_opaque_unknown_states() {
        for metadata in [
            json!({"id":"absent"}),
            json!({"id":"null","state":null}),
            json!({"id":"extension","state":"future-state"}),
            json!({"id":"opaque","state":{"future":1}}),
        ] {
            let wakeup = Wakeup::from_metadata(metadata.clone(), None).unwrap();
            assert!(wakeup.metadata.get("state").is_none());
            assert_eq!(wakeup.snapshot(), metadata);
            assert!(!wakeup.state.pending());
        }
        assert!(WakeupState::Ready.pending());
        assert!(!WakeupState::OutcomeUnknown.pending());
    }
    #[test]
    fn task_settlement_and_wakeup_creation_share_one_commit_and_never_admit_payloads() {
        let scratch = Scratch::new();
        let mut journal = Journal::open(scratch.0.join("session.jsonl")).unwrap();
        let mut history = histories();
        let mut scheduler = TaskScheduler::default();
        let mut notices = Vec::new();
        {
            let mut io = CaptureSession {
                journal: &mut journal,
                history: &mut history,
                owner: None,
            };
            scheduler.settle(&mut io, &mut |kind, value| notices.push((kind.to_owned(), value)),
                &json!({"id":"done","status":"succeeded","wakeup_reason":"inspect refs","stdout":{"ref":"H.records.stdout[0]"}})).unwrap();
        }
        assert_eq!(journal.seq, 1);
        assert_eq!(
            journal.decoded_event(0).unwrap().kind,
            JournalEventKind::TaskSettled
        );
        assert_eq!(scheduler.pending_count(), 1);
        assert!(scheduler.has_ready());
        assert_eq!(
            notices
                .iter()
                .map(|(kind, _)| kind.as_str())
                .collect::<Vec<_>>(),
            vec!["task_state", "wakeup_state"]
        );
        assert!(history.is_empty());
        let path = scratch.0.join("failed.jsonl");
        let mut failed = Journal::open(path).unwrap();
        failed.failed = true;
        let mut scheduler = TaskScheduler::default();
        let mut io = CaptureSession {
            journal: &mut failed,
            history: &mut history,
            owner: None,
        };
        assert!(scheduler
            .settle(
                &mut io,
                &mut |_, _| panic!("failed commit must not emit"),
                &json!({"id":"done","status":"succeeded","wakeup_reason":"no replay"})
            )
            .is_err());
        assert_eq!(scheduler.pending_count(), 0);
        assert_eq!(failed.seq, 0);
    }
    #[test]
    fn task_launch_decodes_once_and_keeps_python_environment_and_options_semantics() {
        let task = TaskLaunch::decode(&json!({"source":"print(42)","task_kind":"python",
            "options":{"cwd":"/tmp","env":{"A":"λ"},"timeout":1.25,"name":"test"}}))
        .unwrap();
        assert_eq!(task.kind.label(), "python");
        assert_eq!(task.source, "print(42)");
        assert_eq!(task.env, vec![("A".to_owned(), "λ".to_owned())]);
        assert_eq!(task.timeout, Some(1.25));
        for value in [
            json!({"source":""}),
            json!({"source":"true","task_kind":true}),
            json!({"source":"true","task_kind":"bad"}),
            json!({"source":"true","options":{"env":{"=":"bad"}}}),
            json!({"source":"true","options":{"timeout":-1}}),
        ] {
            assert!(TaskLaunch::decode(&value).is_err());
        }
    }
    #[test]
    fn frontend_phase_restore_preserves_outer_clock_draft_and_command_policy() {
        let mut frontend = TerminalFrontend::new();
        assert!(frontend.transition(UiState::Thinking, Some("outer".into())));
        let before = frontend.phase();
        assert!(!frontend.transition(UiState::Thinking, Some("outer".into())));
        assert_eq!(frontend.phase.started, before.started);
        assert!(frontend.transition(UiState::Running, None));
        assert!(frontend.restore_phase(before.clone()));
        assert_eq!(frontend.phase.started, before.started);
        let mut draft = EditBuffer::default();
        draft.line = "draft-tail".into();
        draft.cursor = 5;
        draft.killed = "saved".into();
        frontend.save_draft(draft);
        let id = "after".to_owned();
        frontend.queue_command(LocalCommand {
            id: id.clone(),
            parsed: ParsedLocalCommand::parse("/new"),
            phase: LocalCommandPhase::AfterTurn,
        });
        assert!(frontend.has_after_turn_command());
        assert_eq!(
            frontend.next_command_phase(),
            Some(LocalCommandPhase::AfterTurn)
        );
        assert_eq!(frontend.pop_command().unwrap().id, id);
        assert!(!frontend.has_commands());
        let draft = frontend.take_draft();
        assert_eq!(draft.line, "draft-tail");
        assert_eq!(draft.cursor, 5);
        assert_eq!(draft.killed, "saved");
        frontend.admit_visible_change().unwrap();
        assert_eq!(frontend.visible_revision(), 1);
    }
    #[test]
    fn prompt_ownership_joins_busy_reader_preserves_nested_boundary_and_keeps_draft() {
        let scratch = Scratch::new();
        let output = scratch.0.join("terminal-output");
        let terminal = EditTerminal {
            io: TerminalIo {
                input: File::open("/dev/null").unwrap(),
                _raw: None,
                eof_message: "closed",
                read_interrupt_is_timeout: true,
            },
            output: OpenOptions::new()
                .write(true)
                .create_new(true)
                .mode(0o600)
                .open(&output)
                .unwrap(),
            cursor_row: 0,
            rows: 1,
            keyboard: false,
            display: false,
            headers: Vec::new(),
            picker_active: false,
        };
        let mut buffer = EditBuffer::default();
        buffer.line = "draft-middle-tail".into();
        buffer.cursor = 12;
        let display = std::sync::Arc::new(std::sync::Mutex::new(BusyDisplay {
            terminal,
            buffer,
            status: json!({"state":"running","cell":2,"cells":2}),
            began: std::time::Instant::now(),
            sampled: std::time::Instant::now(),
            pending_boundary: Some(
                json!({"cell":2,"parent_cell":1,"language":"shell","elapsed_ms":1,"status":"ok"}),
            ),
            cache: std::sync::Arc::new(std::sync::Mutex::new(BusyEditorCache::default())),
            completion: None,
        }));
        let stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let joined = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let reader_stop = stop.clone();
        let reader_joined = joined.clone();
        let thread = std::thread::spawn(move || {
            while !reader_stop.load(std::sync::atomic::Ordering::SeqCst) {
                std::thread::sleep(std::time::Duration::from_millis(1));
            }
            reader_joined.store(true, std::sync::atomic::Ordering::SeqCst);
        });
        let (sender, lines) = std::sync::mpsc::channel();
        sender.send(("queued".into(), "steer".into())).unwrap();
        let mut frontend = TerminalFrontend::new();
        frontend.input = InputOwnership::Busy(BusyInput {
            stop,
            lines,
            display,
            thread,
        });
        let lines = frontend
            .acquire_prompt(json!({"state":"running","cell":1,"cells":2}))
            .unwrap();
        assert!(joined.load(std::sync::atomic::Ordering::SeqCst));
        assert_eq!(lines, vec![("queued".to_owned(), "steer".to_owned())]);
        assert!(matches!(
            frontend.input,
            InputOwnership::PromptExclusive { resume_busy: true }
        ));
        assert!(!frontend.start_busy(json!({})));
        assert!(frontend.acquire_prompt(json!({})).is_err());
        assert!(fs::read_to_string(output)
            .unwrap()
            .contains("  ↳ cell 1 › 2 · shell"));
        assert!(frontend.release_prompt());
        assert!(matches!(frontend.input, InputOwnership::Idle));
        let draft = frontend.take_draft();
        assert_eq!(draft.line, "draft-middle-tail");
        assert_eq!(draft.cursor, 12);
        assert!(!frontend.release_prompt());
    }
}
fn bg_text<'a>(v: &'a Value, key: &str, max: usize) -> Result<Option<&'a str>> {
    match v.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(s)) if !s.trim().is_empty() && s.chars().count() <= max => Ok(Some(s)),
        _ => Err(format!("{key} must be a nonempty string of at most {max} characters").into()),
    }
}
fn bg_seconds(v: &Value, max: f64) -> Result<Option<f64>> {
    if v.is_null() {
        return Ok(None);
    }
    let seconds = v.as_f64().ok_or("duration must be a number")?;
    if !seconds.is_finite() || seconds <= 0.0 || seconds > max {
        return Err(format!("duration must be finite, positive and at most {max} seconds").into());
    }
    Ok(Some(seconds))
}
#[cfg(test)]
thread_local! {
    static STATUS_SNAPSHOT_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}
// Borrow only the immutable owners needed for a footer. Constructing these
// inputs is cheap; serializing them is deferred until a renderer needs them.
struct StatusSnapshotInputs<'a> {
    frontend: &'a TerminalFrontend,
    execution: &'a ExecutionController,
    provider: &'a ProviderClient,
    context: &'a ContextStore,
    skills: &'a Value,
    last_generation_failed: bool,
    active_background_tasks: usize,
}
impl StatusSnapshotInputs<'_> {
    fn context_usage(&self) -> Value {
        let system_chars = self.skills["system"]
            .as_str()
            .unwrap_or(SYSTEM)
            .chars()
            .count();
        let chars = self.context.rendered_chars(system_chars);
        let estimated_tokens = chars.div_ceil(3);
        let input_budget = model_input_budget(
            self.provider.context_limit,
            &self.provider.reasoning_metadata(&self.provider.model),
            4096,
        );
        json!({"context_revision":self.context.revision(),"item_count":self.context.items().len(),
            "rendered_chars":chars,"estimated_input_tokens":estimated_tokens,
            "measured_last_input_tokens":self.provider.usage["last_input_tokens"],
            "model_context_limit":self.provider.context_limit,"reserved_output_tokens":4096,
            "input_token_budget":input_budget,"remaining_input_tokens":input_budget.saturating_sub(estimated_tokens),
            "system_chars":system_chars,"skills_estimated_tokens":self.skills["estimated_added_tokens"],
            "forced":estimated_tokens>input_budget*9/10,"force_threshold":0.9,
            "estimator":"unicode-chars/3-v1 estimate; system/control allowance included; image budget separate"})
    }
    fn payload(&self) -> Value {
        #[cfg(test)]
        STATUS_SNAPSHOT_CALLS.with(|calls| calls.set(calls.get() + 1));
        let mut payload = json!({"active_background_tasks":self.active_background_tasks,"state":self.frontend.state().label(),"cell":self.execution.cell(),"cells":self.execution.cells(),
            "language":self.execution.language(),"cell_elapsed_ms":self.execution.started().map(|start|start.elapsed().as_millis().min(u64::MAX as u128) as u64),
            "thinking_elapsed_ms":self.frontend.thinking_elapsed(),
            "selected_model":self.provider.model(),"effort":self.provider.effort(),
            "context_usage":self.context_usage(),"cache_hit_tokens":self.provider.usage["cache_hit_tokens"],
            "reported_cache_hit_tokens":self.provider.usage["reported_cache_hit_tokens"],
            "cache_hit_percentage":self.provider.cache_accounting.percentage(),
            "cache_percentage_complete":self.provider.cache_accounting.complete()&&self.provider.usage["cache_usage_complete"]!=false,
            "last_cell":self.execution.last_cell(),"generation_failed":self.last_generation_failed});
        if self.frontend.state() == UiState::Thinking {
            payload["model"] = json!(self.frontend.model().unwrap_or(&self.provider.model));
        }
        if let Some(retry) = self.provider.retry_snapshot() {
            payload["retry"] = json!(retry.retry);
            payload["max_retries"] = json!(retry.max_retries);
            payload["retry_delay_ms"] = json!(retry.waiting_delay_ms);
            payload["retry_operation"] = json!(retry.operation);
        }
        payload
    }
}
impl Host {
    fn scheduler_operation<T>(
        &mut self,
        action: impl FnOnce(
            &mut TaskScheduler,
            &mut CaptureSession<'_>,
            &mut dyn FnMut(&str, Value),
        ) -> Result<T>,
    ) -> Result<T> {
        // Do not call state_payload here: editor/picker paste calls this pump
        // for every byte, even when there are no jobs or emitted events.
        let status = StatusSnapshotInputs {
            frontend: &self.frontend,
            execution: &self.execution,
            provider: &self.provider,
            context: &self.context,
            skills: &self.skills,
            last_generation_failed: self.last_generation_failed,
            active_background_tasks: self.scheduler.active_count(),
        };
        let owner = self.execution.cell().zip(self.execution.operation());
        let mut io = CaptureSession {
            journal: &mut self.journal,
            history: &mut self.history,
            owner,
        };
        let mut emit = |kind: &str, payload: Value| {
            self.frontend
                .render(kind, payload, self.json, self.incoming.is_some(), || {
                    status.payload()
                })
        };
        let before = status.active_background_tasks;
        let result = action(&mut self.scheduler, &mut io, &mut emit);
        if self.scheduler.active_count() != before {
            self.event("state", self.state_payload());
        }
        result
    }
    fn bg_save_task(&mut self, metadata: &Value) -> Result<()> {
        self.scheduler_operation(|_, io, emit| TaskScheduler::save_task(io, emit, metadata))
    }
    fn bg_save_wakeup(&mut self, metadata: &Value) -> Result<()> {
        self.scheduler_operation(|_, io, emit| TaskScheduler::save_wakeup(io, emit, metadata))
    }
    fn bg_run(&mut self, v: &Value) -> Result<Value> {
        self.service_background()?;
        let TaskLaunch {
            source,
            kind,
            name,
            wakeup_reason,
            timeout,
            cwd,
            env,
        } = self.scheduler.prepare_launch(v)?;
        let mut command = kind.command(&source);
        let kind = kind.label();
        let id = format!("task{}", self.journal.seq);
        let dir = self
            .home
            .join(format!("background-{}-{}", std::process::id(), unique_id()));
        fs::create_dir(&dir)?;
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&dir, fs::Permissions::from_mode(0o700))?;
        let out = dir.join("stdout");
        let err = dir.join("stderr");
        let outfile = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&out)?;
        let errfile = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&err)?;
        let mut stdout = Capture::open(&out, "stdout", &id)?;
        let mut stderr = Capture::open(&err, "stderr", &id)?;
        // Commit empty chunks now so all running jobs have stable, distinct refs.
        stdout.commit(self, &[])?;
        stderr.commit(self, &[])?;
        let metadata = json!({"id":id,"kind":kind,"name":name,"status":BgTaskStatus::Starting.as_str(),
            "created_ms":now_ms(),"wakeup_reason":wakeup_reason,
            "stdout":{"ref":format!("H.records.stdout[{}]",stdout.index.unwrap()),"index":stdout.index,"bytes":0,"complete":false},
            "stderr":{"ref":format!("H.records.stderr[{}]",stderr.index.unwrap()),"index":stderr.index,"bytes":0,"complete":false}});
        self.bg_save_task(&metadata)?;
        self.journal.append(
            "intent",
            json!({"operation":id,"type":"background","kind":kind,"source":source,"cwd":cwd}),
        )?;
        let mut task = BgTask::prepare(metadata, stdout, stderr, dir, timeout)?;
        if let Some(cwd) = cwd {
            command.current_dir(cwd);
        }
        command
            .envs(env)
            .stdin(std::process::Stdio::null())
            .stdout(outfile)
            .stderr(errfile);
        unsafe {
            command.pre_exec(|| {
                if libc::setsid() < 0 {
                    return Err(io::Error::last_os_error());
                }
                Ok(())
            });
        }
        if let Err(error) = task.launch(&mut command) {
            task.finish_launch_failure(self, error)?;
        }
        let failed = task.status == BgTaskStatus::Settled(BgTaskOutcome::Failed);
        let metadata = task.snapshot();
        self.scheduler.insert_task(id.clone(), task);
        if failed {
            self.bg_settle(&metadata)?;
        } else {
            self.bg_save_task(&metadata)?;
        }
        Ok(metadata)
    }
    fn bg_list(&mut self, state: Option<&str>) -> Result<Value> {
        self.service_background()?;
        self.scheduler.list(state)
    }
    fn bg_get(&mut self, id: &str) -> Result<Value> {
        self.service_background()?;
        self.scheduler.get(id)
    }
    fn bg_kill(&mut self, id: &str, force: bool) -> Result<Value> {
        self.service_background()?;
        if let Some(metadata) = self.scheduler.kill(id, force)? {
            self.bg_save_task(&metadata)?;
        }
        self.scheduler.get(id)
    }
    fn bg_settle(&mut self, metadata: &Value) -> Result<()> {
        self.scheduler_operation(|scheduler, io, emit| scheduler.settle(io, emit, metadata))
    }
    fn service_background(&mut self) -> Result<()> {
        self.pump_control(WaitPolicy::Service).map(|_| ())
    }
    fn service_tasks(&mut self) -> Result<()> {
        if self.journal.failed {
            self.bg_abort();
            return Err(
                "session journal failed; owned background jobs terminated, capture may be partial"
                    .into(),
            );
        }
        let Some(_lease) = self.control_pump.enter() else {
            return Ok(());
        };
        let result = (|| {
            self.poll_busy_input()?;
            self.service_background_inner()
        })();
        if result.is_err() {
            self.bg_abort();
        }
        result
    }
    fn pump_control(&mut self, policy: WaitPolicy<'_>) -> Result<ControlProgress> {
        self.service_tasks()?;
        if matches!(policy, WaitPolicy::Service) {
            return Ok(ControlProgress {
                cancelled: false,
                revision: self.execution.cancel_revision(),
            });
        }
        let mut cancelled = false;
        if INTERRUPT.swap(false, std::sync::atomic::Ordering::SeqCst) {
            cancelled = true;
            if let WaitPolicy::Process { pid, signal } = policy {
                self.journal.append(
                    "cancel",
                    json!({"generation":self.execution.generation(),"source":"SIGINT"}),
                )?;
                self.execution.cancelled();
                unsafe {
                    libc::kill(-pid, signal);
                }
            }
        }
        // A continuously writing peer cannot prevent the waiter from checking
        // its deadline or progressing its transport. Remaining input stays FIFO.
        for _ in 0..CONTROL_COMMANDS_PER_TICK {
            let command = match self.incoming.as_ref().map(|receiver| receiver.try_recv()) {
                Some(Ok(command)) => command,
                Some(Err(std::sync::mpsc::TryRecvError::Disconnected)) => {
                    self.input_closed = true;
                    break;
                }
                _ => break,
            };
            if command.kind == NativeCommandKind::Interrupt {
                if !self.accept_input_control(&command)? {
                    continue;
                }
                if let WaitPolicy::Process { pid, signal } = policy {
                    self.journal.append(
                        "cancel",
                        json!({"command_id":command.id,"generation":self.execution.generation()}),
                    )?;
                    self.execution.cancelled();
                    unsafe {
                        libc::kill(-pid, signal);
                    }
                }
                self.event("completed", json!({"command_id":command.id,"status":"ok"}));
                cancelled = true;
            } else if !self.background_control(&command)? {
                self.queue_arrival(command)?;
            }
        }
        // Local /interrupt and /quit can raise the signal while commands are
        // being classified. Consume it before allowing a write/request forward.
        if INTERRUPT.swap(false, std::sync::atomic::Ordering::SeqCst) {
            cancelled = true;
            if let WaitPolicy::Process { pid, signal } = policy {
                self.journal.append(
                    "cancel",
                    json!({"generation":self.execution.generation(),"source":"SIGINT"}),
                )?;
                self.execution.cancelled();
                unsafe {
                    libc::kill(-pid, signal);
                }
            }
        }
        if cancelled {
            if let WaitPolicy::Provider { operation } = policy {
                self.journal.append(
                    "provider_cancelled",
                    json!({"operation":operation,"billing":"unknown"}),
                )?;
                self.execution.cancelled();
            }
        }
        Ok(ControlProgress {
            cancelled,
            revision: self.execution.cancel_revision(),
        })
    }
    fn bg_abort(&mut self) {
        // No more journal writes after a persistence failure, not even cleanup.
        self.scheduler.abort();
    }
    fn service_background_inner(&mut self) -> Result<()> {
        if !self.scheduler.has_poll_work() {
            return Ok(());
        }
        self.scheduler_operation(|scheduler, io, emit| scheduler.poll(io, emit))
    }
    fn schedule_wakeup(
        &mut self,
        seconds: f64,
        reason: &str,
        task: Option<Value>,
    ) -> Result<Value> {
        self.scheduler_operation(|scheduler, io, emit| {
            scheduler.schedule(io, emit, seconds, reason, task)
        })
    }
    fn wakeup_list(&mut self) -> Result<Value> {
        self.service_background()?;
        Ok(self.scheduler.wakeup_list())
    }
    fn wakeup_cancel(&mut self, id: &str) -> Result<Value> {
        if let Some(metadata) = self.scheduler.cancelled_wakeup(id) {
            return Ok(metadata);
        }
        let metadata = self.scheduler.change_wakeup(id, WakeupState::Cancelled)?;
        self.bg_save_wakeup(&metadata)?;
        Ok(metadata)
    }
    fn wakeup_run(&mut self, id: &str) -> Result<Value> {
        let metadata = self.scheduler.change_wakeup(id, WakeupState::Ready)?;
        self.bg_save_wakeup(&metadata)?;
        Ok(metadata)
    }
    // Called only at an idle/safe boundary, never from servicing a busy operation.
    fn dispatch_wakeups(&mut self) -> Result<bool> {
        self.service_background()?;
        if !self.pending.is_empty() {
            return Ok(false);
        }
        if let Some(command) = self.incoming.as_ref().and_then(|r| r.try_recv().ok()) {
            if !self.background_control(&command)? {
                self.queue_arrival(command)?;
            }
            return Ok(false);
        }
        let ids = self.scheduler.ready_ids();
        if ids.is_empty() {
            return Ok(false);
        }
        let mut batch = Vec::new();
        for id in &ids {
            let metadata = self.scheduler.dispatch_wakeup(id, WakeupState::Dispatching);
            self.bg_save_wakeup(&metadata)?;
            batch.push(metadata);
        }
        let notice = json!({"wakeups":batch});
        if self.no_model {
            self.event("notice", json!({"text":format!("Wakeup: {notice}")}));
        } else {
            self.add_context(
                "user",
                format!("Scheduled continuation (metadata only): {notice}"),
                false,
                vec![],
            )?;
        }
        // A crash while dispatched remains outcome_unknown on resume, never replayed.
        let result = if self.no_model {
            Ok(())
        } else {
            self.run_agent()
        };
        for id in ids {
            let metadata = self.scheduler.dispatch_wakeup(&id, WakeupState::Consumed);
            self.bg_save_wakeup(&metadata)?;
        }
        result?;
        Ok(true)
    }
    fn bg_restore(&mut self, kind: &JournalEventKind, payload: &Value) -> Result<()> {
        self.scheduler.restore(kind, payload)
    }
    fn bg_recover(&mut self) -> Result<()> {
        self.scheduler_operation(|scheduler, io, emit| scheduler.recover(io, emit))
    }
    fn bg_guard(&mut self, cancel: bool) -> Result<()> {
        self.service_background()?;
        if self.scheduler.active_count() > 0 {
            if !cancel {
                return Err(
                    "background jobs are running; kill them first or request --cancel-tasks".into(),
                );
            }
            self.bg_shutdown()?;
        }
        Ok(())
    }
    fn bg_shutdown(&mut self) -> Result<()> {
        let ids = self.scheduler.active_ids();
        for id in &ids {
            self.bg_kill(id, false)?;
        }
        let deadline = std::time::Instant::now() + std::time::Duration::from_millis(750);
        while self.scheduler.active_count() > 0 && std::time::Instant::now() < deadline {
            self.service_background()?;
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        for id in &ids {
            if self.scheduler.is_active(id) {
                self.bg_kill(id, true)?;
            }
        }
        let deadline = std::time::Instant::now() + std::time::Duration::from_millis(250);
        while self.scheduler.active_count() > 0 && std::time::Instant::now() < deadline {
            self.service_background()?;
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        // A large backlog or escaped writer must not make shutdown unbounded.
        // Preserve captured bytes explicitly as partial rather than claiming EOF.
        for id in ids {
            self.scheduler_operation(|scheduler, io, emit| {
                scheduler.finish_partial(io, emit, &id)
            })?;
        }
        Ok(())
    }
}

// =============================================================================
// Model catalog normalization and refresh
// =============================================================================

// Pure, bounded catalog normalization. Remote instructions and tool metadata
// are intentionally never copied into normalized descriptors.
fn catalog_safe_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 128
        && id
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'.' | b'_' | b'-'))
}
// OpenAI fine-tuned model IDs contain colons; Codex native slugs do not.
fn catalog_api_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 128
        && id
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'.' | b'_' | b'-' | b':'))
}
fn catalog_safe_label(text: &str, max: usize) -> bool {
    !text.trim().is_empty()
        && text.chars().count() <= max
        && !text
            .chars()
            .any(|c| c.is_control() || matches!(c, '\u{2028}' | '\u{2029}'))
}
fn catalog_optional_limit(item: &Value, key: &str) -> Result<Option<u64>> {
    match item.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(value) => {
            let n = value
                .as_u64()
                .filter(|n| (1..=16777216).contains(n))
                .ok_or_else(|| {
                    format!("Invalid model catalog {key}: expected an integer in 1..=16777216")
                })?;
            Ok(Some(n))
        }
    }
}
fn catalog_effort(effort: &str) -> Option<&str> {
    match effort {
        "none" => Some("off"),
        "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" => Some(effort),
        _ => None,
    }
}
fn catalog_aliases(slug: &str, base: Option<&Value>) -> Vec<String> {
    let mut aliases = base
        .and_then(|m| m["aliases"].as_array())
        .map(|values| {
            values
                .iter()
                .filter_map(Value::as_str)
                .filter(|s| catalog_safe_id(s))
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    if let Some((version, kind)) = slug.strip_prefix("gpt-").and_then(|s| s.rsplit_once('-')) {
        if ["sol", "astra", "luna", "terra"].contains(&kind)
            && !version.is_empty()
            && !version.starts_with('.')
            && !version.ends_with('.')
            && version.bytes().all(|c| c.is_ascii_digit() || c == b'.')
        {
            let alias = format!("{kind}{}", version.replace('.', ""));
            if catalog_safe_id(&alias) && !aliases.contains(&alias) {
                aliases.push(alias);
            }
        }
    }
    aliases
}
fn normalize_codex_catalog(body: &Value, base: &[Value]) -> Result<Vec<Value>> {
    let entries = body["models"]
        .as_array()
        .ok_or("Codex model catalog requires a models array")?;
    if entries.len() > 2048 {
        return Err("Codex model catalog exceeds 2048 entries".into());
    }
    let mut seen = std::collections::HashSet::new();
    let mut normalized = Vec::new();
    for item in entries {
        let slug = item["slug"]
            .as_str()
            .filter(|id| catalog_safe_id(id))
            .ok_or("Invalid Codex catalog model slug")?;
        if !seen.insert(slug) {
            return Err(format!("Duplicate Codex catalog model slug: {slug}").into());
        }
        let name = item["display_name"]
            .as_str()
            .filter(|s| catalog_safe_label(s, 256))
            .ok_or("Invalid Codex catalog model display_name")?;
        let visibility = item["visibility"]
            .as_str()
            .filter(|s| matches!(*s, "list" | "hide" | "none"))
            .ok_or("Invalid Codex catalog model visibility")?;
        let context = catalog_optional_limit(item, "context_window")?;
        let maximum = catalog_optional_limit(item, "max_context_window")?;
        let context = context.or(maximum);
        let percent = match item.get("effective_context_window_percent") {
            None => 95,
            Some(value) => value
                .as_u64()
                .filter(|n| (1..=100).contains(n))
                .ok_or("Invalid Codex effective_context_window_percent")?,
        };
        let input = context.map(|n| n * percent / 100);
        if input == Some(0) {
            return Err("Codex effective input limit must be positive".into());
        }
        let priority = match item.get("priority") {
            None => i32::MAX as i64,
            Some(value) => value
                .as_i64()
                .filter(|n| (i32::MIN as i64..=i32::MAX as i64).contains(n))
                .ok_or("Invalid Codex catalog priority")?,
        };
        let mut levels = Vec::new();
        match item.get("supported_reasoning_levels") {
            None => {}
            Some(value) => {
                for level in value
                    .as_array()
                    .filter(|a| a.len() <= 32)
                    .ok_or("Invalid Codex supported_reasoning_levels")?
                {
                    let effort = level["effort"]
                        .as_str()
                        .filter(|s| catalog_safe_id(s) && s.len() <= 32)
                        .ok_or("Invalid Codex reasoning effort preset")?;
                    if let Some(effort) = catalog_effort(effort) {
                        if !levels.contains(&effort) {
                            levels.push(effort);
                        }
                    }
                }
            }
        }
        let preferred = match item.get("default_reasoning_level") {
            None | Some(Value::Null) => None,
            Some(value) => Some(
                value
                    .as_str()
                    .filter(|s| catalog_safe_id(s) && s.len() <= 32)
                    .ok_or("Invalid Codex default_reasoning_level")?,
            ),
        };
        let default = preferred
            .and_then(catalog_effort)
            .filter(|s| levels.contains(s))
            .or_else(|| {
                if levels.contains(&"medium") {
                    Some("medium")
                } else {
                    levels.first().copied()
                }
            });
        let image_input = match item.get("input_modalities") {
            None => true, // The native schema's documented default.
            Some(value) => {
                let modalities = value
                    .as_array()
                    .filter(|a| a.len() <= 32)
                    .ok_or("Invalid Codex input_modalities")?;
                for modality in modalities {
                    if !modality
                        .as_str()
                        .is_some_and(|s| catalog_safe_id(s) && s.len() <= 32)
                    {
                        return Err("Invalid Codex input modality".into());
                    }
                }
                modalities.iter().any(|v| v == "image")
            }
        };
        // Validate hidden descriptors too: never accept a partial malformed catalog.
        if visibility != "list" {
            continue;
        }
        let id = format!("openai-codex/{slug}");
        let known = base.iter().find(|m| m["id"] == id);
        normalized.push(json!({"id":id,"name":name,"provider":"openai-codex",
            "api":"openai-codex-responses","aliases":catalog_aliases(slug,known),
            "context_limit":context,"max_input_tokens":input,"reasoning":!levels.is_empty(),
            "reasoning_efforts":levels,"default_effort":default,"image_input":image_input,
            "image_output":false,"deprecated":false,"priority":priority,
            "metadata_complete":context.is_some()&&!levels.is_empty(),
            "catalog_listed":true,"source":"provider-discovery"}));
    }
    normalized.sort_by(|a, b| {
        a["priority"]
            .as_i64()
            .cmp(&b["priority"].as_i64())
            .then_with(|| a["id"].as_str().cmp(&b["id"].as_str()))
    });
    Ok(normalized)
}
fn normalize_openai_catalog(body: &Value, base: &[Value], provider: &str) -> Result<Vec<Value>> {
    if !catalog_safe_id(provider) {
        return Err("Invalid model catalog provider ID".into());
    }
    let entries = body["data"]
        .as_array()
        .ok_or("API model catalog requires a data array")?;
    if entries.len() > 2048 {
        return Err("API model catalog exceeds 2048 entries".into());
    }
    let mut seen = std::collections::HashSet::new();
    let mut normalized = Vec::new();
    for entry in entries {
        let slug = entry["id"]
            .as_str()
            .filter(|id| catalog_api_id(id))
            .ok_or("Invalid API catalog model ID")?;
        if !seen.insert(slug) {
            return Err(format!("Duplicate API catalog model ID: {slug}").into());
        }
        let id = format!("{provider}/{slug}");
        let known = base.iter().find(|m| m["id"] == id);
        let mut model = json!({"id":id,"name":slug,"provider":provider,"context_limit":null,
            "metadata_complete":false,"catalog_listed":true,"source":"provider-discovery"});
        if let Some(known) = known {
            // /models proves availability only, not protocol or capabilities.
            for key in [
                "name",
                "api",
                "context_limit",
                "max_input_tokens",
                "max_tokens",
                "image_input",
                "image_output",
                "reasoning",
                "reasoning_efforts",
                "default_effort",
                "aliases",
                "deprecated",
            ] {
                if let Some(value) = known.get(key) {
                    model[key] = value.clone();
                }
            }
            model["metadata_complete"] = json!(
                known["metadata_complete"] != false
                    && known["context_limit"]
                        .as_u64()
                        .is_some_and(|n| (1..=16777216).contains(&n))
                    && known["api"].as_str().is_some_and(|s| !s.is_empty())
            );
        }
        normalized.push(model);
    }
    normalized.sort_by(|a, b| a["id"].as_str().cmp(&b["id"].as_str()));
    Ok(normalized)
}

const MODEL_CATALOG_MAX_BYTES: u64 = 8 * 1024 * 1024;
// Native catalog compatibility revision, not this harness's package version.
// Current upstream metadata requires 0.153/0.155 for the GPT-6 family.
fn model_catalog_defaults() -> Value {
    json!({"auto_refresh":true,"refresh_interval_seconds":3600,"retry_interval_seconds":300,"codex_client_version":"0.155.0"})
}
fn model_catalog_options(config: &Value) -> Result<Value> {
    let mut options = model_catalog_defaults();
    if let Some(value) = config.get("model_catalog") {
        for (key, value) in value.as_object().ok_or("model_catalog must be an object")? {
            if options.get(key).is_none() {
                return Err(format!("unknown model_catalog option {key}").into());
            }
            if key == "auto_refresh" {
                if !value.is_boolean() {
                    return Err("model_catalog.auto_refresh must be boolean".into());
                }
            } else if key == "codex_client_version" {
                if !value.as_str().is_some_and(|s| {
                    s.len() <= 32
                        && s.split('.').count() == 3
                        && s.split('.').all(|p| {
                            !p.is_empty()
                                && p.bytes().all(|b| b.is_ascii_digit())
                                && p.parse::<u32>().is_ok()
                        })
                }) {
                    return Err("model_catalog.codex_client_version must be a numeric major.minor.patch string".into());
                }
            } else if !value.as_u64().is_some_and(|n| (1..=604800).contains(&n)) {
                return Err(format!("model_catalog.{key} must be an integer in 1..=604800").into());
            }
            options[key] = value.clone();
        }
    }
    Ok(options)
}
fn catalog_contains_secret(value: &Value, secrets: &[String]) -> bool {
    match value {
        Value::String(text) => secrets.iter().any(|s| !s.is_empty() && text.contains(s)),
        Value::Array(values) => values.iter().any(|v| catalog_contains_secret(v, secrets)),
        Value::Object(values) => values.values().any(|v| catalog_contains_secret(v, secrets)),
        _ => false,
    }
}
fn empty_model_catalog() -> Value {
    json!({"version":1,"providers":{}})
}
fn load_model_catalog(path: &Path) -> Result<Value> {
    let file = match OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK)
        .open(path)
    {
        Ok(file) => file,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(empty_model_catalog()),
        Err(error) => return Err(error.into()),
    };
    if !file.metadata()?.is_file() || file.metadata()?.len() > MODEL_CATALOG_MAX_BYTES {
        return Err("model catalog cache must be a regular file of at most 8 MiB".into());
    }
    let mut cache: Value = serde_json::from_reader(file)?;
    if cache["version"] != 1 || !cache["providers"].is_object() {
        return Err("invalid model catalog cache".into());
    }
    for (provider, record) in cache["providers"].as_object_mut().unwrap() {
        if !["openai", "openai-codex"].contains(&provider.as_str())
            || !record["identity"]
                .as_str()
                .is_some_and(|s| s.len() == 64 && s.bytes().all(|c| c.is_ascii_hexdigit()))
        {
            return Err("invalid model catalog cache identity".into());
        }
        for key in ["fetched_at_ms", "attempted_at_ms"] {
            if record.get(key).is_some_and(|v| !v.is_u64()) {
                return Err("invalid model catalog timestamp".into());
            }
        }
        if let Some(models) = record.get_mut("models") {
            let models = models
                .as_array_mut()
                .filter(|m| m.len() <= 2048)
                .ok_or("invalid model catalog cache entries")?;
            let mut seen = HashSet::new();
            for model in models {
                let id = model["id"].as_str().ok_or("invalid cached model ID")?;
                let (p, slug) = id.split_once('/').ok_or("invalid cached model ID")?;
                let valid_slug = if provider == "openai-codex" {
                    catalog_safe_id(slug)
                } else {
                    catalog_api_id(slug)
                };
                if p != provider.as_str() || !valid_slug || !seen.insert(id.to_string()) {
                    return Err("invalid cached model identity".into());
                }
                if !model["name"]
                    .as_str()
                    .is_some_and(|s| catalog_safe_label(s, 256))
                    || !model["metadata_complete"].is_boolean()
                {
                    return Err("invalid cached model metadata".into());
                }
                for key in ["context_limit", "max_input_tokens", "max_tokens"] {
                    catalog_optional_limit(model, key)?;
                }
                if let Some(levels) = model.get("reasoning_efforts") {
                    if !levels.as_array().is_some_and(|a| {
                        a.len() <= 7
                            && a.iter()
                                .all(|v| v.as_str().is_some_and(|s| catalog_effort(s) == Some(s)))
                    }) {
                        return Err("invalid cached model effort metadata".into());
                    }
                }
                for key in ["reasoning", "image_input", "image_output", "deprecated"] {
                    if model.get(key).is_some_and(|v| !v.is_boolean()) {
                        return Err("invalid cached model capability".into());
                    }
                }
                if model["metadata_complete"] == true
                    && (!model["context_limit"].is_u64()
                        || !model["api"].as_str().is_some_and(|s| {
                            [
                                "openai-codex-responses",
                                "openai-responses",
                                "openai-completions",
                                "image-generation",
                            ]
                            .contains(&s)
                        })
                        || (provider == "openai-codex"
                            && (!model["reasoning_efforts"]
                                .as_array()
                                .is_some_and(|a| !a.is_empty())
                                || model["api"] != "openai-codex-responses")))
                {
                    return Err("inconsistent cached model capabilities".into());
                }
                if let Some(aliases) = model.get("aliases") {
                    if !aliases.as_array().is_some_and(|a| {
                        a.len() <= 32 && a.iter().all(|v| v.as_str().is_some_and(catalog_safe_id))
                    }) {
                        return Err("invalid cached model aliases".into());
                    }
                }
                let mut safe = json!({});
                for key in [
                    "id",
                    "name",
                    "api",
                    "context_limit",
                    "max_input_tokens",
                    "max_tokens",
                    "reasoning",
                    "reasoning_efforts",
                    "default_effort",
                    "image_input",
                    "image_output",
                    "deprecated",
                    "priority",
                    "aliases",
                    "metadata_complete",
                ] {
                    if let Some(value) = model.get(key) {
                        safe[key] = value.clone();
                    }
                }
                safe["provider"] = json!(provider);
                safe["source"] = json!("provider-discovery");
                safe["catalog_listed"] = json!(true);
                *model = safe;
            }
        }
    }
    Ok(cache)
}
impl Host {}
impl ProviderClient {
    fn catalog_endpoint(&self, provider: &str) -> Result<(String, String)> {
        let provider = provider_alias(provider);
        if !["openai", "openai-codex"].contains(&provider) {
            return Err("catalog refresh currently supports codex and openai; other providers retain offline/configured inventory".into());
        }
        let (base, key, _) = self.provider_config(&format!("{provider}/catalog-discovery"))?;
        let endpoint = if provider == "openai-codex" {
            let base = base
                .strip_suffix("/codex/responses")
                .map(|s| format!("{s}/codex"))
                .unwrap_or(base);
            if base.ends_with("/codex") {
                format!("{base}/models")
            } else {
                format!("{base}/codex/models")
            }
        } else {
            format!("{}/models", base.trim_end_matches('/'))
        };
        Ok((endpoint, key))
    }
    fn catalog_identity(&self, provider: &str) -> Option<String> {
        let provider = provider_alias(provider);
        let (endpoint, key) = self.catalog_endpoint(provider).ok()?;
        // Credential/account/endpoint-bound; no plaintext identity or token is cached.
        let principal = if provider == "openai-codex" {
            key.split('.').nth(1).and_then(|part|base64::engine::general_purpose::URL_SAFE_NO_PAD.decode(part.trim_end_matches('=')).ok())
                .and_then(|bytes|serde_json::from_slice::<Value>(&bytes).ok())
                .filter(|claims|claims["https://api.openai.com/auth"]["chatgpt_account_id"]==self.auth[provider]["accountId"])
                .map(|claims|json!({"auth":claims["https://api.openai.com/auth"],"profile":claims["https://api.openai.com/profile"],"subject":claims["sub"],"email":claims["email"]}).to_string()).unwrap_or(key)
        } else {
            key
        };
        let revision = if provider == "openai-codex" {
            model_catalog_options(&self.config_defaults).ok()?["codex_client_version"]
                .as_str()?
                .to_string()
        } else {
            String::new()
        };
        let scope = format!(
            "{provider}\0{endpoint}\0{principal}\0{revision}\0{}",
            self.auth[provider]["accountId"].as_str().unwrap_or("")
        );
        Some(
            ring::digest::digest(&ring::digest::SHA256, scope.as_bytes())
                .as_ref()
                .iter()
                .map(|b| format!("{b:02x}"))
                .collect(),
        )
    }
}
impl Host {
    fn catalog_endpoint(&self, provider: &str) -> Result<(String, String)> {
        self.provider.catalog_endpoint(provider)
    }
    fn catalog_identity(&self, provider: &str) -> Option<String> {
        self.provider.catalog_identity(provider)
    }
    fn catalog_auto_enabled(&self) -> bool {
        match std::env::var("PY_MODEL_CATALOG_AUTO_REFRESH")
            .ok()
            .as_deref()
        {
            Some("0" | "false") => false,
            Some("1" | "true") => true,
            _ => model_catalog_options(&self.provider.config_defaults)
                .map_or(false, |v| v["auto_refresh"] == true),
        }
    }
    fn maybe_refresh_model_catalog(&mut self, provider: &str) {
        if !self.catalog_auto_enabled()
            || !self.provider_usable(provider)
            || self.catalog_identity(provider).is_none()
        {
            return;
        }
        if let Err(error) = self.refresh_model_catalog(provider, false) {
            self.event("notice",json!({"text":format!("Model catalog refresh failed: {error}. Keeping cached/offline inventory; /model list refresh retries explicitly.")}));
        }
    }
    fn refresh_model_catalog(&mut self, provider: &str, force: bool) -> Result<bool> {
        let provider = provider_alias(provider).to_string();
        self.reload_auth()?;
        self.catalog_endpoint(&provider)?;
        let before = self
            .catalog_identity(&provider)
            .ok_or("catalog refresh requires credentials; /login the provider first")?;
        let record = &self.provider.catalog["providers"][&provider];
        let now = now_ms() as u64;
        let options = model_catalog_options(&self.provider.config_defaults)?;
        if !force && record["identity"] == before {
            let recent = |key: &str, seconds: u64| {
                record[key]
                    .as_u64()
                    .is_some_and(|t| t <= now && now - t < seconds * 1000)
            };
            if recent(
                "fetched_at_ms",
                options["refresh_interval_seconds"].as_u64().unwrap(),
            ) || recent(
                "attempted_at_ms",
                options["retry_interval_seconds"].as_u64().unwrap(),
            ) {
                return Ok(false);
            }
        }
        self.event(
            "notice",
            json!({"text":format!("Refreshing {provider} model catalog…")}),
        );
        let cancel_revision = self.execution.cancel_revision();
        let result = self.with_state(UiState::Running, None, |host| {
            if provider == "openai-codex" {
                host.refresh_codex()?;
            }
            let (endpoint, key) = host.catalog_endpoint(&provider)?;
            let client = reqwest::Client::builder()
                .timeout(std::time::Duration::from_secs(15))
                .redirect(reqwest::redirect::Policy::none())
                .build()?;
            let mut request = client
                .get(endpoint)
                .bearer_auth(&key)
                .header("Accept", "application/json")
                .header("originator", "py")
                .header("User-Agent", "py-rust/0.1.0");
            if provider == "openai-codex" {
                request = request
                    .query(&[(
                        "client_version",
                        options["codex_client_version"].as_str().unwrap(),
                    )])
                    .header(
                        "chatgpt-account-id",
                        host.provider.auth["openai-codex"]["accountId"]
                            .as_str()
                            .ok_or("Codex account ID missing")?,
                    );
            }
            let mut secrets = Vec::new();
            credential_secret_values(&host.provider.auth, &mut secrets);
            secrets.push(key);
            let body = host.codex_wait(
                async {
                    let mut response = request
                        .send()
                        .await
                        .map_err(|_| "model catalog network error")?;
                    let status = response.status();
                    let mut bytes = Vec::new();
                    while let Some(chunk) = response
                        .chunk()
                        .await
                        .map_err(|_| "model catalog response disconnected")?
                    {
                        if bytes.len() as u64 + chunk.len() as u64 > MODEL_CATALOG_MAX_BYTES {
                            return Err("model catalog response exceeds 8 MiB".into());
                        }
                        bytes.extend_from_slice(&chunk);
                    }
                    if !status.is_success() {
                        return Err(format!(
                            "model catalog HTTP {status}{}",
                            codex_error_detail(&bytes, &secrets)
                        )
                        .into());
                    }
                    Ok(serde_json::from_slice::<Value>(&bytes)
                        .map_err(|_| "model catalog returned invalid JSON")?)
                },
                "model_catalog",
            )?;
            let base = host.models();
            if provider == "openai-codex" {
                normalize_codex_catalog(&body, base.as_array().unwrap())
            } else {
                normalize_openai_catalog(&body, base.as_array().unwrap(), &provider)
            }
        });
        // Metadata/validation failures may echo a credential in an ID or label too.
        let mut secrets = Vec::new();
        credential_secret_values(&self.provider.auth, &mut secrets);
        if let Ok((_, key)) = self.catalog_endpoint(&provider) {
            secrets.push(key);
        }
        let mut result: Result<Vec<Value>> = result.map_err(|error| {
            format!(
                "model catalog refresh{}",
                codex_error_detail(error.to_string().as_bytes(), &secrets)
            )
            .into()
        });
        if result
            .as_ref()
            .is_ok_and(|models| catalog_contains_secret(&json!(models), &secrets))
        {
            result =
                Err("model catalog contained reflected credential data; update rejected".into());
        }
        // Tokens can rotate during refresh; bind the response to the actual principal.
        let identity = self.catalog_identity(&provider).unwrap_or(before);
        let mut record = if self.provider.catalog["providers"][&provider]["identity"] == identity {
            self.provider.catalog["providers"][&provider].clone()
        } else {
            json!({"identity":identity})
        };
        record["attempted_at_ms"] = json!(now_ms() as u64);
        if self.execution.cancel_revision() != cancel_revision {
            return Err("model catalog refresh cancelled; previous cache retained".into());
        }
        if let Ok(models) = &result {
            record["models"] = json!(models);
            record["fetched_at_ms"] = json!(now_ms() as u64);
        }
        self.commit_model_catalog(&provider, record)?;
        self.provider.set_session_model(
            self.provider.model.clone(),
            self.model_limit(&self.provider.model)?,
        );
        match result {
            Ok(models) => {
                self.journal.append("model_catalog_refresh",json!({"provider":provider,"count":models.len(),"fetched_at_ms":now_ms() as u64}))?;
                self.event("notice",json!({"text":format!("Updated {provider} model catalog: {} entries. Active model and session prompt unchanged.",models.len())}));
                Ok(true)
            }
            Err(error) => Err(error),
        }
    }
    fn commit_model_catalog(&mut self, provider: &str, mut record: Value) -> Result<()> {
        let lock = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .truncate(false)
            .mode(0o600)
            .custom_flags(libc::O_NOFOLLOW)
            .open(self.home.join("models.lock"))?;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            if unsafe { libc::flock(lock.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) } == 0 {
                break;
            }
            let error = io::Error::last_os_error();
            if error.raw_os_error() != Some(libc::EWOULDBLOCK) {
                return Err(error.into());
            }
            if std::time::Instant::now() >= deadline || self.codex_cancel("model_catalog")? {
                return Err("model catalog cache busy/cancelled; previous cache retained".into());
            }
            std::thread::sleep(std::time::Duration::from_millis(15));
        }
        let path = self.home.join("models.json");
        let mut cache = load_model_catalog(&path).unwrap_or_else(|_| empty_model_catalog());
        let latest = &cache["providers"][provider];
        // A failed/older concurrent request must not replace a newer good snapshot.
        if latest["identity"] == record["identity"]
            && latest["models"].is_array()
            && latest["fetched_at_ms"].as_u64().unwrap_or(0)
                > record["fetched_at_ms"].as_u64().unwrap_or(0)
        {
            record["models"] = latest["models"].clone();
            record["fetched_at_ms"] = latest["fetched_at_ms"].clone();
        }
        record["attempted_at_ms"] = json!(record["attempted_at_ms"]
            .as_u64()
            .unwrap_or(0)
            .max(latest["attempted_at_ms"].as_u64().unwrap_or(0)));
        cache["providers"][provider] = record;
        if serde_json::to_vec(&cache)?.len() as u64 > MODEL_CATALOG_MAX_BYTES {
            return Err("normalized model cache exceeds 8 MiB".into());
        }
        write_private_json(&path, &cache)?;
        self.provider.accept_catalog(cache);
        Ok(())
    }
    fn model_list_command(&mut self, args: &str) -> Result<()> {
        self.reload_auth()?;
        let (verb, rest) = args
            .split_once(char::is_whitespace)
            .map(|(a, b)| (a, b.trim()))
            .unwrap_or((args, ""));
        let provider = self
            .provider
            .model
            .split_once('/')
            .map(|p| provider_alias(p.0))
            .unwrap_or("openai")
            .to_string();
        if verb == "refresh" {
            let target = if rest.is_empty() {
                provider
            } else {
                self.resolve_provider(rest)?
            };
            if !self.provider_usable(&target) {
                return Err(format!(
                    "Provider {target} is not usable; /login {target} before catalog refresh"
                )
                .into());
            }
            let result = self.refresh_model_catalog(&target, true);
            self.list_models(&format!("{target}/"));
            result.map(|_| ())
        } else {
            self.maybe_refresh_model_catalog(&provider);
            self.list_models(args);
            Ok(())
        }
    }
}

// =============================================================================
// Durable skills and configuration
// =============================================================================

// Durable entries remain ordinary files; only initialization interprets them.
fn skills_defaults() -> Value {
    json!({"enabled":true,"max_system_tokens":8000,"max_core_entry_tokens":2000,
    "max_inventory_entry_tokens":128,"max_entries":128,"max_file_bytes":65536})
}
fn skills_options(config: &Value) -> Result<Value> {
    if !config.is_object() {
        return Err("config.json must contain an object".into());
    }
    let mut result = skills_defaults();
    if let Some(options) = config.get("skills") {
        for (key, value) in options
            .as_object()
            .ok_or("skills config must be an object")?
        {
            if result.get(key).is_none() {
                return Err(format!("unknown skills setting: {key}").into());
            }
            if key == "enabled" {
                if !value.is_boolean() {
                    return Err("skills.enabled must be boolean".into());
                }
            } else if !value.as_u64().is_some_and(|n| n > 0 && n <= 16_777_216) {
                return Err(format!("skills.{key} must be an integer in 1..=16777216").into());
            }
            result[key] = value.clone();
        }
    }
    Ok(result)
}
fn config_secret_key(key: &str) -> bool {
    matches!(
        key.to_ascii_lowercase().replace('-', "_").as_str(),
        "auth"
            | "credentials"
            | "key"
            | "api_key"
            | "apikey"
            | "access"
            | "refresh"
            | "token"
            | "password"
            | "access_token"
            | "refresh_token"
            | "secret"
            | "client_secret"
            | "authorization"
    )
}
fn config_has_secrets(value: &Value) -> bool {
    match value {
        Value::Object(object) => object
            .iter()
            .any(|(key, value)| config_secret_key(key) || config_has_secrets(value)),
        Value::Array(values) => values.iter().any(config_has_secrets),
        _ => false,
    }
}
fn validate_config(config: &Value) -> Result<()> {
    if config_has_secrets(config) {
        return Err("credentials belong in auth.json and /login, not config.json".into());
    }
    skills_options(config)?;
    model_catalog_options(config)?;
    for key in ["model", "effort"] {
        if let Some(value) = config.get(key) {
            if !value.as_str().is_some_and(|s| !s.trim().is_empty()) {
                return Err(format!("{key} must be a nonempty string").into());
            }
        }
    }
    if let Some(effort) = config["effort"].as_str() {
        if !["off", "minimal", "low", "medium", "high", "xhigh", "max"].contains(&effort) {
            return Err("invalid configured effort".into());
        }
    }
    if let Some(providers) = config.get("providers") {
        if !providers.is_object() {
            return Err("providers must be an object".into());
        }
    }
    Ok(())
}
fn effective_config(config: &Value) -> Result<Value> {
    let mut value = config.clone();
    value["skills"] = skills_options(config)?;
    value["model_catalog"] = model_catalog_options(config)?;
    Ok(value)
}
fn skills_tokens(text: &str) -> usize {
    text.chars().count().div_ceil(3)
}
fn valid_skill_date(date: &str) -> bool {
    if date.len() != 20 || !date.is_ascii() {
        return false;
    }
    let b = date.as_bytes();
    if b[4] != b'-'
        || b[7] != b'-'
        || b[10] != b'T'
        || b[13] != b':'
        || b[16] != b':'
        || b[19] != b'Z'
    {
        return false;
    }
    if b.iter()
        .enumerate()
        .any(|(i, c)| ![4, 7, 10, 13, 16, 19].contains(&i) && !c.is_ascii_digit())
    {
        return false;
    }
    let number = |a, b| date[a..b].parse::<u32>().ok();
    let (Some(y), Some(m), Some(d), Some(h), Some(min), Some(s)) = (
        number(0, 4),
        number(5, 7),
        number(8, 10),
        number(11, 13),
        number(14, 16),
        number(17, 19),
    ) else {
        return false;
    };
    let days = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) {
                29
            } else {
                28
            }
        }
        _ => 0,
    };
    y > 0 && d > 0 && d <= days && h < 24 && min < 60 && s < 60
}
fn parse_skill(name: &str, text: &str) -> Result<Value> {
    let mut lines = text.split_inclusive('\n');
    if lines.next().map(str::trim_end) != Some("---") {
        return Err("missing --- front matter".into());
    }
    let mut metadata = json!({});
    let mut closed = false;
    for line in lines.by_ref() {
        let line = line.trim_end();
        if line == "---" {
            closed = true;
            break;
        }
        if line.trim().is_empty() {
            continue;
        }
        let (key, raw) = line
            .split_once(':')
            .ok_or("expected key: value front matter")?;
        if ![
            "kind",
            "created",
            "updated",
            "origin",
            "description",
            "core",
        ]
        .contains(&key)
        {
            return Err(format!("unknown metadata field {key}").into());
        }
        if metadata.get(key).is_some() {
            return Err(format!("duplicate metadata field {key}").into());
        }
        let raw = raw.trim();
        metadata[key] = if key == "core" {
            match raw {
                "true" => json!(true),
                "false" => json!(false),
                _ => return Err("core must be true or false".into()),
            }
        } else if raw.starts_with('"') {
            let s: String = serde_json::from_str(raw)?;
            json!(s)
        } else {
            if raw.is_empty() || raw.starts_with(['\'', '|', '>', '[', '{', '&', '*', '!', '#']) {
                return Err("use a plain single-line or JSON-quoted string".into());
            }
            json!(raw)
        };
    }
    if !closed {
        return Err("unterminated front matter".into());
    }
    for key in [
        "kind",
        "created",
        "updated",
        "origin",
        "description",
        "core",
    ] {
        if metadata.get(key).is_none() {
            return Err(format!("missing metadata field {key}").into());
        }
    }
    if !["memory", "skill", "python"].contains(&metadata["kind"].as_str().unwrap_or("")) {
        return Err("kind must be memory, skill or python".into());
    }
    if !["agent", "user"].contains(&metadata["origin"].as_str().unwrap_or("")) {
        return Err("origin must be agent or user".into());
    }
    for key in ["created", "updated"] {
        if !valid_skill_date(metadata[key].as_str().unwrap_or("")) {
            return Err(format!("{key} must be a valid YYYY-MM-DDTHH:MM:SSZ timestamp").into());
        }
    }
    if metadata["updated"].as_str() < metadata["created"].as_str() {
        return Err("updated precedes created".into());
    }
    let description = metadata["description"].as_str().unwrap();
    if description.trim().is_empty()
        || description
            .chars()
            .any(|c| c.is_control() || c == '\u{2028}' || c == '\u{2029}')
    {
        return Err("description must be nonempty, single-line and control-free".into());
    }
    let body = lines.collect::<String>();
    let mut python = String::new();
    if metadata["kind"] == "python" {
        let mut fence: Option<String> = None;
        let mut executable = false;
        let mut count = 0;
        for line in body.split_inclusive('\n') {
            let trim = line.trim_end();
            if let Some(marker) = &fence {
                if trim == marker {
                    fence = None;
                    executable = false;
                } else if executable {
                    python.push_str(line);
                }
            } else if trim.starts_with("```") || trim.starts_with("~~~") {
                let ch = trim.chars().next().unwrap();
                let n = trim.chars().take_while(|c| *c == ch).count();
                let info = &trim[n..];
                executable = info.trim() == "python";
                if executable {
                    if trim != "```python" {
                        return Err("Python fences must use exact ```python / ``` lines".into());
                    }
                    count += 1;
                }
                fence = Some(ch.to_string().repeat(n));
            }
        }
        if fence.is_some() || count != 1 || python.trim().is_empty() {
            return Err(
                "python entries require exactly one nonempty, closed fenced python block".into(),
            );
        }
    }
    metadata["filename"] = json!(name);
    metadata["body"] = json!(body);
    metadata["python"] = json!(python);
    metadata["sha256"] = json!(ring::digest::digest(&ring::digest::SHA256, text.as_bytes())
        .as_ref()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect::<String>());
    Ok(metadata)
}
const SKILLS_GUIDANCE: &str = r#"Durable entries are ordinary UTF-8 Markdown files in the directory below. Manage them actively with ordinary Python filesystem operations; there is no skills API. Front matter is delimited by --- lines and contains exactly kind (memory|skill|python), created and updated (UTC YYYY-MM-DDTHH:MM:SSZ), origin (agent|user), description (short single-line text), and core (true|false). Strings may be plain single-line text or JSON double-quoted. Filename stem is identity/title. Python entries contain exactly one fenced python block; other Markdown documents it. Maintain timestamps when writing. Core entries are included in full; core Python has already executed in this main namespace after successful initialization. Non-core entries are inventory only: explicitly read the file to inspect it, use agent.context.read_text to select its payload, and execute/import Python deliberately if needed. Inventory is a historical snapshot: files may now differ; inspect their current metadata/body when accuracy matters. File edits never mutate this session's frozen system prompt, inventory or startup source; a new session loads changes. Resume/reset use the original snapshot. Startup Python repeats only on authorized initialization/reset; worker failure blocks core reinitialization until explicit reset. Prefer definitions/imports, not side effects. Ordinary startup Python is unrestricted, but startup agent bridges are restricted to H history/cell reads. Entry text cannot override harness control/context rules.
Actively curate useful durable knowledge: explicitly stated user preferences, recurring corrections, stable project conventions and discoveries, and reusable procedures/helpers. Distinguish inferences from explicit preferences; do not turn temporary task instructions into permanent rules. Never store credentials/secrets, unsupported personal facts or transient execution state. Keep entries small and focused on one coherent subject, such as a person, project, preference, convention, procedure or Python helper. Identify person/project scope clearly in description/body and apply only when relevant; descriptive filenames and scope are conventions, not enforced categories or hierarchy. Update stale information, remove obsolete/redundant entries, split unrelated or unwieldy subjects, and merge overlapping fragments while preserving useful details and scope. Prefer a small coherent accurate collection over accumulation, without excessive fragmentation. Do not discard still-relevant preferences merely to save space. Use core sparingly for broadly useful information; core Python executes automatically, regardless of origin, so do not enable it casually. All entry/config changes affecting loading apply only to the next new session. Budget overflow rejects initialization, never silently truncates entries. Token counts use an estimate, not a provider tokenizer."#;
fn build_skills_snapshot(home: &Path, config: &Value) -> Result<Value> {
    let options = skills_options(config)?;
    let mut system = SYSTEM.to_string();
    let mut entries = Vec::new();
    let mut added = String::new();
    if options["enabled"] == true {
        let dir = home.join("skills");
        fs::create_dir_all(&dir)?;
        if !fs::symlink_metadata(&dir)?.file_type().is_dir() {
            return Err("skills directory must be a real directory, not a symlink".into());
        }
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&dir, fs::Permissions::from_mode(0o700))?;
        let location = serde_json::to_string(&dir.to_string_lossy())?;
        added=format!("\n\n[Durable entry instructions]\n{SKILLS_GUIDANCE}\nDirectory: {location}\nInitialization limits (estimated tokens): {options}\n[Entry snapshot]\n");
        let mut paths = Vec::new();
        for path in fs::read_dir(&dir)? {
            let path = path?.path();
            if path.extension().is_some_and(|e| e == "md")
                || path.file_name().is_some_and(|n| n == ".md")
            {
                paths.push(path);
            }
        }
        paths.sort();
        if paths.len() > options["max_entries"].as_u64().unwrap() as usize {
            return Err(format!("{}: {} entries exceed skills.max_entries={}; remove/merge entries or increase the limit",dir.display(),paths.len(),options["max_entries"]).into());
        }
        for path in paths {
            let name = path
                .file_name()
                .and_then(|s| s.to_str())
                .ok_or("entry filename must be UTF-8")?;
            if name == ".md" || name.chars().any(char::is_control) {
                return Err("entry filename must have a nonempty, printable stem".into());
            }
            let meta = fs::symlink_metadata(&path)?;
            if !meta.file_type().is_file() {
                return Err(format!(
                    "{} must be a regular file, not a symlink/directory",
                    path.display()
                )
                .into());
            }
            let max = options["max_file_bytes"].as_u64().unwrap() as usize;
            if meta.len() > max as u64 {
                return Err(format!("{}: {} bytes exceed skills.max_file_bytes={max}; shorten/split the entry or increase the limit",path.display(),meta.len()).into());
            }
            // Bound reads even if another writer grows a discovered file.
            let file = OpenOptions::new()
                .read(true)
                .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK)
                .open(&path)?;
            if !file.metadata()?.file_type().is_file() {
                return Err(format!("{name} must be a regular file").into());
            }
            let mut bytes = Vec::new();
            std::io::Read::read_to_end(&mut std::io::Read::take(file, max as u64 + 1), &mut bytes)?;
            if bytes.len() > max {
                return Err(format!("{} exceeds skills.max_file_bytes={max}; shorten/split the entry or increase the limit",path.display()).into());
            }
            let text = std::str::from_utf8(&bytes)?;
            let mut entry =
                parse_skill(name, text).map_err(|e| format!("{}: {e}", path.display()))?;
            entry["path"] = json!(path);
            let core = entry["core"] == true;
            let inventory = json!({"filename":name,"kind":entry["kind"],"description":entry["description"],"core":core,"path":path});
            let rendered = if core {
                format!(
                    "\n[Core entry {}]\n{}\n{}\n[End core entry]\n",
                    serde_json::to_string(name)?,
                    inventory,
                    entry["body"].as_str().unwrap()
                )
            } else {
                format!("\n[Available entry] {inventory}\n")
            };
            let key = if core {
                "max_core_entry_tokens"
            } else {
                "max_inventory_entry_tokens"
            };
            if skills_tokens(&rendered) > options[key].as_u64().unwrap() as usize {
                return Err(format!("{}: {} estimated tokens exceed skills.{key}={}; shorten/split the entry or increase the limit",path.display(),skills_tokens(&rendered),options[key]).into());
            }
            added.push_str(&rendered);
            if !core {
                entry.as_object_mut().unwrap().remove("body");
                entry.as_object_mut().unwrap().remove("python");
            }
            entries.push(entry);
        }
        if skills_tokens(&added) > options["max_system_tokens"].as_u64().unwrap() as usize {
            return Err(format!("{}: {} estimated tokens including guidance exceed skills.max_system_tokens={}; shorten/remove entries or increase the limit",dir.display(),skills_tokens(&added),options["max_system_tokens"]).into());
        }
        system.push_str(&added);
    }
    Ok(
        json!({"version":1,"system":system,"entries":entries,"options":options,
        "estimated_added_tokens":skills_tokens(&added),"estimator":"unicode-chars/3-v1 (estimate, not a guarantee)"}),
    )
}
impl Host {
    fn system_prompt(&self) -> &str {
        self.skills["system"].as_str().unwrap_or(SYSTEM)
    }
    fn check_system_budget(&self, limit: usize) -> Result<()> {
        self.check_model_system_budget(&self.provider.model, limit)
    }
    fn check_model_system_budget(&self, model: &str, limit: usize) -> Result<()> {
        let protected = (self.system_prompt().chars().count() + 512).div_ceil(3);
        let available = model_input_budget(limit, &self.reasoning_metadata(model), 4096);
        if protected + 1024 >= available {
            return Err(format!("Unsatisfiable protected system-prefix budget: {protected} estimated input tokens plus 1024 continuation reserve do not fit input budget {available} (context limit {limit}, 4096 output reserve); choose a larger-context model or start a new session with fewer core entries").into());
        }
        Ok(())
    }
    fn initialize_skills(&mut self) -> Result<()> {
        self.execution.block_startup();
        self.check_system_budget(self.provider.context_limit)?;
        let entries = self.skills["entries"]
            .as_array()
            .ok_or("invalid skills snapshot entries")?
            .iter()
            .filter(|e| e["core"] == true && e["kind"] == "python")
            .cloned()
            .collect::<Vec<_>>();
        if entries.is_empty() {
            self.execution.finish_startup(true);
            return Ok(());
        }
        self.journal.append("startup_begin",json!({"generation":self.execution.generation(),"entries":entries.iter().map(|e|&e["filename"]).collect::<Vec<_>>()}))?;
        self.execution.begin_startup();
        let outcome = (|| -> Result<()> {
            let mut validation = String::new();
            for entry in &entries {
                validation.push_str(&format!(
                    "compile({}, {}, 'exec')\n",
                    serde_json::to_string(&entry["python"])?,
                    serde_json::to_string(&entry["path"])?
                ));
            }
            let id = format!("startup-validate-{}", self.journal.seq);
            let result = self.execute(&id, &validation, false)?;
            if result["status"] != "ok" {
                return Err(format!(
                    "startup precompilation failed; diagnostics in {}",
                    result["stderr"]["ref"]
                )
                .into());
            }
            for entry in entries {
                let id = format!("startup-{}", self.journal.seq);
                self.journal.append("startup_entry",json!({"operation":id,"generation":self.execution.generation(),"filename":entry["filename"],"sha256":entry["sha256"],"source":entry["python"]}))?;
                let result = self.execute(
                    &id,
                    entry["python"].as_str().ok_or("missing startup source")?,
                    false,
                )?;
                if result["status"] != "ok" {
                    return Err(format!("startup {} failed; diagnostics in {}; earlier side effects are not rolled back",entry["filename"],result["stderr"]["ref"]).into());
                }
            }
            Ok(())
        })();
        self.execution.finish_startup(false);
        self.journal.append(
            "startup_end",
            json!({"generation":self.execution.generation(),"status":if outcome.is_ok(){"ok"}else{"error"}}),
        )?;
        self.execution.finish_startup(outcome.is_ok());
        outcome
    }
    fn config_command(&mut self, args: &str) -> Result<()> {
        let (verb, rest) = args
            .split_once(char::is_whitespace)
            .map(|(a, b)| (a, b.trim()))
            .unwrap_or((args, ""));
        if verb.is_empty() {
            self.ui_json("Configuration (loading changes apply on /new)",&json!({"path":self.home.join("config.json"),"effective":effective_config(&self.provider.config_defaults)?,"session_skills_options":self.skills["options"],"skills_changes_pending":skills_options(&self.provider.config_defaults)?!=self.skills["options"],"config_changes_pending":self.provider.config_defaults!=self.provider.config}));
            return Ok(());
        }
        if verb == "reload" {
            if !rest.is_empty() {
                return Err("usage: /config reload".into());
            }
            let next = load_json(&self.home.join("config.json"))?;
            validate_config(&next)?;
            self.provider.accept_defaults(next);
            self.ui_text("Configuration reloaded. Session prompt/startup snapshot unchanged; catalog refresh preferences apply immediately, other loading defaults apply on /new.");
            return Ok(());
        }
        let (key, value) = rest
            .split_once(char::is_whitespace)
            .map(|(a, b)| (a, b.trim()))
            .unwrap_or((rest, ""));
        let parts = key.split('.').collect::<Vec<_>>();
        if key.is_empty()
            || parts.iter().any(|p| {
                p.is_empty()
                    || !p
                        .chars()
                        .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
            })
        {
            return Err("use a dotted configuration key".into());
        }
        if parts.iter().any(|p| config_secret_key(p)) {
            return Err("credentials belong in auth.json and /login, not /config".into());
        }
        if verb == "get" {
            if !value.is_empty() {
                return Err("usage: /config get <key>".into());
            }
            let effective = effective_config(&self.provider.config_defaults)?;
            let mut found = &effective;
            for part in &parts {
                found = found.get(*part).ok_or("unknown configuration key")?;
            }
            self.ui_json(key, found);
            return Ok(());
        }
        if verb != "set" && verb != "unset" {
            return Err(
                "usage: /config [get <key> | set <key> <JSON-value> | unset <key> | reload]".into(),
            );
        }
        if verb == "unset" && !value.is_empty() {
            return Err("usage: /config unset <key>".into());
        }
        let mut next = self.provider.config_defaults.clone();
        let mut target = &mut next;
        for part in &parts[..parts.len() - 1] {
            let object = target
                .as_object_mut()
                .ok_or("configuration key crosses a non-object")?;
            target = object
                .entry((*part).to_string())
                .or_insert_with(|| json!({}));
        }
        let object = target
            .as_object_mut()
            .ok_or("configuration parent must be an object")?;
        if verb == "set" {
            object.insert(
                parts.last().unwrap().to_string(),
                serde_json::from_str(value)?,
            );
        } else {
            object.remove(*parts.last().unwrap());
        }
        validate_config(&next)?;
        let lock = OpenOptions::new()
            .create(true)
            .read(true)
            .write(true)
            .truncate(false)
            .mode(0o600)
            .open(self.home.join("config.lock"))?;
        if unsafe { libc::flock(lock.as_raw_fd(), libc::LOCK_EX) } != 0 {
            return Err(io::Error::last_os_error().into());
        }
        let path = self.home.join("config.json");
        if load_json(&path)? != self.provider.config_defaults {
            return Err("config.json changed externally; /config reload before editing".into());
        }
        write_private_json(&path, &next)?;
        self.provider.accept_defaults(next);
        self.ui_text("Configuration saved. Current session snapshot unchanged; catalog refresh preferences apply immediately, other loading defaults apply on /new.");
        Ok(())
    }
}

