    #[test]
    fn e2e_foreground_shell_journal_failure_kills_and_reaps_group() {
        let home = std::env::temp_dir().join(format!(
            "py-shell-journal-failure-{}-{}",
            std::process::id(),
            super::unique_id()
        ));
        let script = r#"
import os,sys,json,subprocess,resource,signal,time,glob
home=sys.argv[2]
def limit_file_size():
 signal.signal(signal.SIGXFSZ,signal.SIG_IGN)
 resource.setrlimit(resource.RLIMIT_FSIZE,(65536,65536))
command='echo $$ > "$SHELL_PID_FILE"; trap "" TERM; printf before-failure; sleep .1; python3 -c "print(\'x\'*50000)"; sleep 20'
p=subprocess.Popen([sys.argv[1],'--json','--json-input','--no-model'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
 env=dict(os.environ,PY_HOME=home,SHELL_PID_FILE=home+'/shell-pid'),preexec_fn=limit_file_size)
pid=None
try:
 out,err=p.communicate((json.dumps({'id':'disk-failure','kind':'shell','command':command})+'\n').encode(),timeout=6)
 assert p.returncode!=0,(out,err)
 pid=int(open(home+'/shell-pid').read())
 try:os.kill(pid,0);raise AssertionError('journal failure left foreground leader alive/unreaped')
 except ProcessLookupError:pass
 assert not glob.glob(home+'/.*-stdout-*') and not glob.glob(home+'/.*-stderr-*'),os.listdir(home)
 records=[json.loads(line) for path in glob.glob(home+'/sessions/*.jsonl') for line in open(path) if line.endswith('\n')]
 operation=next(v['payload']['operation'] for v in records if v['kind']=='intent' and v['payload']['type']=='shell')
 assert not any(v['kind']=='shell_completion' and v['payload']['operation']==operation for v in records),records[-3:]
 assert not any(v['kind']=='stream_complete' and v['payload']['operation']==operation for v in records),records[-3:]
finally:
 if pid is None and os.path.exists(home+'/shell-pid'):pid=int(open(home+'/shell-pid').read())
 if pid is not None:
  try:os.killpg(pid,signal.SIGKILL)
  except ProcessLookupError:pass
 if p.poll() is None:p.kill();p.wait()
"#;
        let out = crate::test_support::run_python_fixture_with(
            "py-shell-failure-fixture",
            script,
            std::time::Duration::from_secs(60),
            |command| {
                command.arg(home.to_str().unwrap());
            },
        );
        assert!(
            out.status.success(),
            "foreground shell failure fixture:\n{}\n{}",
            String::from_utf8_lossy(&out.stderr),
            String::from_utf8_lossy(&out.stdout)
        );
    }

    // Real CLI driver with bounded event waits; failed assertions reap the child.
    struct InputClient {
        child: std::process::Child,
        input: Option<std::process::ChildStdin>,
        output: std::sync::mpsc::Receiver<Value>,
        home: PathBuf,
    }
    impl InputClient {
        fn new(resume: Option<(PathBuf, PathBuf)>) -> Self {
            use std::io::BufRead;
            let (home, session) = match resume {
                Some((h, s)) => (h, Some(s)),
                None => (
                    std::env::temp_dir().join(format!(
                        "py-input-e2e-{}-{}",
                        std::process::id(),
                        std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap()
                            .as_nanos()
                    )),
                    None,
                ),
            };
            let mut cmd = crate::test_command(std::env::var("PY_HARNESS_BIN").unwrap());
            cmd.args(["--json", "--json-input", "--no-model"])
                .env("PY_HOME", &home)
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::inherit());
            if let Some(session) = session {
                cmd.arg("--session").arg(session);
            }
            let mut child = cmd.spawn().unwrap();
            let input = child.stdin.take();
            let stdout = child.stdout.take().unwrap();
            let (tx, output) = std::sync::mpsc::channel();
            std::thread::spawn(move || {
                for line in std::io::BufReader::new(stdout).lines() {
                    let event = serde_json::from_str(&line.unwrap()).unwrap();
                    if tx.send(event).is_err() {
                        break;
                    }
                }
            });
            let mut client = Self {
                child,
                input,
                output,
                home,
            };
            client.until("ready", None);
            client
        }
        fn send(&mut self, v: Value) {
            writeln!(self.input.as_mut().unwrap(), "{v}").unwrap();
        }
        fn until(&mut self, kind: &str, id: Option<&str>) -> Value {
            loop {
                let v = self
                    .output
                    .recv_timeout(std::time::Duration::from_secs(5))
                    .expect("CLI must remain responsive");
                if kind == "rejected" && id.is_some_and(|id| v["command_id"] == id) {
                    assert_ne!(
                        v["kind"], "accepted",
                        "invalid replies must not be accepted first"
                    );
                    assert_ne!(v["kind"], "completed", "invalid replies must not complete");
                }
                if v["kind"] == kind && id.is_none_or(|id| v["command_id"] == id) {
                    return v;
                }
            }
        }
        fn finish(mut self) -> PathBuf {
            self.input.take();
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
            loop {
                if let Some(status) = self.child.try_wait().unwrap() {
                    assert!(status.success());
                    break;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "CLI must exit after EOF"
                );
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
            self.home.clone()
        }
    }
    impl Drop for InputClient {
        fn drop(&mut self) {
            let _ = self.child.kill();
            let _ = self.child.wait();
        }
    }
    fn input_command(id: &str, p: &Value, action: &str, value: Option<&str>) -> Value {
        json!({"id":id,"kind":"stdin_reply","prompt_id":p["prompt_id"],"operation":p["operation"],
            "worker_generation":p["worker_generation"],"action":action,"value":value})
    }
    #[test]
    fn e2e_input_correlation_and_duplicate_replies() {
        let mut c = InputClient::new(None);
        c.send(py("cell","import builtins\na=input('first?')\nb=builtins.input('second?')\nassert (a,b)==('λ🙂','')\nassert H.records.stdin[:]==['λ🙂','']"));
        let first = c.until("input_prompt", None);
        assert!(first["prompt_id"].is_string());
        assert_eq!(first["operation"], "cell");
        for (id, field, value) in [
            ("bad-prompt", "prompt_id", json!("wrong")),
            ("bad-op", "operation", json!("other")),
            ("bad-generation", "worker_generation", json!(999)),
        ] {
            let mut reply = input_command(id, &first, "text", Some("poison"));
            reply[field] = value;
            c.send(reply);
            c.until("rejected", Some(id));
        }
        for (id, action, value) in [
            ("bool-action", json!(true), json!("poison")),
            ("unknown-action", json!("other"), json!("poison")),
            ("missing-value", json!("text"), Value::Null),
            ("wrong-value", json!("text"), json!(42)),
        ] {
            let mut reply = input_command(id, &first, "text", Some("poison"));
            reply["action"] = action;
            reply["value"] = value;
            c.send(reply);
            c.until("rejected", Some(id));
        }
        c.send(json!({"id":"missing-link","kind":"stdin_reply","value":"poison"}));
        c.until("rejected", Some("missing-link"));
        let mut reply = input_command("one", &first, "text", Some("λ🙂"));
        reply.as_object_mut().unwrap().remove("action"); // omitted action defaults to text
        c.send(reply);
        c.until("completed", Some("one"));
        let second = c.until("input_prompt", None);
        assert_ne!(first["prompt_id"], second["prompt_id"]);
        c.send(input_command("one", &second, "text", Some("duplicate")));
        c.until("rejected", Some("one"));
        c.send(input_command("late", &first, "text", Some("late")));
        c.until("rejected", Some("late"));
        c.send(input_command("two", &second, "text", Some("")));
        c.until("completed", Some("two"));
        assert_eq!(c.until("completed", Some("cell"))["status"], "ok");
        c.send(input_command("after", &second, "text", Some("late")));
        c.until("rejected", Some("after"));
        let h = c.finish();
        let j = journal(&h);
        let inputs: Vec<_> = j.iter().filter(|v| v["kind"] == "stdin").collect();
        assert_eq!(inputs.len(), 2);
        for (index, prompt, reply) in [(0, &first, "one"), (1, &second, "two")] {
            let input = inputs[index];
            assert_eq!(input["payload"]["prompt_id"], prompt["prompt_id"]);
            assert_eq!(input["payload"]["operation"], "cell");
            assert_eq!(input["payload"]["index"], index);
            let opened = j
                .iter()
                .find(|v| {
                    v["kind"] == "input_prompt" && v["payload"]["prompt_id"] == prompt["prompt_id"]
                })
                .unwrap();
            let accepted = j
                .iter()
                .find(|v| v["kind"] == "accepted" && v["payload"]["command_id"] == reply)
                .unwrap();
            let closed: Vec<_> = j
                .iter()
                .filter(|v| {
                    v["kind"] == "input_closed" && v["payload"]["prompt_id"] == prompt["prompt_id"]
                })
                .collect();
            assert_eq!(closed.len(), 1);
            assert_eq!(closed[0]["payload"]["action"], "text");
            assert!(opened["seq"].as_u64() < accepted["seq"].as_u64());
            assert!(accepted["seq"].as_u64() < input["seq"].as_u64());
            assert!(input["seq"].as_u64() < closed[0]["seq"].as_u64());
        }
    }
    #[test]
    fn e2e_input_eof_and_resume() {
        let mut c = InputClient::new(None);
        c.send(py(
            "saved",
            "assert input()=='retained🙂'\nassert input()==''",
        ));
        let p = c.until("input_prompt", None);
        c.send(input_command("reply", &p, "text", Some("retained🙂")));
        c.until("completed", Some("reply"));
        let p = c.until("input_prompt", None);
        c.send(input_command("reply-empty", &p, "text", Some("")));
        c.until("completed", Some("reply-empty"));
        assert_eq!(c.until("completed", Some("saved"))["status"], "ok");
        c.send(py("eof","try:\n input()\nexcept EOFError:\n pass\nelse:\n raise AssertionError('expected EOF')\nassert H.records.stdin[:]==['retained🙂','']"));
        let p = c.until("input_prompt", None);
        c.send(input_command("eof-reply", &p, "eof", None));
        c.until("completed", Some("eof-reply"));
        assert_eq!(c.until("completed", Some("eof"))["status"], "ok");
        c.send(py("uncaught", "input()"));
        let p = c.until("input_prompt", None);
        c.send(input_command("eof-uncaught", &p, "eof", None));
        c.until("completed", Some("eof-uncaught"));
        assert_eq!(c.until("completed", Some("uncaught"))["status"], "error");
        let h = c.finish();
        let session = std::fs::read_dir(h.join("sessions"))
            .unwrap()
            .next()
            .unwrap()
            .unwrap()
            .path();
        let mut c = InputClient::new(Some((h, session)));
        c.send(py(
            "restored",
            "assert H.records.stdin[:]==['retained🙂','']\nassert 'p' not in globals()",
        ));
        assert_eq!(c.until("completed", Some("restored"))["status"], "ok");
        c.send(py(
            "channel-eof",
            "try:\n input()\nexcept EOFError:\n pass\nelse:\n raise AssertionError('expected EOF')",
        ));
        c.until("input_prompt", None);
        c.input.take();
        assert_eq!(c.until("completed", Some("channel-eof"))["status"], "ok");
        c.finish();
    }
    #[test]
    fn e2e_input_generation_and_reply_ids_survive_resume() {
        let mut c = InputClient::new(None);
        for id in ["reset1", "reset2"] {
            c.send(json!({"id":id,"kind":"reset"}));
            c.until("completed", Some(id));
        }
        c.send(py("first", "input()"));
        let mut previous = c.until("input_prompt", None);
        assert_eq!(previous["worker_generation"], 2);
        c.send(input_command("reply0", &previous, "text", Some("initial")));
        c.until("completed", Some("reply0"));
        c.until("completed", Some("first"));
        let mut home = c.finish();
        for generation in [3, 4] {
            let session = std::fs::read_dir(home.join("sessions"))
                .unwrap()
                .next()
                .unwrap()
                .unwrap()
                .path();
            let mut c = InputClient::new(Some((home, session)));
            let id = format!("cell{generation}");
            c.send(py(&id, "assert H.records.stdin[0]=='initial'\ninput()"));
            let p = c.until("input_prompt", None);
            assert_eq!(p["worker_generation"], generation);
            assert_ne!(p["prompt_id"], previous["prompt_id"]);
            c.send(input_command("reply0", &p, "text", Some("duplicate")));
            c.until("rejected", Some("reply0"));
            c.send(input_command("stale", &previous, "text", Some("late")));
            c.until("rejected", Some("stale"));
            let reply = format!("reply{generation}");
            c.send(input_command(&reply, &p, "eof", None));
            c.until("completed", Some(&reply));
            assert_eq!(c.until("completed", Some(&id))["status"], "error");
            previous = p;
            home = c.finish();
        }
    }
    #[test]
    fn e2e_worker_stdin_is_not_command_stdin() {
        let(ev,_)=run(vec![py("raw","import os,sys,subprocess\nassert os.read(0,4096)==b''\nassert sys.stdin.read()==''\nassert subprocess.check_output(['python3','-c','import sys; print(repr(sys.stdin.read()))'])==b\"''\\n\""),
            py("next","print('commands preserved')")]);
        assert_eq!(done(&ev, "raw")["status"], "ok");
        assert_eq!(done(&ev, "next")["status"], "ok");
    }
    #[test]
    fn e2e_crash_at_input_does_not_reopen_prompt() {
        let mut c = InputClient::new(None);
        c.send(py("unknown", "input('unanswered')"));
        let p = c.until("input_prompt", None);
        let home = c.home.clone();
        c.child.kill().unwrap();
        c.child.wait().unwrap();
        drop(c);
        let session = std::fs::read_dir(home.join("sessions"))
            .unwrap()
            .next()
            .unwrap()
            .unwrap()
            .path();
        let mut c = InputClient::new(Some((home, session)));
        c.send(json!({"id":"recovery","kind":"recovery"}));
        let r = c.until("recovery", Some("recovery"));
        assert!(r["operations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|v| v["operation"] == "unknown"
                && v["state"] == "unknown"
                && v["replay_allowed"] == false));
        c.send(input_command("late", &p, "text", Some("late")));
        c.until("rejected", Some("late"));
        c.send(py(
            "next",
            "assert len(H.records.stdin)==0\nassert 'input' not in globals()",
        ));
        assert_eq!(c.until("completed", Some("next"))["status"], "ok");
        let j = journal(&c.finish());
        assert_eq!(j.iter().filter(|v| v["kind"] == "input_prompt").count(), 1);
        assert_eq!(
            j.iter()
                .filter(|v| v["kind"] == "code" && v["payload"]["source"] == "input('unanswered')")
                .count(),
            1
        );
        assert!(!j
            .iter()
            .any(|v| v["kind"] == "input_closed" && v["payload"]["prompt_id"] == p["prompt_id"]));
    }
    #[test]
    fn e2e_input_cancel_is_sticky_and_ipc_survives() {
        for action in ["interrupt", "cancel"] {
            let mut c = InputClient::new(None);
            c.send(py("owner","try:\n input('cancel?')\nexcept KeyboardInterrupt:\n pass\ntry:\n input('must-not-reopen')\nexcept KeyboardInterrupt:\n pass\nagent.loop.stop()"));
            let p = c.until("input_prompt", None);
            c.send(if action == "interrupt" {
                json!({"id":"cancel","kind":"interrupt"})
            } else {
                input_command("cancel", &p, "cancel", None)
            });
            c.until("completed", Some("cancel"));
            assert_eq!(c.until("completed", Some("owner"))["status"], "cancelled");
            c.send(input_command("late", &p, "text", Some("late")));
            c.until("rejected", Some("late"));
            c.send(py(
                "next",
                "assert H.records.stdin[:]==[]\nagent.say('ipc alive')",
            ));
            assert_eq!(c.until("completed", Some("next"))["status"], "ok");
            let j = journal(&c.finish());
            assert_eq!(j.iter().filter(|v| v["kind"] == "input_prompt").count(), 1);
            assert_eq!(j.iter().filter(|v| v["kind"] == "cancel").count(), 1);
        }
    }
    #[test]
    fn e2e_input_cancel_does_not_start_blocking_helpers() {
        for helper in [
            "agent.sh('sleep 30')",
            "agent.llm('must not dispatch')",
            "agent.llm.image('must not generate',model='openai/gpt-image-1')",
            "agent.say('must not say')",
            "agent.context.read_text('must not select', start=0, stop=15)",
            "agent.context.read_raw(b'must not attach')",
            "agent.loop.reset_python()",
            "agent.loop.stop()",
        ] {
            let mut c = InputClient::new(None);
            c.send(py("owner",&format!("try:\n input()\nexcept KeyboardInterrupt:\n try:\n  {helper}\n except KeyboardInterrupt:\n  print('HELPER-CANCELLED')\n else:\n  raise AssertionError('helper executed')")));
            let p = c.until("input_prompt", None);
            c.send(input_command("cancel", &p, "cancel", None));
            c.until("completed", Some("cancel"));
            let done = c.until("completed", Some("owner"));
            assert_eq!(done["status"], "cancelled");
            assert_eq!(done["stderr"]["bytes"], 0);
            let j = journal(&c.finish());
            assert_eq!(
                j.iter()
                    .filter(|v| v["kind"] == "stream" && v["payload"]["collection"] == "stdout")
                    .map(|v| v["payload"]["text"].as_str().unwrap())
                    .collect::<String>(),
                "HELPER-CANCELLED\n"
            );
            assert!(!j
                .iter()
                .any(|v| ["say", "context_add", "raw", "request", "worker_reset"]
                    .contains(&v["kind"].as_str().unwrap_or(""))));
            assert!(!j.iter().any(|v| v["kind"] == "intent"
                && ["shell", "provider", "image"]
                    .contains(&v["payload"]["type"].as_str().unwrap_or(""))));
        }
    }
    #[test]
    fn e2e_input_cancel_escalates_if_python_ignores_it() {
        let mut c = InputClient::new(None);
        c.send(py(
            "owner",
            "try:\n input()\nexcept KeyboardInterrupt:\n while True: pass",
        ));
        let p = c.until("input_prompt", None);
        c.send(input_command("cancel", &p, "cancel", None));
        c.until("completed", Some("cancel"));
        let result = c.until("completed", Some("owner"));
        assert_eq!(result["status"], "cancelled");
        assert_eq!(result["stdout"]["complete"], false);
        c.send(py(
            "next",
            "assert H.records.stdin[:]==[]\nassert len(agent.context.items())>0",
        ));
        assert_eq!(c.until("completed", Some("next"))["status"], "ok");
        assert!(journal(&c.finish())
            .iter()
            .any(|v| v["kind"] == "worker_reset" && v["payload"]["generation"] == 1));
    }
    #[test]
    fn e2e_input_wait_drains_output_and_sigint() {
        let mut c = InputClient::new(None);
        c.send(py(
            "owner",
            "import os\nos.write(1,b'prefix-before-input')\ninput('wait?')",
        ));
        c.until("input_prompt", None);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let mut captured = false;
        while std::time::Instant::now() < deadline {
            if journal(&c.home)
                .iter()
                .any(|v| v["kind"] == "stream" && v["payload"]["text"] == "prefix-before-input")
            {
                captured = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        unsafe {
            libc::kill(c.child.id() as i32, libc::SIGINT);
        }
        assert_eq!(c.until("completed", Some("owner"))["status"], "cancelled");
        assert!(
            captured,
            "waiting for input must not suspend stream commits"
        );
        c.send(py(
            "next",
            "assert H.records.stdout[0]=='prefix-before-input'\nassert len(H.records.stdin)==0",
        ));
        assert_eq!(c.until("completed", Some("next"))["status"], "ok");
        c.finish();
    }
    #[test]
    fn e2e_interrupt_active_python_without_replay() {
        let (ev, h) = run(vec![
            py(
                "a",
                "import time\nprint('started',flush=True)\ntime.sleep(30)",
            ),
            json!({"id":"cancel","kind":"interrupt"}),
            py("b", "print('alive')"),
        ]);
        assert_eq!(done(&ev, "a")["status"], "cancelled");
        assert_eq!(done(&ev, "b")["status"], "ok");
        assert_eq!(
            journal(&h)
                .iter()
                .filter(|v| v["kind"] == "code"
                    && v["payload"]["source"]
                        .as_str()
                        .unwrap_or("")
                        .contains("time.sleep"))
                .count(),
            1
        );
    }

    #[test]
    fn e2e_image_generation_then_explicit_image_input() {
        let png = {
            let mut out = std::io::Cursor::new(Vec::new());
            image::DynamicImage::new_rgb8(2, 2)
                .write_to(&mut out, image::ImageFormat::Png)
                .unwrap();
            base64::Engine::encode(&base64::engine::general_purpose::STANDARD, out.into_inner())
        };
        let mut step = 0;
        let server = crate::test_support::MockProvider::json(4, move |_| {
            let current = step;
            step += 1;
            if current == 1 {
                json!({"data":[{"b64_json":png}]}).to_string()
            } else {
                let code = match current {
                    0 => "r=agent.llm.image('draw a square',model='openai/gpt-image-1')",
                    2 => "agent.context.read_raw(H.records.raw[0])",
                    _ => "agent.loop.stop()",
                };
                json!({"choices":[{"message":{"content":code}}]}).to_string()
            }
        });
        let home = crate::test_support::TestDirectory::new("py-image-e2e");
        let mut command = crate::test_command(std::env::var("PY_HARNESS_BIN").unwrap());
        command
            .args(["--json", "--json-input"])
            .env("PY_HOME", home.path())
            .env("OPENAI_BASE_URL", format!("http://{}/v1", server.address))
            .env("OPENAI_API_KEY", "fixture")
            .env("PY_MODEL", "openai/fixture");
        let output = crate::test_support::ProcessSession::spawn(command).collect(
            &crate::test_support::jsonl_input(&[
                json!({"id":"a","kind":"submit","text":"make then inspect image"}),
            ]),
            std::time::Duration::from_secs(30),
        );
        let events = crate::test_support::jsonl_events(&output);
        assert!(
            events
                .iter()
                .filter(|e| e["kind"] == "completed")
                .all(|e| e["status"] == "ok"),
            "{events:?}"
        );
        let bodies = server.finish();
        assert!(!bodies[2]["messages"].to_string().contains("data:image"));
        assert!(bodies[3]["messages"]
            .to_string()
            .contains("data:image/png;base64,"));
        let records = journal(home.path());
        assert!(records.iter().any(|v| v["kind"] == "raw"));
        assert!(records
            .iter()
            .filter(|v| v["kind"] == "request")
            .all(|v| v["payload"]["operation"].is_string()));
    }
