    #[test]
    fn e2e_interactive_cli_help_prefixes_and_completion() {
        let home = std::env::temp_dir().join(format!("py-pty-e2e-{}", super::now_ms()));
        let script = r#"
import os,pty,select,subprocess,time,sys,fcntl,termios
master,slave=pty.openpty()
def controlling():
    os.setsid();fcntl.ioctl(0,termios.TIOCSCTTY,0)
p=subprocess.Popen([sys.argv[1],'--no-model'],stdin=slave,stdout=slave,stderr=slave,
    env=dict(os.environ,PY_HOME=sys.argv[2],TERM='xterm-256color'),preexec_fn=controlling)
os.close(slave)
def collect(seconds=.15):
    end=time.monotonic()+seconds; data=b''
    while time.monotonic()<end:
        if select.select([master],[],[],.02)[0]:
            try:data+=os.read(master,65536)
            except OSError:break
    return data
data=b''
def wait_for(token,start=0):
    global data
    deadline=time.monotonic()+5
    while token not in data[start:]:
        data+=collect(.03)
        assert time.monotonic()<deadline,(token,data)
wait_for(b'\x1b[?2004h')
os.write(master,b'/he\t');wait_for(b'Fuzzy select')
os.write(master,b'\r');wait_for(b'\x1b[0J')
# First Enter selects /help from /help and /hotkeys; second submits it.
os.write(master,b'\r');wait_for(b'H stores full history')
start=len(data);os.write(master,b"@print('pty-result')\r");wait_for(b'status: ok',start)
os.write(master,b'/quit\r');data+=collect()
try:p.wait(timeout=3)
except subprocess.TimeoutExpired:p.kill();sys.stderr.buffer.write(data);raise
os.close(master)
sys.stdout.buffer.write(data)
"#;
        let out = crate::test_support::run_python_fixture_with(
            "py-interactive-help-fixture",
            script,
            std::time::Duration::from_secs(60),
            |command| {
                command.arg(home.to_str().unwrap());
            },
        );
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        let text = String::from_utf8_lossy(&out.stdout);
        assert!(
            text.contains("H stores full history"),
            "Tab completion/help failed: {text}"
        );
        assert!(text.contains("pty-result"));
        assert!(journal(&home)
            .iter()
            .any(|v| v["kind"] == "stream" && v["payload"]["text"] == "pty-result\n"));
    }
    #[test]
    fn e2e_interactive_input_partial_eof_and_ctrl_c() {
        let home = std::env::temp_dir().join(format!(
            "py-pty-input-{}-{}",
            std::process::id(),
            super::now_ms()
        ));
        let script = r#"
import os,pty,select,subprocess,time,sys,json,fcntl,termios
master,slave=pty.openpty()
def child_terminal():
 os.setsid();fcntl.ioctl(0,termios.TIOCSCTTY,0)
p=subprocess.Popen([sys.argv[1],'--no-model'],stdin=slave,stdout=slave,stderr=slave,
 env=dict(os.environ,PY_HOME=sys.argv[2],TERM='xterm-256color'),preexec_fn=child_terminal)
os.close(slave)
transcript=bytearray();cursor=0
def until(needle, timeout=4):
 global cursor
 deadline=time.monotonic()+timeout
 while needle not in transcript[cursor:]:
  assert time.monotonic()<deadline,('waiting for',needle,bytes(transcript))
  if select.select([master],[],[],.05)[0]:
   transcript.extend(os.read(master,65536))
 cursor=transcript.index(needle,cursor)+len(needle)
def wait_prompt(text):
 # Terminal echo also contains source literals. Synchronize on the real durable
 # prompt event rather than treating echoed code as evidence of an active prompt.
 deadline=time.monotonic()+4
 while time.monotonic()<deadline:
  for name in os.listdir(os.path.join(sys.argv[2],'sessions')):
   with open(os.path.join(sys.argv[2],'sessions',name)) as f:
    for line in f:
     if not line.endswith('\n'):continue
     event=json.loads(line)
     if event['kind']=='input_prompt' and event['payload']['prompt']==text:return
  if select.select([master],[],[],.02)[0]:transcript.extend(os.read(master,65536))
 raise AssertionError(('no actual input prompt',text,bytes(transcript)))
def command(text):os.write(master,text.encode()+b'\r')
try:
 # Editor-ready reports, unlike echoed/redrawn prompt strings, cannot be
 # mistaken for the next raw editor while a canonical input is still closing.
 until(b'\x1b[?2004h')
 command('/help');until(b'\x1b[?2004h')
 command("@answer=input('interactive-name? '); print('ANSWER='+answer)")
 wait_prompt('interactive-name? ');os.write(master,'Ada🙂\n'.encode());until(b'ANSWER=Ada');until(b'\x1b[?2004h')
 command("@import builtins; print('IMPORTED='+builtins.input('imported-name? '))")
 wait_prompt('imported-name? ');os.write(master,b'Grace\n');until(b'IMPORTED=Grace');until(b'\x1b[?2004h')
 command("@print('PARTIAL='+input('partial-then-newline? '))")
 wait_prompt('partial-then-newline? ');os.write(master,b'part\x04')
 time.sleep(.1);os.write(master,b'tail\n');until(b'PARTIAL=parttail');until(b'\x1b[?2004h')
 command("@print('FD0='+repr(__import__('os').read(0,32)))")
 until(b"FD0=b''");until(b'\x1b[?2004h')
 command("@print('BEFORE-INPUT',flush=True); input('partial-input? ')")
 wait_prompt('partial-input? ')
 # Canonical Ctrl-D releases partial text without a newline: poll readability
 # must not turn into a blocking read_line that swallows cancellation.
 os.write(master,b'partial\x04')
 time.sleep(.1);os.write(master,b'\x03')
 until(b'\x1b[?2004h')
 command("@print('AFTER-CANCEL'); print(H.records.stdin[:])")
 until(b'AFTER-CANCEL');until(b'\x1b[?2004h')
 command("@exec(\"try:\\n input('eof-input? ')\\nexcept EOFError: print('PYTHON-EOF')\")")
 wait_prompt('eof-input? ');os.write(master,b'\x04');until(b'PYTHON-EOF');until(b'\x1b[?2004h')
 command("!printf shell-interactive");until(b'shell-interactive');until(b'\x1b[?2004h')
 command('/quit');p.wait(timeout=4)
 assert p.returncode==0
finally:
 if p.poll() is None:p.kill();p.wait()
 os.close(master)
 sys.stdout.buffer.write(transcript)
"#;
        let out = crate::test_support::run_python_fixture_with(
            "py-input-pty-fixture",
            script,
            std::time::Duration::from_secs(60),
            |command| {
                command.arg(home.to_str().unwrap());
            },
        );
        assert!(
            out.status.success(),
            "PTY failed:\n{}\n{}",
            String::from_utf8_lossy(&out.stderr),
            String::from_utf8_lossy(&out.stdout)
        );
        let j = journal(&home);
        let input: Vec<_> = j
            .iter()
            .filter(|v| v["kind"] == "stdin")
            .map(|v| v["payload"]["text"].clone())
            .collect();
        assert_eq!(
            input,
            vec![json!("Ada🙂"), json!("Grace"), json!("parttail")]
        );
        assert!(j
            .iter()
            .any(|v| v["kind"] == "completion" && v["payload"]["status"] == "cancelled"));
        assert!(j
            .iter()
            .any(|v| v["kind"] == "input_closed" && v["payload"]["action"] == "eof"));
        assert!(j.iter().any(|v| v["kind"] == "stream"
            && v["payload"]["text"]
                .as_str()
                .unwrap_or("")
                .contains("AFTER-CANCEL")));
    }
    #[test]
    fn e2e_forced_gate_blocks_side_effects_and_allows_stderr_read() {
        let home = std::env::temp_dir().join(format!("py-forced-e2e-{}", super::now_ms()));
        let mut child = crate::test_command(std::env::var("PY_HARNESS_BIN").unwrap())
            .args(["--json", "--json-input", "--no-model"])
            .env("PY_HOME", &home)
            .env("PY_CONTEXT_LIMIT", "10000")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        use std::io::BufRead;
        let mut stdin = child.stdin.take().unwrap();
        let mut stdout = std::io::BufReader::new(child.stdout.take().unwrap());
        writeln!(stdin, "{}", json!({"id":"budget","kind":"status"})).unwrap();
        let mut ev = Vec::<Value>::new();
        let usage = loop {
            let mut line = String::new();
            assert!(stdout.read_line(&mut line).unwrap() > 0);
            let event: Value = serde_json::from_str(&line).unwrap();
            let usage = if event["kind"] == "status" {
                Some(event["context_usage"].clone())
            } else {
                None
            };
            ev.push(event);
            if let Some(usage) = usage {
                break usage;
            }
        };
        // Size this payload using the actual frozen prefix, not a hard-coded
        // SYSTEM length: enter forcing mode without overflowing the budget.
        let chars = (usage["input_token_budget"].as_u64().unwrap() as usize * 3 * 95 / 100)
            .saturating_sub(usage["rendered_chars"].as_u64().unwrap() as usize + 512);
        let source = format!("text={:?}\n", "x".repeat(chars))
            + &(0..chars)
                .step_by(8000)
                .map(|start| {
                    format!(
                        "agent.context.read_text(text, start={start}, stop={})\n",
                        (start + 8000).min(chars)
                    )
                })
                .collect::<String>();
        let invalid_reads = [
            ("old-slice", "agent.context.read_text(H.stderr[2][:500])"),
            (
                "presliced",
                "agent.context.read_text(H.stderr[2][:500], start=0, stop=500)",
            ),
            (
                "variable-index",
                "agent.context.read_text(H.stderr[side_effect], start=0, stop=500)",
            ),
            (
                "variable-bound",
                "agent.context.read_text(H.stderr[2], start=side_effect, stop=500)",
            ),
            (
                "bool-bound",
                "agent.context.read_text(H.stderr[2], start=False, stop=500)",
            ),
            (
                "none-bound",
                "agent.context.read_text(H.stderr[2], start=0, stop=None)",
            ),
            (
                "positional-bound",
                "agent.context.read_text(H.stderr[2], 0, 500)",
            ),
            (
                "missing-bound",
                "agent.context.read_text(H.stderr[2], start=0)",
            ),
            (
                "extra-bound",
                "agent.context.read_text(H.stderr[2], start=0, stop=500, max_chars=8000)",
            ),
            (
                "unpacked-bound",
                "agent.context.read_text(H.stderr[2], **{'start':0,'stop':500})",
            ),
            (
                "zero-cell",
                "agent.context.read_text(H.stderr[0], start=0, stop=500)",
            ),
            (
                "too-wide",
                "agent.context.read_text(H.stderr[2], start=0, stop=8001)",
            ),
            (
                "additional-code",
                "agent.context.read_text(H.stderr[2], start=0, stop=500); side_effect=1",
            ),
        ];
        let mut commands = vec![py("a", &source), py("b", "side_effect=1")];
        commands.extend(invalid_reads.iter().map(|(id, source)| py(id, source)));
        commands.extend([
            py(
                "c",
                "agent.context.read_text(H.stderr[2], stop=500, start=0)",
            ),
            py("d", "print('side_effect' in globals())"),
        ]);
        for c in commands {
            writeln!(stdin, "{}", c).unwrap();
        }
        drop(stdin);
        ev.extend(
            stdout
                .lines()
                .map(|line| serde_json::from_str::<Value>(&line.unwrap()).unwrap()),
        );
        assert!(child.wait().unwrap().success());
        assert_eq!(done(&ev, "a")["status"], "ok");
        assert_eq!(done(&ev, "b")["status"], "error");
        assert_eq!(done(&ev, "c")["status"], "ok");
        assert_eq!(done(&ev, "d")["status"], "error");
        assert_eq!(done(&ev, "b")["context_usage"]["forced"], true);
        for (id, _) in invalid_reads {
            assert_eq!(done(&ev, id)["status"], "error", "{id}");
        }
    }

    #[test]
    fn e2e_steering_is_delivered_at_cell_boundary() {
        let full = format!(
            "steer-at-boundary\n{}\nsteering-tail-λ",
            "🙂\n".repeat(5000)
        );
        let (_, h, r) = model_run(
            vec!["print('first')", "agent.loop.stop()"],
            vec![
                json!({"id":"a","kind":"submit","text":"first task"}),
                json!({"id":"s","kind":"submit","text":full,"mode":"steering"}),
            ],
        );
        assert_eq!(r.len(), 2);
        assert!(!r[0]["messages"].to_string().contains("steer-at-boundary"));
        assert!(r[1]["messages"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|message| message["content"].as_str())
            .any(|text| text == full));
        assert!(journal(&h)
            .iter()
            .any(|v| v["kind"] == "queue_delivered" && v["payload"]["command_id"] == "s"));
    }
