    #[test]
    fn e2e_key_auth_is_private_and_not_in_session() {
        let home = std::env::temp_dir().join(format!("py-auth-e2e-{}", super::now_ms()));
        std::fs::create_dir_all(&home).unwrap();
        let input = json!({"id":"a","kind":"login","provider":"openai","key":"sensitive-api-key"})
            .to_string()
            + "\n"
            + &json!({"id":"b","kind":"auth"}).to_string()
            + "\n";
        let mut child = crate::test_command(std::env::var("PY_HARNESS_BIN").unwrap())
            .args(["--json", "--json-input", "--no-model"])
            .env("PY_HOME", &home)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        child
            .stdin
            .take()
            .unwrap()
            .write_all(input.as_bytes())
            .unwrap();
        let out = child.wait_with_output().unwrap();
        assert!(out.status.success());
        assert!(!String::from_utf8_lossy(&out.stdout).contains("sensitive-api-key"));
        let stored: Value =
            serde_json::from_slice(&std::fs::read(home.join("auth.json")).unwrap()).unwrap();
        assert_eq!(stored["openai"]["key"], "sensitive-api-key");
        assert!(!journal(&home)
            .iter()
            .any(|v| v.to_string().contains("sensitive-api-key")));
        use std::os::unix::fs::PermissionsExt;
        assert_eq!(
            std::fs::metadata(home.join("auth.json"))
                .unwrap()
                .permissions()
                .mode()
                & 0o777,
            0o600
        );
    }

