    fn provider_fixture(
        provider: &str,
        api: &str,
        response: Value,
        command: Value,
    ) -> (Vec<Value>, PathBuf, String, Value) {
        use std::io::{BufRead, BufReader, Read};
        use std::net::TcpListener;
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut socket, _) = listener.accept().unwrap();
            socket
                .set_read_timeout(Some(std::time::Duration::from_secs(5)))
                .unwrap();
            let mut reader = BufReader::new(socket.try_clone().unwrap());
            let mut route = String::new();
            reader.read_line(&mut route).unwrap();
            let mut length = 0;
            let mut line = String::new();
            loop {
                line.clear();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" {
                    break;
                }
                if line.to_lowercase().starts_with("content-length:") {
                    length = line
                        .split(':')
                        .nth(1)
                        .unwrap()
                        .trim()
                        .parse::<usize>()
                        .unwrap();
                }
            }
            let mut bytes = vec![0; length];
            reader.read_exact(&mut bytes).unwrap();
            let request: Value = serde_json::from_slice(&bytes).unwrap();
            let body = response.to_string();
            write!(socket,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();
            (route, request)
        });
        let home = std::env::temp_dir().join(format!("py-wire-e2e-{}", super::now_ms()));
        std::fs::create_dir_all(&home).unwrap();
        std::fs::write(
            home.join("config.json"),
            json!({"providers":{provider:{
            "base_url":format!("http://{address}"),"api":api,
            "models":[{"id":"fixture","api":api,"context_limit":100000}]}}})
            .to_string(),
        )
        .unwrap();
        let mut child = crate::test_command(std::env::var("PY_HARNESS_BIN").unwrap())
            .args(["--json", "--json-input", "--no-model"])
            .env("PY_HOME", &home)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        writeln!(child.stdin.take().unwrap(), "{command}").unwrap();
        let out = child.wait_with_output().unwrap();
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        let events = String::from_utf8(out.stdout)
            .unwrap()
            .lines()
            .map(|l| serde_json::from_str(l).unwrap())
            .collect();
        let (route, request) = server.join().unwrap();
        (events, home, route, request)
    }
    #[test]
    fn e2e_responses_wire_and_all_output_text_blocks() {
        let (ev, h, route, request) = provider_fixture(
            "fixture",
            "openai-responses",
            json!({"output":[{"type":"reasoning","summary":[]},{"type":"message","content":[
                {"type":"output_text","text":"hello "},{"type":"output_text","text":"world"}]}],
                "usage":{"input_tokens":11,"output_tokens":4,"input_tokens_details":{"cached_tokens":3}}}),
            py(
                "a",
                "r=agent.llm('question', model='fixture/fixture')\nassert r=='hello world'",
            ),
        );
        assert_eq!(done(&ev, "a")["status"], "ok");
        assert!(route.contains("/responses"));
        assert_eq!(request["input"][0]["role"], "system");
        assert_eq!(request["input"][1]["role"], "user");
        assert_eq!(request["input"][1]["content"], "question");
        assert!(request.get("tools").is_none());
        assert_eq!(
            journal(&h)
                .iter()
                .rev()
                .find(|v| v["kind"] == "usage")
                .unwrap()["payload"]["cache_hit_tokens"],
            3
        );
    }

    #[test]
    fn e2e_inner_llm_images_anthropic_and_google_wire() {
        let mut output = std::io::Cursor::new(Vec::new());
        image::DynamicImage::new_rgb8(2, 2)
            .write_to(&mut output, image::ImageFormat::Png)
            .unwrap();
        let data = base64::Engine::encode(
            &base64::engine::general_purpose::STANDARD,
            output.into_inner(),
        );
        for (provider, api, response) in [
            (
                "fixture-a",
                "anthropic-messages",
                json!({"content":[{"type":"thinking","thinking":"private"},
                {"type":"text","text":"one"},{"type":"text","text":"two"}],
                "usage":{"input_tokens":10,"output_tokens":3,"cache_read_input_tokens":2}}),
            ),
            (
                "fixture-g",
                "google-generative-ai",
                json!({"candidates":[{"content":{"parts":[
                {"thought":true,"text":"private"},{"text":"one"},{"text":"two"}]}}],
                "usageMetadata":{"promptTokenCount":10,"candidatesTokenCount":3,"cachedContentTokenCount":2}}),
            ),
        ] {
            let code=format!("r=agent.llm('inspect',model='{provider}/fixture',system='image instructions',images=[{{'base64':'{data}'}}])\nassert r=='onetwo'");
            let (ev, h, _, request) = provider_fixture(provider, api, response, py("a", &code));
            assert_eq!(done(&ev, "a")["status"], "ok");
            if api == "anthropic-messages" {
                assert_eq!(request["system"], "image instructions");
                assert_eq!(request["messages"][0]["content"][1]["source"]["data"], data);
                assert_eq!(
                    request["messages"][0]["content"][1]["source"]["media_type"],
                    "image/png"
                );
            } else {
                assert_eq!(
                    request["systemInstruction"]["parts"][0]["text"],
                    "image instructions"
                );
                assert_eq!(
                    request["contents"][0]["parts"][1]["inlineData"]["data"],
                    data
                );
            }
            assert!(request.get("tools").is_none());
            let entries = journal(&h);
            let usage = &entries.iter().rev().find(|v| v["kind"] == "usage").unwrap()["payload"];
            assert_eq!(usage["input_tokens"], 10);
            assert_eq!(usage["cache_hit_tokens"], 2);
            assert!(!entries
                .iter()
                .any(|v| v["kind"] == "context_add" && v["payload"]["text"] == "onetwo"));
        }
    }

    #[test]
    fn e2e_auth_failure_response_secret_is_not_logged() {
        use std::io::{BufRead, BufReader, Read};
        use std::net::TcpListener;
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let address = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let (mut socket, _) = listener.accept().unwrap();
            let mut reader = BufReader::new(socket.try_clone().unwrap());
            let mut line = String::new();
            reader.read_line(&mut line).unwrap();
            let mut length = 0;
            loop {
                line.clear();
                reader.read_line(&mut line).unwrap();
                if line == "\r\n" {
                    break;
                }
                if line.to_lowercase().starts_with("content-length:") {
                    length = line
                        .split(':')
                        .nth(1)
                        .unwrap()
                        .trim()
                        .parse::<usize>()
                        .unwrap();
                }
            }
            let mut bytes = vec![0; length];
            reader.read_exact(&mut bytes).unwrap();
            let body =
                json!({"error":"invalid_client","access_token":"secret-in-error-body"}).to_string();
            write!(socket,"HTTP/1.1 401 Unauthorized\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();
        });
        let home = std::env::temp_dir().join(format!("py-auth-error-e2e-{}", super::now_ms()));
        let mut child = crate::test_command(std::env::var("PY_HARNESS_BIN").unwrap())
            .args(["--json", "--json-input", "--no-model"])
            .env("PY_HOME", &home)
            .env("PY_GITHUB_AUTH_URL", format!("http://{address}"))
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        writeln!(
            child.stdin.take().unwrap(),
            "{}",
            json!({"id":"a","kind":"login",
            "provider":"github-copilot","method":"oauth"})
        )
        .unwrap();
        let out = child.wait_with_output().unwrap();
        server.join().unwrap();
        let text = String::from_utf8(out.stdout).unwrap();
        assert!(text.contains("401"));
        assert!(!text.contains("secret-in-error-body"));
        assert!(!String::from_utf8_lossy(&out.stderr).contains("secret-in-error-body"));
        assert!(!journal(&home)
            .iter()
            .any(|v| v.to_string().contains("secret-in-error-body")));
    }

    #[test]
    fn e2e_cell_histories_share_presented_indexes_for_python_and_embedded_shell() {
        let source = r#"r=agent.sh('printf child')
assert r['cell']==1 and r['stdout']['index']==1 and r['stderr']['index']==1
assert r['stdout']['record_index']==0 and r['stdout']['record_ref']=='H.records.stdout[0]'
assert eval(r['stdout']['ref'])=='child' and eval(r['stdout']['record_ref'])=='child'
assert H.code[1].startswith("r=agent.sh") and H.stdout[1]=='child' and H.stderr[1]==''
assert H[1].code==H.cells[1].source and H[1].parent_cell is None
print('PARENT')"#;
        let inspect = r#"assert H.code[1]==H.records.code[0]
assert H.stdout[1]=='childPARENT\n' and H.stderr[1]==''
assert H.stdout[1:3]==['childPARENT\n',''] and H.stdout[:2]==['childPARENT\n']
assert H.stdout[-2:-1]==['childPARENT\n'] and H.stdout[::-1]==['','childPARENT\n']
assert H.code[2:1]==[] and H[-2].cell==1 and H.cells[-1].cell==2
assert len(H)==len(H.code)==len(H.stdout)==len(H.stderr)==len(H.events)==2
assert H.stdin[1]==H.stdin[2]==[] and H.say[1]==[]
assert H[1].stdout_complete and H[1].stderr_complete and not H[2].stdout_complete
assert H[1].record_indices['stdout']==[1]
assert H.records.stdout[:]==['child','childPARENT\n']
for view in (H,H.cells,H.code,H.stdout,H.stderr,H.user,H.stdin,H.say,H.requests,H.responses,H.usage,H.raw,H.events):
 for index in (0,3,-3):
  try:view[index]
  except IndexError:pass
  else:raise AssertionError((view,index))"#;
        let (events, home) = run(vec![py("cell-parent", source), py("cell-inspect", inspect)]);
        let parent = done(&events, "cell-parent");
        assert_eq!(parent["status"], "ok", "{events:?}");
        assert_eq!(parent["cell"], 1);
        for collection in ["code", "stdout", "stderr"] {
            assert_eq!(parent[collection]["index"], 1);
        }
        assert_eq!(parent["code"]["record_index"], 0);
        assert_eq!(parent["stdout"]["record_index"], 1);
        assert_eq!(done(&events, "cell-inspect")["status"], "ok", "{events:?}");
        let history = journal(&home);
        let starts = history
            .iter()
            .filter(|event| event["kind"] == "cell_start")
            .collect::<Vec<_>>();
        assert_eq!(
            starts
                .iter()
                .map(|event| event["payload"]["source_ref"].clone())
                .collect::<Vec<_>>(),
            vec![json!("H.code[1]"), json!("H.code[2]")]
        );
    }
