    #[test]
    fn e2e_busy_tty_slash_bang_control_replay_and_draft_survive() {
        fixture(
            r###"
import pty,select,fcntl,termios,struct
hidden=pathlib.Path(home,'tty-hidden');draft=pathlib.Path(home,'tty-draft');stale=pathlib.Path(home,'tty-stale')
codes[:]=['open('+repr(str(stale))+',"w").write("bad"); agent.final("tty-stale-final")','agent.final("tty-fresh-final")']
env['TERM']='xterm-256color'
master,slave=pty.openpty();fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',40,160,0,0))
p=subprocess.Popen([sys.argv[1]],stdin=slave,stdout=slave,stderr=slave,env=env);os.close(slave);data=bytearray()
def pump():
 ready,_,_=select.select([master],[],[],.02)
 if ready:
  try:data.extend(os.read(master,65536))
  except OSError:pass
def tty_wait(test,label):
 end=time.monotonic()+8
 while time.monotonic()<end:
  pump()
  if test():return
 raise AssertionError((label,bytes(data[-10000:]),records()[-15:]))
def send(text):os.write(master,text.encode())
idle=b'\x1b[>1u\x1b[?2004h'
tty_wait(lambda:idle in data,'idle editor')
send('fixture task\r');tty_wait(request_started.is_set,'busy provider starts')
send('/status\r');tty_wait(lambda:any(v['kind']=='local_command_completed' for v in records()),'local status completed')
send("!printf '\\033[35mTTY_CONTROL\\033[0m'; printf tty-hidden > "+shlex.quote(str(hidden))+'\r')
tty_wait(hidden.exists,'hidden shell executes while provider held')
send('!!printf tty-visible-marker\r')
tty_wait(lambda:len([v for v in records() if v['kind']=='cell_end'])==2,'visible shell completes while held')
assert not first_release.is_set() and not stale.exists()
assert b'\x1b[35mTTY_CONTROL\x1b[0m' in data,bytes(data[-10000:])
send('!printf unfinished_');first_release.set()
tty_wait(lambda:data.count(idle)>=2 and b'tty-fresh-final' in data,'final answer and idle editor')
send('tail > '+shlex.quote(str(draft))+'\r');tty_wait(draft.exists,'busy draft returns to idle editor')
assert draft.read_text()=='unfinished_tail'
assert not stale.exists() and len(requests)==2,requests
assert 'tty-visible-marker' in json.dumps(requests[1]) and 'TTY_CONTROL' not in json.dumps(requests[1]),requests[1]
assert b'queued steering' not in data and b'sent steering' not in data,bytes(data[-10000:])
no_local_steering([v['payload']['command_id'] for v in records() if v['kind']=='local_command_accepted'])
tty_wait(lambda:data.count(idle)>=3,'idle after draft shell');send('/quit\r')
assert p.wait(timeout=8)==0,bytes(data[-10000:]);os.close(master);srv.shutdown()
"###,
        );
    }

    #[test]
    fn e2e_busy_native_json_client_cannot_replay_controls_to_tty_output() {
        fixture(
            r###"
import pty,select
master,slave=pty.openpty();env['TERM']='xterm-256color'
p=subprocess.Popen([sys.argv[1],'--json-input'],stdin=subprocess.PIPE,stdout=slave,stderr=slave,env=env,text=True);os.close(slave);data=bytearray()
def send(id,kind='submit',**fields):p.stdin.write(json.dumps(dict(id=id,kind=kind,**fields))+'\n');p.stdin.flush()
def pump():
 ready,_,_=select.select([master],[],[],.02)
 if ready:
  try:data.extend(os.read(master,65536))
  except OSError:pass
def output_wait(test,label):
 end=time.monotonic()+8
 while time.monotonic()<end:
  pump()
  if test():return
 raise AssertionError((label,bytes(data[-10000:]),records()[-15:]))
output_wait(lambda:bool(glob.glob(home+'/sessions/*.jsonl')),'session ready')
send('turn',text='native client capability check');output_wait(request_started.is_set,'provider held')
send('native-flag',kind='shell',command="printf '\\033[35mCLIENT_GRANT\\033[0m'",terminal_controls=True)
output_wait(lambda:any(v['kind']=='cell_end' and v['payload']['language']=='shell' for v in records()),'native shell runs while busy')
assert not first_release.is_set()
# stdout really is a TTY and JSON-output mode is off. Only the input origin
# prevents replay; escaping JSON output cannot accidentally make this pass.
output_wait(lambda:b'CLIENT_GRANT' in data,'sanitized preview reaches tty')
assert b'\x1b[35mCLIENT_GRANT\x1b[0m' not in data,bytes(data[-10000:])
no_local_steering(['native-flag']);first_release.set()
output_wait(lambda:any(v['kind']=='cell_end' and v['payload']['language']=='python' for v in records()),'turn completes')
send('native-quit',kind='quit');p.stdin.close();assert p.wait(timeout=8)==0,bytes(data[-10000:]);os.close(master);srv.shutdown()
"###,
        );
    }

